window.__D("text/torat-shmuel/c037",{"p":[[2002180242,"ועד אחרית שנה, מרשית חסר כתיב, ולמדו רז\"ל מזה בגמ' ר\"ה דט\"ז ע\"ב א\"ר יצחק כל שנה שרשה בתחלתה מתעשרת בסופה שנאמר מרשית השנה ועד אחרית, סופה שיש לה אחרית, ע\"ד מ\"ש ואחריתך ישגה מאד כו' וע\"ד ויש תקוה לאחריתך כו', כי אחרית ע\"ה גימ' כתר<sup data-n=\"683\">3</sup>, ופרש\"י שרשה מתחלתה שישראל עושין עצמן רשין בר\"ה לדבר תחנונים ותפלה כענין שנאמר תחנונים ידבר רש, היוצא מזה שבר\"ה צריך להיות בחי' רש כו'.\n<b>ולהבין</b> זה י\"ל מקודם מ\"ש תפלה לדוד הטה ה' אזנך ענני כי עני ואביון אני, וי\"ל למה קרא עצמו עני, שהרי הי' חסיד ג\"כ וכמ\"ש אח\"כ שמרה נפשי כי חסיד אני ולמה קרא עצמו עני, שהרי באמת עני הוא היפך מדריגת החסיד<sup data-n=\"684\">4</sup>, שהרי ארז\"ל אין עני אלא בדעת וא\"כ איך הוא חסיד, ואם הוא חסיד לא יתכן שיקרא עצמו עני. וגם מהו ענין שאמר הטה ה' אזנך ענני כי עני ואביון אני, שמשמע שמה שמבקש שיטה ה' אזנו לענות לו על בקשתו זהו מחמת הטעם להיותו עני ואביון כו', ומהו גודל מעלת העני כ\"כ. גם י\"ל משארז\"ל יאה עניותא לישראל כברזא סומקא<sup data-n=\"685\">5</sup> לסוסיא חיורא, ובמד\"ר<sup data-n=\"686\">6</sup> ארז\"ל יאה מסכנותא לברתא דיעקב כעיזקא סומקא ברישי' דסוסיא חיורא, מהו המעלה של עניות כו'. אך הענין הוא דהנה כתיב ב\"פ תפלה, תפלה לעני כי יעטוף, ותפלה למשה איש האלקים, ואיתא בזהר מלמד שתפלה למשה ותפלה לעני כי יעטוף שניהם שוים, שגם בחי' תפלה לעני הוא ג\"כ שוה במדריגה לבחי' תפלה למשה כו'.\nב) <b>ובזה</b> יובן מ\"ש זה עני קרא וה' שמע, דלכאורה אינו מובן שהרי תיבת זה הוא מיותר שהי' צריך לכתוב עני קרא וה' שמע ולמה נאמר זה עני קרא, אלא לפי שזה קאי על משה, וכמשארז\"ל כל הנביאים נתנבאו בכה משה נתנבא בזה, וכתיב כי זה משה האיש, וכן איתא במנחות יבא זה ויקבל זאת מזה לעם זו, שמשה נק' זה, וזהו זה עני קרא וה' שמע דהיינו שזה שהוא משה היינו תפלה למשה, ועני היינו תפלה לעני קרא וה' שמע שניהם שוים ממש כנ\"ל. ועוי\"ל זה עני שהגם שהוא בבחי' זה בחי' עשיר, זה תפארת בחי' עשיר אספקלריא המאירה, מ\"מ קורא עצמו",[["683","3","<b>אחרית ע\"ה </b> [ עם הכולל]<b> גימ' כתר</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380128\" data-slug=\"likkutei-torah\" data-id=\"4001380128\">לקו\"ת צו יג, א</a>. אוה\"ת ויחי שנח, ב (בשם המאו\"א). דרושים לר\"ה שם ע' א'שצג. סה\"מ תרכ\"ז ע' תכח. תרל\"ב ח\"א ע' לה."],["684","4","<b>עני הוא היפך מדריגת החסיד</b>: בד\"ה ארשב\"נ תר\"צ שם מבאר זה: שהעני הוא מוכנע ושפל בטבעו, וחסיד הוא תקיף ומרומם בטבעו כו', וכן בענין המוחין הרי מדרי' חסיד הוא שיש לו ידיעה והשגה בענין אלקי, ועני ארז\"ל אין עני אלא בדעת."],["685","5","<b>משארז\"ל יאה עניותא לישראל כברזא סומקא</b>: בגמ' (חגיגה ט, ב): ”יאה עניותא ליהודאי\". — וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380847\" data-slug=\"likkutei-torah\" data-id=\"4001380847\">לקו\"ת ראה לג, א</a>. שה\"ש נא, סע\"ג."],["686","6","<b>ובמד\"ר . . כעיזקא סומקא ברישי' דסוסא חיורא</b>: בויק\"ר (פל\"ה, ו [הובא בד\"ה תפלה לעני באוה\"ת דרושים לר\"ה שם]): ”כערקא סומקא ברישא דסוסא חיורא\". [ובפי' המ\"כ שם: נאה ויפה העניות לבת יעקב כרצועה אדומה בראש סוס לבן]. ושם פי\"ג, ד: ”כעזקתא סומקתא דעל ליביה דסוסא חיורא\". וראה גם שהש\"ר פ\"א ע\"פ משכני."]]],[2002180243,"עני, פי' עני ע\"ד מ\"ש עני ונכה רוח, ולכאורה משמע שהם ב' בחי', ובאמת הכוונה שאינו עני בעצם היינו בחי' עני בדעת, אלא שהגם שהוא עשיר עכ\"ז מחזיק עצמו לעני בדעת לפי שהוא נכה רוח ושפל בעיני עצמו כמ\"ש והייתי שפל בעיני כו', וע\"ד משימים עצמם כבהמה שאין לה דעת וכמ\"ש אדם ובהמה וארז\"ל בני אדם שהם ערומים בדעת כאדם ומשימי' עצמם כבהמה בחולין ד\"ה ע\"ב, ופרש\"י כבהמה דכי הרוח, והיינו כעני שהוא נכה רוח. ועמ\"ש בס' במדבר בד\"ה ומקנה רב<sup data-n=\"687\">7</sup> בענין אני חכמה שכנתי ערמה, ומשם יובן ענין ערומים בדעת, ומ\"מ להיותם דכי הרוח משימים עצמם כבהמה היינו בהמה רבה כו'. ופעם איתא בזהר שתפלת העני קודם לתפלה למשה, וראייתו מתפילין של יד ותפילין של ראש, שתפלה של יד נק' תפלה לעני לפי שתפילין של יד הוא על יד כהה, ויד כהה לגבי יד ימין נק' עני לפי שחסרה כח נגד יד ימין, כמו העני שחסר נגד העשיר, ותפלה של ראש הוא בחי' תפלה למשה, ואעפ\"כ מקדימין תפילין של יד לתפלה של ראש. ולכאורה אינו מובן למה תפלה לעני קודם לתפלה למשה, שהרי אף לפי דעה זו שנת\"ל ששניהם שוין ג\"כ אינו מובן למה יהיו שניהם שוים, וכ\"ש שתפלה לעני יהי' לזה מעלת הקדימה שזה אינו מובן לכאו' למה הי' תפלת העני קודם כו'.\n<b>אך</b> הענין הוא דהנה מתחלה י\"ל למה ברא הקב\"ה עניים<sup data-n=\"688\">8</sup>, והעני צריך לקבל מהעשיר, למה לא ברא שיהיו הכל שוים, ולכה\"פ שלא יצטרך העני לקבל מהעשיר אלא שיקבלו כולם השפעתם מלמעלה כו'. והגמ' משני לפי שנא' מלוה ה' חונן דל שחונן דל הוא מלוה ה'<sup data-n=\"689\">9</sup>, נמצא שמה שנותן הרי הוא מלוה להקב\"ה, שהרי הקב\"ה הי' צריך ליתן להעני המצטרך לו, והעשיר הנותן לו הרי הוא מלוה להקב\"ה ונותן לעני תמורת זה מה שהקב\"ה הי' צריך ליתן בעצמו להעני, ואח\"כ משלם הקב\"ה לעשיר בתוס' מרובה וכמארז\"ל ע\"פ עשר תעשר עשר בשביל שתתעשר. וגם זה אינו מובן למה צריך הקב\"ה ללוות ממנו ואח\"כ לשלם לו, הי' לו לכתחלה ליתן לעני ולא הי' צריך הקב\"ה ללוות מהעשיר. אך ברבות משני כדי שיזכו זה לזה, שכשם שהעשיר מזכה להעני כך העני מזכה לעשיר וכמ\"ש ברות אשר עשיתי עמו<sup data-n=\"690\">10</sup>, והיינו שעי\"ז יש זכות ומצוה לעשיר כו'.",[["687","7","<b>ועמ\"ש בס' במדבר בד\"ה ומקנה רב</b>: אוה\"ת מטות ע' א'שמג. וראה גם סה\"מ תרל\"ג ח\"א ס\"ע מד-ה. וש\"נ. וראה להלן בהנחת כ\"ק אדמו\"ר מהורש\"ב נ\"ע ממאמר זה."],["688","8","<b>אך הענין הוא . . למה ברא הקב\"ה עניים</b>: בהבא לקמן ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450551\" data-slug=\"or-hatorah-hb\" data-id=\"8316450551\">אוה\"ת עקב ע' תקנא</a>."],["689","9","<b>והגמ' משני לפי שנא' מלוה ה' חונן דל שחונן דל הוא מלוה ה'</b>: ז\"ל הגמ' (ב\"ב י, א): ”שאל כו' את ר\"ע אם אלקיכם אוהב עניים מפני מה אינו מפרנסם\". ובהמשך הגמ' שם: ”אר\"י מאי דכתיב מלוה ה' חונן דל, אלמלא מקרא כתוב אי אפשר לאומרו כביכול עבד לוה לאיש מלוה\". וראה חדא\"ג מהר\"ל מפראג שם: פי' מה שעבד לוה לאיש מלוה מפני כי הוא משועבד אליו לפרעון החוב ולזאת נק' הלוה עבד לאיש מלוה בשביל השעבוד הזה והכתוב אומר מלוה ה' כאשר חונן דל, כי על השי\"ת להשלים את העולם שהוא בראו והוא ברא את העני וצריך לפרנסו, ולפיכך מי שחונן את הדל הוא מלוה אל הקב\"ה."],["690","10","<b>וכמ\"ש ברות אשר עשיתי עמו</b>: ראה רות רבה פ\"ה, ט (ועד\"ז בויק\"ר לד, ח): יותר ממה שבעה\"ב עושה עם העני, העני עושה עם בעה\"ב, שכן אמרה רות לנעמי שם האיש אשר עשיתי עמו היום ולא אמרה אשר עשה עמי כו' הרבה פעולות והרבה טובות עשיתי עמו בשביל שהאכילני פרוסה אחת."]]],[2002180244,"ג) <b>והנה</b> באמת זה שנבראו עניים יש בזה כוונה עמוקה, דהנה למעלה בכל סדר השתלשלות יש בחי' משפיע ומקבל, דהנה כל סדר השתל' הוא בדרך משפיע ומקבל, כמו בחי' זו\"נ דאצי' שבחי' ז\"א הוא משפיע לנוק', ועד\"ז למעלה יותר בבחי' חו\"ב הוא ג\"כ בדרך משפיע ומקבל, שחכ' נק' אב הוא בחי' משפיע ובינה היא בחי' אם בחי' מקבל, ועמ\"ש בע\"ח<sup data-n=\"691\">11</sup> שער י\"א הוא שער עתיק יומין פ\"א, וז\"ל כי עת\"י דאצי' כל עצמותו נעשה משני בחי' אלו מ\"ה וב\"ן, מ\"ה שבו הוא בחי' עתיק דדכורא, וב\"ן שבו הוא בחי' נוק' דעתיק. ונמצא כי גם בע\"ק הוא בחי' משפיע ומקבל, ואפי' בכלליות ההשתל' בחי' הק\"ו הוא ההשפעה הנמשכת מא\"ס ית' שלפני הצמצום כו'. ובחי' משפיע ומקבל שבשמות היינו שם הוי' ושם אלקים, שם הוי' הוא בחי' משפיע, ושם אלקים ושם אד' הם בחי' מקבל. וכמ\"ש וה' בהיכל קדשו היכל בגימ' אד', כוס בגימ' אלקים<sup data-n=\"692\">12</sup>. ולפי שיש למעלה בחי' משפיע ומקבל ע\"כ הוכרח שיהי' למטה ג\"כ בחי' משפיע ומקבל בחי' עשיר ועני כו', וע\"י יחוד עשיר ועני בחי' משפיע ומקבל למטה עי\"ז נעשה למעלה ג\"כ בחי' יחוד משפיע ומקבל יחוד שם הוי' בשם אלקים. ובזהר נק' זה בשם יחוד שמשא וסיהרא, דהנה סיהרא נק' בשם עני, דסיהרא לית לה מגרמה כלום, שאין לה שום אור בפ\"ע כ\"א שמקבלת מאור השמש. וזהו פני משה כפני חמה ופני יהושע כפני לבנה<sup data-n=\"693\">13</sup>, לפי שמשה הי' משפיע לבד ולא הי' מקבל משום אדם, והגם שהי' מקבל תורה כמארז\"ל משה קיבל תורה מסיני, אך זהו שהי' מקבל רק מלמעלה לבד שהי' מקבל משם הוי', אבל למטה לא הי' מקבל כ\"א משפיע לבד. אבל יהושע הי' מקבל ממשה, ולזה זקנים שבאותו הדור אמרו אוי לאותה בושה אוי לאותה כלימה, לפי שאין ערך אור השמש לאור הלבנה. נמצא ששרש העני והעשיר נמשך משמשא וסיהרא, ולפי שסיהרא לית לה מגרמה כלום ע\"כ עני לית לי' מגרמי' כלום. אך המכוון ממה שסיהרא לית לה מגרמה כלום זהו בכדי שיהי' יחוד שמשא וסיהרא. וזה המכוון נגמר ע\"י השפעת העשיר לעני וזיכוי מה שהעני מזכה להעשיר, כי ע\"י שנעשה יחוד עני ועשיר עי\"ז נעשה למעלה ג\"כ<sup data-n=\"694\">14</sup> יחוד שמשא בסיהרא כו'. ובזה יובן מה שתפלה לעני קודם לתפלה למשה, והיינו",[["691","11","<b>ועמ\"ש בע\"ח</b>: ראה גם אוה\"ת ויקרא (כרך ב) ע' תק. סה\"מ תרכ\"ו ע' עז."],["692","12","<b>ושם אלקים ושם אד' הם בחי' מקבל . . היכל בגימ' אד', כוס בגימ' אלקים</b>: ר\"ל שהיכל וכוס שניהם בחי' כלים ומקבלים. וראה מאמרי אדה\"ז הקצרים ע' תל: היכל אותיות הכלי."],["693","13","<b>וזהו פני משה כפני חמה ופני יהושע כפני לבנה</b>: ראה בארוכה סה\"מ תרל\"ג ח\"ב ע' תכ ואילך. [ובהנסמן שם בתחילת המאמר]."],["694","14","<b>וזה המכוון נגמר ע\"י השפעת העשיר לעני . . עי\"ז נעשה למעלה ג\"כ</b>: בד\"ה ארשב\"נ תר\"צ שם מתרץ כאן את הקושיא דלעיל (פ\"ב): ”וזהו דאי' בזהר דתפלה לעני ותפלה למשה שניהם שוים, דתפלה למשה שהוא כו' תפלת עשיר משפיע, ותפלה לעני מקבל הרי שניהם שוים לפי שע\"י עני ועשיר נשלם כללות הסדר דמשפיע ומקבל ונמשך שפע רב בכל העולמות\". וממשיך: ”אך א\"כ אינו מובן למה תפלת עני עוד גדלה מתפלת עשיר, אך הענין הוא דהנה כתי' תפלה לעני . . . [כדלקמן בפיסקא שלאח\"ז]."]]],[2002180245,"לפי שע\"י עני ועשיר נשלם המכוון שיהי' יחוד שמשא וסיהרא, והנה עי\"ז צריך העני לסבול יסורים וצער.\n<b>וזהו</b> מ\"ש תפלה לעני כי יעטוף ולפני ה' ישפוך שיחו, שיחו הוא מלשון תרעומות, שיש לעני תרעומות על הקב\"ה למה צריך הוא לסבול צער ויסורים ויקבל מעשיר, שבאמת אנו רואים שיש עניים הרבה שהם טובים מעשירים, ואעפ\"כ צריך לקבל מהעשיר, וכמ\"ש בגמ' רב חסדא ורבה<sup data-n=\"695\">15</sup> תרווייהו צדיקי גמורי נינהו, ולרב חסדא סמידתא לכלבא לא מתבעי, ורבה לא הוה לי' קמחא דשערי אפילו ללחם, כי באמת מזוני לאו בזכותא תליא אלא במזלא תליא<sup data-n=\"696\">16</sup>, מזל הוא בחי' גבוה מאד, דהיינו בחי' מזלא דא\"א שהוא למעלה מן השכל וטו\"ד, ולפי שזה שהוא עני ואין לו כלום הוא בלי טעם, ע\"כ יש לעני תרעומות גדולה למה הוא צריך לסבול זה, דהן אמת שמוכרח שיהיו עניים שעי\"ז יומשך יחוד שמשא בסיהרא, אבל מפני מה הוא העני והרי הוא מתרעם מדוע לא יהי' העשיר עני, והעני עשיר, ועד\"ז יוכל כל עני להתרעם מדוע הגיע לחלקו שיהי' הוא העני כו'. אך אעפ\"כ בכלל מההכרח שיהיו עניים כו', דהנה כתי' הרם כשופר קולך כמו ששופר צדו א' קצר<sup data-n=\"697\">17</sup> וצדו הא' רחב ע\"ש מן המיצר קראתי י\"ה ענני במרחב י\"ה שצריך להיות מן המיצר דוקא דהיינו שיהי' מיצר לו בבחי' פנימית ממש. והענין הוא דהנה איתא בת\"ז לית מחשבה תפיסא בי' כלל, פי' מחשבה הוא בחי' חכ' כמ\"ש בזהר פ' חיי מח' ויובלא דלא אתפרש לעלמין, אבל נתפס הוא ברעו\"ד<sup data-n=\"698\">18</sup> דהיינו בבחי' רצון פשוט, דהנה אית רצון ואית רצון, אית רצון שע\"פ שכל וטעם ואית רצון שלמעלה מן השכל וטו\"ד, והנה ברצון שעפ\"י שכל א\"א להשיג באלקות, אבל ברעו\"ד שהוא בחי' רצון שלמעלה מן השכל נתפס עצמות אוא\"ס ממש, וזהו מן המיצר קראתי י\"ה דהיינו מבחי' מיצר שהוא בחי' רצון פשוט כו'.\nד) <b>והנה</b> כדי להגיע לבחי' מיצר זה יכול העני להגיע יותר, וכמ\"ש רעבים גם צמאים נפשם בהם תתעטף ויצעקו אל ה' בצר להם, שע\"י רעבים גם צמאים עי\"ז ויצעקו אל ה' בצר להם כו' וכמארז\"ל במד\"ר באיכה צריך יהודאי",[["695","15","<b>וכמ\"ש בגמ' רב חסדא ורבה</b>: במו\"ק כח, א: חיי בני ומזוני כו' במזלא תליא מילתא דהא רבה ור\"ח תרווייהו רבנן צדיקי הוו כו' בי ר\"ח סמידא לכלבי ולא מתבעי בי רבה נהמא דשערי לאינשי ולא משתכח."],["696","16","<b>מזוני לאו בזכותא תליא אלא במזלא תליא</b>: ראה בארוכה סה\"מ תרל\"ג ח\"א ע' רלח-ט. וש\"נ. ס\"ע רמז-ח."],["697","17","<b>דהנה כתי' הרם כשופר קולך . . צדו א' קצר</b>: בהבא לקמן פיסקא זו ראה בארוכה מאמרי אדה\"ז תקס\"ג ח\"א ע' קצז. אוה\"ת דרושים לפ' זכור ע' א'תשעג. שם (כרך ז) ע' ב'תשעו."],["698","18","<b>לית מחשבה תפיסא בי' כלל . . אבל נתפס הוא ברעו\"ד</b>: ראה בארוכה סה\"מ תרכ\"ט ס\"ע שעט ואילך. לקמן ד\"ה ויקהלו אל המלך שלמה [ובהנסמן שם בתחילת המאמר]. ובמקומות שנסמנו בהערה שלפנ\"ז."]]],[2002180246,"לחרובא עביד תשובה<sup data-n=\"699\">19</sup>, בבחי' רצון פשוט, ולפי שהעני מגיע יותר לבחי' מיצר עי\"ז תפלה לעני קודם לתפלה למשה, ומה גם שטענתו חזקה בתערומת הנ\"ל למה יגרע חלקו שיהי' הוא העני, מאחר שגם קיום העשיר א\"א להיות כ\"א כשיהיו עניים דוקא, שהרי בכלליות ההשתלשלות הוא בדרך משפיע ומקבל וכנ\"ל, וא\"כ גדלה צעקתו וטענתו חזקה מדוע הגיע לחלקו שיהי' הוא העני, ומה ראו על ככה כו', ולכן תפלתו קודמת להיות בא בטענה חזקה כנ\"ל, ולהיות כי לפ\"ד הנכון עמו, והאמת כן הוא, והעניות שלו הוא מחמת שבסדר השתלשלות צ\"ל כן ולא בחטאו בא, לכן יותר יכאב לבו מדוע הגיע לו ככה, ועי\"ז יוכל לבוא יותר לבחי' המיצר להיות צעק לבם אל הוי' בבחי' רצון פשוט, ועי\"ז תפלתו קודמת. ועמ\"ש בד\"ה ציון במשפט<sup data-n=\"700\">20</sup> מענין ה' בצר פקדוך צקון לחש מוסרך למו, ממ\"ש בזהר בשלח אימת מוסרך למו בשעתא דפקיד לון קוב\"ה ברצועה, וחמו ימא סעיר וגלגלוהי זקפין ומאחוריהם פרעה ואבני גירין ובלסטראין כדין ויצעקו אל ה'. וזהו תפלה לעני כי יעטוף, יעטוף הוא ל' עטופים, ובהעטיף הצאן, והיינו שמתעטף א\"ע מחמת שהוא מיצר לו<sup data-n=\"701\">21</sup> עד שאין מקום לו כלל. והנה כתיב כי רוח מלפני יעטוף, ופרש\"י שהוא ע\"ד תפלה לעני כי יעטוף, והיינו כי רוח קאי על נשמות שיהי' כל א' בבחי' יעטוף<sup data-n=\"702\">22</sup> דהיינו בבחי' רצון פשוט שהוא בחי' עני כמשי\"ת כו'.\n<b>ובעבודה</b> בנפש האדם הנה ארז\"ל כל המנבל א\"ע הקב\"ה מגביהו<sup data-n=\"703\">23</sup>, והיינו כשהוא מנבל א\"ע להתמרמר על ריחוקו מה' אחד כי ידע אינש בנפשו עוצם ריחוקו מה', והיינו כשמתבונן איך שירדה נפשו האלקית פלאים להתלבש בגוף ונה\"ב, שמתחלה היתה עומדת באהוי\"ר כמ\"ש חי ה' אשר עמדתי לפניו, שהיתה עומדת באהוי\"ר ודבוקה בה' אחד, וגם נפשו הבהמי' נלקחה מפני שור שבמרכבה שגם הם עומדים ברום עולם ומשמיעים ביראה, ואומרים קדוש וברוך, וכאשר מתלבשת הנשמה בגוף ונה\"ב הנה לא די מה שהיא עצמה איננה חפיצה ליכלל בה' אחד, הנה היא מקררת גם הנה\"א שיומשך אחר תענוגים גשמי' ולשכוח על ה' אחד ממכ\"ע וסוכ\"ע. וזהו<sup data-n=\"704\">24</sup> שאומרים בתפלה סלח לנו כי חטאנו, דלכאורה צ\"ל מפני מה",[["699","19","<b>וכמארז\"ל במד\"ר באיכה צריך יהודאי לחרובא עביד תשובה</b>: בד\"ה תפלה לעני באוה\"ת דרושים לר\"ה שם מציין לשהש\"ר פ\"א ע\"פ משכני [ובמ\"כ שם: צריך היהודי לחיי צער ודוחק עד שאין לו לאכול רק חרובין אז מקבל מרות ועושה תשובה]. וראה גם ויק\"ר פי\"ג, ד. פל\"ה, ו."],["700","20","<b>ועמ\"ש בד\"ה ציון במשפט</b>: אוה\"ת ויצא רטז, סע\"א-ב. דברים ע' מא-ב. שם (כרך ו) ע' ב'תרה. נ\"ך (כרך ג) ע' א'קצד."],["701","21","<b>וזהו תפלה לעני כי יעטוף . . שמתעטף א\"ע מחמת שהוא מיצר לו</b>: ראה בביאור יותר בד\"ה ארשב\"נ תר\"צ שם: דיעטוף הוא כיסוי והלבשה כו' שהעני עטוף ר\"ל ביסורים וצער כו' עד שאין לו מקום כלל. ובד\"ה תפלה לעני באוה\"ת דרושים לר\"ה שם ע' א'שצז: שצרת הרעבון מלבשת לבו ומוחו כ\"כ עד שא\"א לו להתלבש במח' אחרת."],["702","22","<b>כי רוח מלפני יעטוף ופרש\"י . . רוח קאי על נשמות שיהי' . . בבחי' יעטוף</b>: ז\"ל רש\"י עה\"פ (ישעי' נז, טז): כי רוח מלפני יעטוף כאשר רוח האדם שהוא מלפני שניתן בו מאתי יעטוף [את האדם] יודה ויכנע על מעלו. עיי\"ש עוד. [הובא בד\"ה תפלה לעני באוה\"ת דרושים לר\"ה שם]."],["703","23","<b>ארז\"ל כל המנבל א\"ע הקב\"ה מגביהו</b>: ראה ברכות סג, ב: כל המנבל עצמו על דברי תורה סופו להתנשא. ובעירובין יג, ב: כל המשפיל עצמו הקב\"ה מגביהו. [הובאו בד\"ה ארשב\"נ תר\"צ שם]."],["704","24","<b>וזהו שאומרי' בתפלה סלח לנו . . מפני מה אומרים זה בשמו\"ע</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380431\" data-slug=\"likkutei-torah\" data-id=\"4001380431\">לקו\"ת בהעלותך ל, ב</a>. תצא לא, סע\"ב. דרושים לשבת שובה סה, ג. סה\"מ תרכ\"ז ע' רנ-א. לעיל ד\"ה וידבר גו' זאת חוקת."]]],[2002180247,"אומרים זה בשמו\"ע, שהי' מהנכון לומר כן קודם התפלה שקודם שיתחיל להתפלל יתוודה על חטאותיו. אך הענין הוא דהנה קודם התפלה דרך איש ישר בעיניו שמאחר שאינו עושה עבירה בפו\"מ ומקיים ג\"כ מצות הרי הוא בעיני עצמו נחשב לצדיק גמור, אבל ע\"י התפלה כשמתחיל תחלה הודו לה' קראו בשמו שמתחיל להודות הגם כי איננו מבין שכן הוא, ואח\"כ ע\"י פסוד\"ז שמזמר עריצים ומכרית כל החוחים והקוצים אז אח\"כ בברכת ק\"ש כשמתבונן בשרשו ומקורו איך שגם שרש ומקור הנה\"ב ג\"כ בטל לאלקות, שעי\"ז מתעורר בנפשו הבהמית ג\"כ בחי' ביטול ולכה\"פ שלא תעכב את נפשו האלקי', אז יוכל למס\"נ בק\"ש בה' אחד, ואחרי אשר פועל ישועות בנפשו שיוכל לבוא לידי רצון פשוט ליכלל בה' אחד הסוכ\"ע אזי רואה איך שהוא רחוק מאלקות בתכלית לכן אומר סלח לנו כי חטאנו, משא\"כ קודם התפלה. והנה כשמתבונן בכ\"ז יתמרמר לבו ונפשו בקרבו על עוצם ריחוקו מה' אחד, אזי הוא נבזה בעיניו נמאס ומשפיל א\"ע מאד עד קצה האחרון ממש, ולזה ארז\"ל כל המנבל א\"ע הקב\"ה מגביהו פי' כשמשפיל א\"ע עד קצה האחרון הקב\"ה שהוא סוכ\"ע שאין בו מעלה ומטה מגביהו, וע' מענין זה בד\"ה לא תחרוש בשור<sup data-n=\"705\">25</sup> ובחמור יחדיו, ובד\"ה וירא ישראל שלא נדפס<sup data-n=\"706\">26</sup>, ונמצא כי ע\"י העוני שמתבונן איך שהוא רחוק מאלקות שכמו העני ביתו ריקם מכל כך הוא ריקם מבחי' המשכת אלקות בנפשו, וע\"י שפלות ומרירות זו הקב\"ה שהוא סוכ\"ע מגביהו, נמצא כי ע\"י העוני בא לבחי' סוכ\"ע כו'.\nה) <b>והנה</b> י\"ל עוד יעטוף הוא לשון הטפה והזלה מלמעלמ\"ט כו', והענין הוא דהנה כתיב אם ישים אליו לבו רוחו ונשמתו אליו יאסוף, מלמעלה למטה, דהיינו כמו שלמטה בנפש האדם יש נר\"נ, כך למעלה יש נפש רוח ונשמה, וכמ\"ש נשבע ה' בנפשו, נפש הוא בחי' ממכ\"ע שמחי' את העולמות וכמ\"ש והר סיני עש\"ן ר\"ת עולם שנה נפש<sup data-n=\"707\">27</sup>, שנפש היא חיות העולמות שהוא בחי' ממכ\"ע כי הדם הוא הנפש, ורוח הוא בחי' סוכ\"ע, וזהו מ\"ש בדור המבול לא ידון רוחי באדם לעולם, לפי שקודם דור המבול הי' מאיר בחי' רוח ולכך הי' בהם אריכות ימים שהיו חיים קרוב לאלף שנה, אך אחר חטא דור המבול נאמר לא ידון רוחי שהוא בחי' סוכ\"ע והיו ימיו מאה ועשרים שנה לפי שאינו מאיר בחי' רוח רק בחי' נפש, והנה מה שאינו מאיר בחי' רוח זהו כשלא יש בחי' העלאה בבחי' רצון פשוט ממטה למעלה, ואז אינו מאיר מלמעלה ג\"כ בחי' רוח, אבל אם ישים אליו לבו מלמטלמ\"ע בחי' רצון פשוט, אז נמשך מלמעלה ג\"כ בחי' רוח, אם ישים אליו לבו רוחו ונשמתו אליו יאסוף. וזהו",[["705","25","<b>בד\"ה לא תחרוש בשור</b>: סה\"מ תרכ\"ז ע' ת-תא."],["706","26","<b>ובד\"ה וירא ישראל שלא נדפס</b>: <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8315950463\" data-slug=\"or-hatorah-hb\" data-id=\"8315950463\">אוה\"ת בשלח ע' תלה</a>. וע' תסג [והוא דרוש אדה\"ז מש\"פ בשלח תקס\"ד בתוס' הגהות מהצ\"צ]. וראה גם סידור עם דא\"ח לא, רע\"א. סה\"מ תרכ\"ז שם ע' רנא."],["707","27","<b>וכמ\"ש והר סיני עש\"ן ר\"ת עולם שנה נפש</b>: ראה בארוכה סה\"מ תרכ\"ז ע' צט-ק. וש\"נ. תרל\"ח ע' כ. וש\"נ. וע' מג. וש\"נ."]]],[2002180248,"מ\"ש כי ידין ה' עמו ועל עבדיו יתנחם, ופי' כי ידין ה' עמו היינו מה שנאמר בדור המבול לא ידון רוחי, אבל עמו ידין ה' שיהי' מאיר בחי' רוח, כי א\"א לומר שידין ה' עמו היינו כמשמעו, שהרי נאמר ועל עבדיו יתנחם (ומחמת זה ת\"א וכן ת\"י בהאזינו וכן פרש\"י בתילים סי' קל\"ו כי ידין ה' דין עמו) אלא ע\"כ מה שנאמר כי ידין ה' עמו היינו שיהי' ידין רוחו מה שנאמר בדור המבול לא ידון רוחי, אבל ע\"י אם ישים אליו לבו ידון רוחי, וזהו כי רוח מלפני יעטוף שיהי' בבחי' הטפה והזלה מלמעלה בחי' רוח כו' שהוא בחי' סוכ\"ע.\n<b>וזהו</b> מ\"ש תפלה לעני כי יעטוף דהיינו שע\"י הטפה והתפלה לעני עי\"ז כי יעטוף דהיינו שעי\"ז נמשך בחי' רוח שהוא בחי' סוכ\"ע, והיינו לפי שתפלת העני מגיע למעלה בבחי' סוכ\"ע. ולזה אמר דהע\"ה ע\"ע כי עני ואביון אני כו' לפי שתפלת העני הוא בחי' גבוה מאד, ונמצא הגם כי קרא עצמו חסיד מ\"מ קרא עצמו עני ג\"כ וכנ\"ל בענין אדם ובהמה בני אדם שהם ערומים בדעת כאדם ומשימים עצמם כבהמה, ונמצא יש לו ב' המעלות של עשיר ועני. ומה שנת\"ל בענין תפלת העני והעשיר ששניהם שוים זהו ע\"ד שיהי' לע\"ל זו\"נ שוין בקומתן, ועד\"ז עכשיו תפלתם שוין. ולפי מ\"ש שתפלת העני קדמה, זהו מפני שבטענתו הנכון עמו כנ\"ל וגם שהוא ממשיך מבחי' סוכ\"ע, וזהו יאה עניותא לישראל כו' לפי שעי\"ז נמשך כי ידין ה' עמו, וזהו ענין שנקראו ישראל עם עני וכמ\"ש ואת עם עני תושיע כו', תושיע בחי' שע\"ה נהורין."],[2002180249,"<h3>ומעתה צ\"ל מה שר\"ה (וא\"ו-יו\"ד) (ב)</h3>\n<b>בס\"ד.</b>\nוא\"ו) <b>ומעתה</b> י\"ל<sup data-n=\"708\">1</sup> מה שר\"ה צ\"ל בבחי' רשה בתחלתה, והענין הוא דהנה ארז\"ל בך\"ה באלול נבה\"ע וביום ששי נברא אדה\"ר, ור\"ה עושין ביום שנברא אדה\"ר, וידוע הקושיא למה אין עושין ר\"ה בתחלת הבריאה דהיינו בך\"ה באלול שנבה\"ע. אך הענין הוא דהנה ארז\"ל בתחלה עלה במח' לברוא את העולם במדה\"ד ראה שאין העולם מתקיים שיתף עמו מדה\"ר, וזהו שבתחלת הבריאה לא נאמר כ\"א שם אלקים, בראשית ברא אלקים, ואח\"כ נאמר ביום עשות הוי' אלקים ארץ ושמים, והיינו לפי שבתחלת הבריאה עלה במח' לברוא העולם במדה\"ד, והנה ש' אלקים הוא מדה\"ד וצמצום, אך ראה שאין העולם מתקיים שיתף עמו מדה\"ר",[["708","1","<b>ומעתה י\"ל . . ארז\"ל בך\"ה באלול נבה\"ע</b>: מאמר זה הוא בהמשך לד\"ה תקעו בחודש הנדפס לעיל. וראה בהנסמן שם לכללות המאמר.\nבהבא לקמן (פרקים ו-ח) ראה ד\"ה תקעו בחודש ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380938\" data-slug=\"likkutei-torah\" data-id=\"4001380938\">לקו\"ת</a> דרושים לר\"ה שם נד, סע\"ד ואילך."]]],[2002180250,"שהוא שם הוי' כו'. וי\"ל למה בתחלת הבריאה עלה במח' לברוא את העולם במדה\"ד ולא נברא במדה\"ר.\n<b>אך</b> הענין הוא, דהנה כתיב כי שמש ומגן הוי' אלקים<sup data-n=\"709\">2</sup>, והיינו כמו למשל שהשמש<sup data-n=\"710\">3</sup> צריך למגן ונרתק וכמ\"ש לשמש שם אהל בהם, והיינו לפי שאם הי' מאיר השמש בלי מגן ונרתק לא היו יכולים לקבל את תוקף אור השמש כו', וע\"י המגן עי\"ז יכולים לקבל את אור השמש, ואז יכולים ליהנות מהאור כו', וכך ש' הוי' וש' אלקים הוא ג\"כ בחי' שמש ומגן, ששם הוי' נק' שמש ושם אלקים נק' מגן ונרתק, והיינו לפי שש' הוי' הוא בחי' מהוה, אך אם הי' ההתהוות ע\"י ש' הוי' לבד לא היו יכולים להתהוות עולמות בבחי' יש ודבר נפרד כמו שהן עתה, אלא שהיו בטלים בתכלית הביטול כביטול זיו השמש בשמש, וכדי שיתהוה עולמות בבחי' יש ודבר נפרד זהו ע\"י ש' אלקים שמסתיר ומעלים על ש' הוי', הגם כי הוי' הוא האלקים כולא חד וגם ש' אלקים הוא מז' שמות שאינן נמחקין, אעפ\"כ הוא בחי' שם המעלים ומסתיר עד שנתהוו בחי' בריאה מאין ליש, כי באמת כח המסתיר הוא ג\"כ אלקות כמו כח הנגלה כו' ע' בד\"ה מהיכן זכו ישראל לק\"ש<sup data-n=\"711\">4</sup> מיעקב. והענין הוא דהנה כתיב כי אל דעות הוי', שיש שני דעות ד\"ע וד\"ת<sup data-n=\"712\">5</sup>, ד\"ע הוא איך דכולא קמי' כלא חשיב, וד\"ת הוא מה שהבריאה היא יש מאין, ונמצא כי גם בחי' ד\"ת נמשך מלמעלה שהרי הוא ית' הוא אל שכולל ב' דיעות אלו, שנמצא גם בחי' ד\"ת הוא מלמעלה כו'. ופי' מאין ליש שהרי ממך הכל כתיב<sup data-n=\"713\">6</sup> ובאמת למעלה הוא בחי' יש וכמ\"ש להנחיל אוהבי יש, ולמטה הוא כלא וכאין כו', אך הפי' מאין ליש<sup data-n=\"714\">7</sup> היינו שלעינינו נראה ליש ודבר נפרד, והחיות המחי' אינו מושג לנו וכמ\"ש שאו מרום עיניכם וראו מי ברא אלה, מי היינו שאינו מושג לנו, ולפי שאם הי' ההתהוות ע\"י ש' הוי' לבד הי' מאיר אלקות בבחי' גילוי ממש והי' בבחי' השגה וגילוי, אך לפי שמי ואלה הוא אותיות אלקים שהוא מסתיר ומעלים את החיות אלקות המחי' כו', ולכך אינו מושג לנו, ולזה נק' הבריאה מאין ליש כו'.",[["709","2","<b>דהנה כתיב כי שמש ומגן הוי' אלקים</b>: בהבא לקמן ראה שעהיוה\"א פ\"ד. רשימות הצ\"צ לתהלים (יהל אור) ע' ש ואילך. וראה גם לעיל ד\"ה ארע\"ק אשריכם ישראל."],["710","3","<b>שהשמש צריך למגן ונרתק וכמ\"ש לשמש שם אוהל בהם</b>: ראה רשימות הצ\"צ לתהלים שם ע' שא. סה\"מ תרל\"ג ח\"א ס\"ע סט. וש\"נ."],["711","4","<b>בד\"ה מהיכן זכו ישראל לק\"ש</b>: סה\"מ תרכ\"ז ס\"ע שפד-ה."],["712","5","<b>דהנה כתיב כי אל דעות הוי' . . ד\"ע וד\"ת</b>: בהבא לקמן ראה בארוכה לעיל ד\"ה מזמור לתודה. וש\"נ."],["713","6","<b>ופי' מאין ליש שהרי ממך הכל כתיב</b>: בהבא לקמן עד סוף הפיסקא ראה בארוכה סה\"מ תרכ\"ז ע' שסד ואילך. וש\"נ. לעיל ד\"ה מזמור לתודה. ועוד."],["714","7","<b>אך הפי' מאין ליש</b>: ראה ד\"ה תפלה לעני ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830010\" data-slug=\"or-hatorah-hb\" data-id=\"8158830010\">אוה\"ת</a> דרושים לר\"ה שם ע' א'תא: ”בהדרוש תקעו [בלקו\"ת הנסמן לעיל בתחילת המאמר] פי' יש מאין באופן אחר\". עיי\"ש. אוה\"ת מסעי (כרך ו) ע' א'תתקנט. ובמקומות שנסמנו בהערות שלפנ\"ז."]]],[2002180251,"ז) <b>וזהו</b> שבתחלה עלה במח' לברוא את העולם במדה\"ד, שהוא בחי' ש' אלקים המצמצם ומעלים, בחי' חד קציר שהוא בחי' צמצום והעלם והסתר<sup data-n=\"715\">8</sup> כדי שיהיו עולמות בבחי' יש ודבר נפרד כו'. אך ראה שאין העולם מתקיים, והיינו כי אף שנתהוו עולמות בבחי' יש ודבר נפרד, אעפ\"כ לא זה הי' תכלית הבריאה שישארו בבחי' יש ודבר נפרד, אלא המכוון<sup data-n=\"716\">9</sup> הי' שיהי' בחי' ביטול היש לאין כי נתאוה הקב\"ה להיות לו דירה בתחתונים, ואם הי' הבריאה ע\"י ש' אלקים לבד היו נשארים בבחי' יש ודבר נפרד, ולכך שיתף עמו מדה\"ר שהוא בחי' ש' הוי', דהיינו שיהי' מאיר ש' הוי' בשם אלקים ויהי' יחוד ש' הוי' בשם אלקים, וכמ\"ש גדול ה' בעיר אלקינו שבעיר אלקינו הוא התגלות ש' הוי', הגם שנק' עיר אלקינו אעפ\"כ הי' שם התגלות ש' הוי'<sup data-n=\"717\">10</sup>. ולזה היו קורין במקדש את השם ככתבו, ובמדינה בכינוי ע\"י ש' אד' וש' אלקים, והיינו לפי שבמקדש הי' התגלות ש' הוי' כו'. והנה ע\"י שמאיר ש' הוי' בהתגלות בבחי' שם אלקים עי\"ז נעשה בחי' ביטול",[["715","8","<b>בחי' חד קציר שהוא בחי' צמצום והעלם והסתר</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370065\" data-slug=\"torah-or\" data-id=\"3901370065\">תו\"א וירא יד, סע\"ג</a>. טו, ריש ע' ד."],["716","9","<b>המכווון הי' שיהי' בחי' ביטול היש לאין</b>: ראה לקו\"ת דרושים לשבת שובה סז, ב."],["717","10","<b>וכמ\"ש גדול ה' בעיר אלקינו שבעיר אלקינו הוא התגלות שם הוי'</b>: ראה בארוכה סה\"מ תרכ\"ז ע' שסה. וש\"נ."]]],[2002180252,"היש לאין, וכמ\"ש הללי נפשי את ה' אהללה ה' בחיי אזמרה לאלקי בעודי, שע\"י שהללי נפשי את הוי' דהיינו שמאיר בחי' ש' הוי', עי\"ז אהללה ה' בחיי שהוא בחי' האור דהיינו הנשמה, ואזמרה לאלקי בעודי שהוא בחי' הגוף<sup data-n=\"718\">11</sup>, שגם הגוף שהוא בחי' יש ודבר נפרד בטל ג\"כ לאלקות כו', וזהו שיתף עמו מדה\"ר כו'.\n<b>ובזה</b> יובן מה שעושין ר\"ה דוקא ביום ששי<sup data-n=\"719\">12</sup> שנברא אדה\"ר, ולא בכ\"ה באלול שנברא העולם, והיינו לפי שתחלת הבריאה הי' רק ע\"י שם אלקים לבד בחי' מדה\"ד שנתהוו בבחי' יש ודבר נפרד לגמרי, ועיקר הכוונה הי' שיהי' יחוד ש' הוי' בשם אלקים, והנה זה היחוד הי' בר\"ה כי ביום ששי שנברא אדה\"ר הוא שיר ה' מלך גאות לבש דהיינו שהוי' הוא מלך, שמאיר ש' הוי' בבחי' מל' שהוא בחי' שם אלקים כו', ה' מלך תגל הארץ שהוי' הוא מלך, והיינו שבר\"ה נעשה בחי' יחוד ש' הוי' בשם אלקים, והיינו לפי שאז קבל אדה\"ר עומ\"ש וכמ\"ש מלכותו ברצון קבלו עליהם, לפי שיש בחי' מלוכה ובחי' ממשלה, מלוכה היא ברצון, וממשלה היא בע\"כ, והנה בתחלת הבריאה הי' רק בחי' ממשלה, והיינו לפי שלא הי' מאיר רק בחי' ש' אלקים לבד ולא הי' בחי' ביטול היש לאין ולא היו מקבלים עומ\"ש ברצון, אך בר\"ה שנעשה יחוד ש' הוי' בשם אלקים אז נעשה בחי' ביטול היש לאין וקבלת עומ\"ש ברצון, ולזה עושין ר\"ה דוקא ביום ששי שנברא אדה\"ר לפי שאז הי' עיקר המכוון של הבריאה שהוא בחי' התגלות ש' הוי' בשם אלקים כו'.\nח) <b>והנה</b> בכל השנה ממשיכים ג\"כ יחוד ש' הוי' בש' אלקים כו', והיינו ע\"י המצות כי רמ\"ח פקודין הם רמ\"ח אברים דמלכא, פי' מלכא הוא למעלה מבחי' מל', כי מלכא היינו ע\"ד יחוד ש' הוי' בשם אלקים, וזהו שארז\"ל שעל כל מצוה אומרים לשם יחוד קוב\"ה ושכינתי' שהוא בחי' יחוד ש' הוי' בש' אלקים, וזהו משארז\"ל למה קדמה פ' שמע לוהא\"ש<sup data-n=\"720\">13</sup> כדי שיקבל עליו עומ\"ש תחלה ואח\"כ יקבל עליו עומ\"צ, והיינו לפי שקבעומ\"ש הוא בדרך כלל, ואח\"כ קבעומ\"צ הוא דרך פרט כו'. וזהו בכל השנה ע\"י המצות נעשה יחוד ש' הוי' בש' אלקים, אך זהו בדרך פרט. אך בר\"ה נעשה היחוד בדרך כלל שהוא בחי' קבעומ\"ש על כל השנה, שעי\"ז נעשה היחוד בד\"כ.\n<b>והנה</b> בזה יובן מה שר\"ה צריך להיות רש כו', והיינו לפי שבר\"ה הוא בחי' היחוד של ש' הוי' באלקים שהוא בחי' יחוד שמשא וסיהרא, והנה זה היחוד נעשה דוקא ע\"י בחי' עני דוקא, לפי שעני הוא בחי' מיצר בצר לך ומצאוך כו', וזהו ענין שבר\"ה צ\"ל בחי' רש, תחנונים ידבר רש שהוא בחי' תקיעת שופר, כי שופר הוא בחי' מיצר מן המיצר קראתי י\"ה, ועי\"ז נעשה יחוד ש' הוי' בשם אלקים, וכמ\"ש עלה אלקים בתרועה ה' בקול שופר, דהיינו שע\"י השופר נעשה יחוד ש' הוי' וש' אלקים כו'.\n<b>וזהו</b> תקעו בחדש שופר בכסא ליום חגינו, שתקיעת שופר שייך לבכסא דוקא שאז החדש מתכסה, והיינו לפי שאז הלבנה היא בתכלית העניות לפי שבאמצע החדש כשהיא במלואה אינה נק' עני, ובתחלת החדש אז היא נק' עני כו', ועי\"ז שהיא בחי' עני ל\"ל מגרמה כלום עי\"ז נעשה בחי' יחוד שמשא בסיהרא כו'. וזהו שנאמר תקעו בחדש סתם ולא נאמר באיזה חדש, רק בכסא ליום חגינו שתלה ר\"ה במה שהלבנה מתכסה דוקא, לפי שר\"ה צ\"ל רשה בתחלתה תחנונים ידבר רש, לפי שע\"י עני שהוא בחי' מיצר עי\"ז נעשה יחוד ש' הוי' באלקים, והיינו כי כדי שיהי' היחוד ש' הוי' וש' אלקים צריך שיהי' נמשך מלמעלה מש' הוי', וזהו ע\"י עני דוקא שהוא בחי' מיצר בחי' רעו\"ד כי למחתב\"כ אבל נתפס הוא ברעו\"ד כו', וזהו ענין תקיעת שופר, תקיעה הוא קול פשוט צעקה פנימי' צעק לבם אל ה' בחי' קול פשוט, ושברים הוא בחי' גנוחי גניח ילולי יליל שהוא בחי' בכי' מים תחתונים בוכין אנן בעינן למהוי קדם מלכא כו'.",[["718","11","<b>אהללה ה' בחיי . . דהיינו הנשמה ואזמרה לאלקי בעודי שהוא בחי' הגוף</b>: ראה שעהיוה\"א פ\"ו (פ, סע\"ב). ובארוכה סידור עם דא\"ח (עה\"פ) נו, ג-ד. ובתוס' הגהות ברשימות הצ\"צ לתהלים (יהל אור) ע' תקסה. וס\"ע תרצד ואילך. סה\"מ עטר\"ת ע' קלט. תרפ\"ה ע' צב. ה'ש\"ת ע' 143. תש\"ו ע' 59."],["719","12","<b>ובזה יובן מה שעושין ר\"ה דוקא ביום ששי</b>: בהבא לקמן בפיסקא זו ראה [נוסף לד\"ה תקעו בלקו\"ת דרושים לר\"ה שם] סידור עם דא\"ח רלח, א."],["720","13","<b>וזהו משארז\"ל למה קדמה פ' שמע לוהא\"ש</b>: ראה בכ\"ז בארוכה סידור עם דא\"ח עג, ג ואילך. סה\"מ תרכ\"ז ע' שלג ואילך. וס\"ע שלט ואילך. תרכ\"ט ע' רג ואילך."]]],[2002180253,"<b>טי\"ת)</b> והנה י\"ל עוד טעם מה שר\"ה צ\"ל בחי' רשה כו' בחי' עני, דהנה אנו אומרים ועינינו מאירות כשמש וכירח, והקשה הה\"מ ז\"ל שאם אנו אומרים כשמש וא\"כ מה שייך לומר עוד וכירח, שהרי אין ערוך השמש לירח כלל, ואור הירח הוא טפל ובטל לגמרי לגבי אור השמש. ותירץ הה\"מ ז\"ל<sup data-n=\"721\">14</sup> שיש מעלה בירח מה שאין בשמש, והיינו לפי שהירח מקבל אור חדש מה שלא הי' לה מקדם ע\"כ מלובש בזה תענוג יותר, משא\"כ באור השמש שאין בה שינויים כלל אלא כו', אין מאיר בה התענוג כ\"כ, לפי שתענוג תמידי אינו תענוג<sup data-n=\"722\">15</sup>, ואמר משל ע\"ז מעני ועשיר, שאנו רואים שכשעני משתכר מאה זהובים מתענג מזה יותר ממלך שיש לו סגולת מלכים, והיינו לפי שהוא אצלו דבר חדש שלא הי' לו מקודם שהי' עני בתכלית העניות, ואח\"כ כשיוצא מהעוני הוא מתענג מאד בזה כו' יותר מהעשיר, שאף שלעשיר יש הרבה יותר מזה אעפ\"כ אינו מתענג מזה כלל, לפי שתענוג תמידי אינו תענוג. וזהו שאנו מבקשים ועינינו מאירות כשמש וכירח, והיינו לפי שירח לית לה מגרמה כלום ואח\"כ כשמקבלת אור מהשמש מלובש בזה תענוג גדול, והנה תענוג היא בחי' גבוה מאד וכמ\"ש וקראת לשבת ענג, אז תתענג על הוי', שתענוג הוא למעלה מש' הוי', ענג ר\"ת עדן נהר גן כו', ולפי שמלובש בה תענוג יותר ע\"כ אנו מבקשים שיהי' כו' ב' המעלות כשמש שיש בה אור רב בעצם ואין בה שינוים כלל, וכירח שמקבלת אור חדש שמלובש בזה תענוג עליון כו'.\n<b>וזהו</b> שבר\"ה הוא דוקא בכסא ליום חגינו, לפי שע\"י שמתכסה הלבנה ואין לה שום אור, ואח\"כ מקבלת אור חדש עי\"ז נתלבש בזה תענוג עליון כו', והנה ע\"י תענוג עליון עי\"ז נמשך סליחת העוונות וכמו שאנו רואים למשל המלך כשהוא מתענג אז הוא שולח לאסירי המלך חפשי<sup data-n=\"723\">16</sup> וסולח לעוונם, וכך עי\"ז שמאיר תענוג עליון למעלה עי\"ז נמשך סליחת העוונות, ולזה בר\"ה צריך שיהי' דוקא בכסא לפי שבר\"ה צריך להמשיך בחי' סליחת העוונות כו', וזהו דוקא ע\"י שהלבנה מתכסה ומתלבש בה תענוג עליון כו'.\nיו\"ד) <b>ובזה</b> יובן מה שתפלה של יד הוא קודם לתפלה של ראש, שאף שתפלה של ראש יש בו ד' בתים, ובתפלה של יד אין בו כ\"א בית א', וכן רצועה של",[["721","14","<b>ועינינו מאירות כשמש וכירח והקשה הה\"מ ז\"ל . . ותירץ הה\"מ ז\"ל</b>: בס' אור תורה פד, סע\"ד ואילך. — הובא ונת' בתוס' הגהות בד\"ה תפלה לעני באוה\"ת דרושים לר\"ה שם ע' א'ת-תא. והבא לקמן (עד התיבות: וזהו שבר\"ה) הוא תוכן תורת הה\"מ שם בתוס' ביאור."],["722","15","<b>שתענוג תמידי אינו תענוג</b>: ראה כתר שם טוב סי' קכא (טז, א). לקו\"א להה\"מ מא, ב [בשם הבעש\"ט]. מאמרי אדה\"ז תקס\"ג ח\"א ע' רז. על התורה ח\"א (הוצאה שני') בהוספות ע' 7. ענינים ע' תיד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680317\" data-slug=\"torat-chaim\" data-id=\"2300680317\">תו\"ח תולדות קמז, ב</a>. ויצא כח, א. מאמרי אדהאמ\"צ שמות ח\"ב ע' תסו. קונטרסים ע' תקסח. אוה\"ת נח, ס, א. מטות ע' א'שכט. רשימות הצ\"צ לתהלים (יהל אור) ע' שעג. ועוד."],["723","16","<b>למשל המלך כשהוא מתענג . . שולח לאסירי המלך חפשי</b>: ראה בכ\"ז לעיל סד\"ה ארע\"ק אשריכם ישראל (ע' תקל)."]]],[2002180254,"יד מותר לעשותה של ראש, אבל של ראש אסור לעשות לשל יד לפי שמעלין בקדש כו', ואעפ\"כ תפלה של יד קודם, לפי שתש\"י הוא בחי' עני יד כהה, ולכך מלובש בה תענוג יותר מבשל ראש, וכדי שיוכל להניח תש\"ר צריך להניח מקודם תש\"י כי בלי תש\"י א\"א להניח של ראש כו', וכמו שאנו רואים שבמשה נאמר לך רד רד מגדולתך כלום נתתי לך גדולה אלא בשביל ישראל, והיינו לפי שישראל נק' עם עני וכמ\"ש ואת עם עני תושיע, והיינו לפי שעם עני שהוא בחי' תפלה לעני הוא ממשיך את בחי' תפלה למשה, וכך תש\"י הוא ממשיך את בחי' תש\"ר.\n<b>והנה</b> באמת כל אדם יכול לבוא למדרגת עני, והענין הוא דהנה עני הוא בחי' ענוה וכמ\"ש עני ורוכב על החמור ות\"י ענותן, והיינו לפי שענוה הוא בחי' ביטול ושפלות, וע\"י ענוה יכול להגיע למדרגת עני כו'. וזהו מ\"ש במשה והאיש משה ענו מאד מכל האדם, והיינו לפי שמשה אף שהי' בחי' שמש פני משה כפני חמה, אעפ\"כ הי' בו ג\"כ המעלה של בחי' סיהרא שהוא בחי' עני וכמ\"ש ועינינו מאירות כשמש וכירח שהיו בו ב' המעלות של שמש וירח כו', והיינו שע\"י ענוה יכול להגיע לבחי' עני כו'. וזהו שדוד אמר ע\"ע כי עני ואביון אני, והיינו לפי שתפלת עני הוא מגיע למעלה מאד מחמת שעני מגיע לבחי' מיצר שהוא בחי' רעו\"ד. ולזה בר\"ה צריך שיהי' רשה בתחלתה, לפי שע\"י שרשה בתחלתה בחי' עני שהוא בחי' תשר\"ת גנוחי גניח ילולי יליל, עי\"ז נמשך למעלה מעצמות אוא\"ס, כי בתרועה יש עוד פי' לשון חיבה וריעות שעי\"ז נמשך בחי' אהבה וריעות מהקב\"ה לישראל ועי\"ז נמשך סליחת העוונות כו', וזהו תקעו בחדש שופר בכסא ליום חגינו בכסא דוקא.\n<b>כי</b> חק לישראל הוא משפט לאלקי יעקב, הנה יש ב' בחי' יעקב וישראל, ישראל הוא בחי' לי ראש שהוא בחי' נשמות צדיקים, ויעקב הוא בחי' יו\"ד עקב שהוא בחי' נשמות בינונים, אך משפט דאיהו רחמי והיינו שאף שמשפט הוא בחי' דין, אך הוא בחי' התכללות דין ורחמים שהוא בחי' שיתף עמו מדה\"ר, וזהו שיעקב אמר<sup data-n=\"724\">17</sup> והי' הוי' לי לאלקים שהוא בחי' שיתוף ש' הוי' עם ש' אלקים כו', והנה עי\"ז נמשך שיהי' הוי' כאלקים יחשב והיינו שעי\"ז נמשך שיהי' המשכה מלמעלה מש' הוי' עד שש' הוי' דעתה יהי' כאלקים יחשב כו'.",[["724","17","<b>והי' הוי' לי לאלקים . . שיתוף שם הוי' . . כאלקים יחשב</b>: ראה בארוכה לקו\"ת דרושים לשבת שובה סד, ג-ד. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370102\" data-slug=\"torah-or\" data-id=\"3901370102\">תו\"א ויצא כא, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370105\" data-slug=\"torah-or\" data-id=\"3901370105\">כב, ג</a>."]]],[2002180255,"<h3>אנכי אנכי הוא כו'</h3>\n<b>בס\"ד.</b>\nאנכי אנכי הוא מוחה פשעיך<sup data-n=\"725\">1</sup> למעני, וצ\"ל ענין אומרו הוא שלכאורה הוא מיותר, דהל\"ל אנכי אנכי מוחה פשעיך. וגם צ\"ל מה\"ע למעני, דמשמע שהגם שאינם ראוי' שימחה פשעם בשביל עצמם עכ\"ז הנה הוא מוחה פשעם למענו בעצמו כבי', הלא ארז\"ל וכי מאי אכפת לי' אם שוחט מן הצואר או שוחט מן העורף כו', ומקרא מלא דבר הכתוב אם חטאת מה תפעל ורבו פשעיך מה תעשה לו אם צדקת מה תתן לו או מה מידך יקח, כי לפניו כחשכה כאורה שוין, ומהו ענין למעני.\n<b>ויובן</b> בהקדם שרש ענין ההפרש בין כל המצוות מעשיות בכלל למצות התשובה, והוא שכלליות המצות הם בש' הוי' כמ\"ש כמ\"פ מצות הוי', ומצות התשובה היא בבחי' אנכי, כמ\"ש כי המצוה הזאת שקאי על מצות התשובה<sup data-n=\"726\">2</sup> שמדבר בה, נא' אשר אנכי מצוך. ולכאורה צ\"ל הלא במ\"ת שהוא נתינת כלליות כל המצות נאמר ג\"כ אנכי ה' כו', ומהו היתרון במצות התשובה. אך הענין הוא דבתשובה נאמר ב\"פ אנכי כמ\"ש אנכי אנכי הוא מוחה פשעיך, וצ\"ל מהו ענין ההפרש בין פעם א' אנכי לב\"פ. וצ\"ל תחלה ההפרש בין אנכי לבחי' ש' הוי', דלכאורה ענינם אחד הוא, שהרי כתיב אנכי הוי' אלקיך שמנושא הענין<sup data-n=\"727\">3</sup> משמע שמודיע שאנכי הוא הוי' אלקיך, שצ\"ל ששם הוי' ידוע הי' לישראל, אבל אנכי מי שאנכי הנה הוא בבחי' ההעלם עד שאינו ידוע לנו מי הוא, לזה אומר אשר אנכי מי שאנכי נתצמצם להיות בבחי' צמצום דש' הוי' בכדי להיות אלקיך אלקה שלך. או נאמר אשר הודיע לנו במ\"ת שהוי' הוא בחי' אוא\"ס המצומצם הנה זהו עצמו בחי' אנכי מי שאנכי וכל המכוון מבחי' הצמצום",[["725","1","<b>אנכי אנכי הוא מוחה פשעיך</b>: ברשימת מאמרי כ\"ק אדמו\"ר מהר\"ש כותב אודות מאמר זה: ”הוא ד\"ה להבין כו' [שרש ההפרש בין מצות כו' לתשובה] דסוף שנת תרל\"ט — בהרחב הביאור\".\nד\"ה להבין כו' שרש ההפרש הנ\"ל נדפס לעיל ע' תקלא, והוא ד\"ה זה בס' מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתפג ואילך. והוא ביאור ראשון לד\"ה כי המצוה הזאת תקס\"ה שם ע' תתעו ואילך. ונו\"א ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380900\" data-slug=\"likkutei-torah\" data-id=\"4001380900\">לקו\"ת נצבים מה, ב</a> ואילך. [ביאור שני לד\"ה כי המצוה הנ\"ל נמצא בס' מאמרי אדה\"ז תקס\"ה ע' תתקלה ואילך. ובתוס' הגהות ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650076\" data-slug=\"or-hatorah-hb\" data-id=\"8316650076\">אוה\"ת נצבים ע' א'רכט</a> ואילך. ובסה\"מ תרכ\"ו ע' רמב ואילך. ובארוכה בהמשך כי המצוה בסה\"מ תרל\"ח ע' שא ואילך וע' תצב ואילך. וראה גם דרמ\"צ מצות וידוי ותשובה (פ\"א-ב) לח, א ואילך].\nמאמר זה נמצא בשינויים והוספות וכו' בד\"ה זה בסה\"מ תרנ\"א ע' כא ואילך וע' כח ואילך. [וראה גם שם ע' נא-ב].\nוראה עוד לכמה מעניני המאמר ד\"ה אנכי אנכי: בס' מאמרי אדה\"ז תקס\"ב ח\"א ס\"ע יג-יד. אוה\"ת נ\"ך (כרך ב) ע' תתה ואילך. סה\"מ תרל\"ג ח\"ב ע' תקכט ואילך. תרל\"ו ח\"ב ע' שטו-ז. תרל\"ח שם ע' שט ואילך [בהמשך כי המצוה תרל\"ח הנ\"ל]. שם ע' תצז ואילך. תרס\"ה ע' כ וס\"ע כח-ל. תרס\"ט ע' יט וע' כט. תרפ\"ז ע' יג וע' כו. תרצ\"ט ס\"ע 29."],["726","2","<b>כי המצוה הזאת שקאי על מצות התשובה</b>: ראה רמב\"ן עה\"פ (נצבים ל, יא). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380901\" data-slug=\"likkutei-torah\" data-id=\"4001380901\">לקו\"ת נצבים שם מה, ג</a>. מאמרי אדה\"ז תקס\"ה שם ע' תתעו. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141124\" data-slug=\"likkutei-sichot\" data-id=\"1300141124\">לקו\"ש חי\"ד ע' 112</a> הערה 24."],["727","3","<b>שמנושא הענין משמע שמודיע שאנכי הוא הוי' אלקיך . . שש' הוי' ידוע הי' לישראל</b>: ראה גם ספורנו עה\"פ (יתרו כ, ב). ועוד."]]],[2002180256,"דש' הוי' בכדי שאנכי בעצמי יהי' אלקיך אלקה שלך, אבל מ\"מ לכאורה ענינם אחד הוא. ולפ\"ז אין יתרון המעלה למצות התשובה שהיא בבחי' אנכי לשאר כל המצות שהם מצות הוי'. אמנם באמת אינו כן, שהרי התשובה מועלת לתקן הפגם שפגמו במצות הוי' א\"כ בהכרח לומר שיש יתרון למצות התשובה, והוא במה שתלוי' בבחי' אנכי מי שאנכי שלמעלה מבחי' ש' הוי'. וגם ממקומו מוכרח לומר כן, דאם נאמר שאנכי וש' הוי' הכל אחד א\"כ מהו מה שמספר שאנכי הוא הוי' אלקיך, שאם ענינם אחד הוא ממילא מובן שכאשר ש' הוי' הוא אלקה שלך כן גם אנכי הוא אלקה שלך, ומהו החידוש שמודיע, אלא בהכרח לומר שאנכי מי שאנכי הוא בחי' ומדריגה גבוה יותר, והוא מה שאנכי קאי על בחי' אוא\"ס שלמעלה מבחי' הצמצום דש' הוי' שהיו\"ד דש' הוי' הוא בחי' צמצום וה\"א התפשטות<sup data-n=\"728\">4</sup> כו', משא\"כ אנכי הוא למעלה מבחי' צמצום זה, ועכ\"ז בכדי להיות אלקיך נתצמצם כבי' בחי' אנכי מי שאנכי בבחי' ש' הוי', ולפ\"ז יתרון מצות התשובה גבהה מעלתה עד שמגעת לבחי' אוא\"ס שלפני הצמצום כו'.\n<b>וביאור</b> הענין הנה נודע כי רמ\"ח מ\"ע הן רמ\"ח איברים דמלכא, והיינו בחי' אורות הנאצלים מן המאציל ביו\"ד ספירות בבחי' אורות וכלים, וראשיתן הוא בחי' הק\"ו כו', ובחי' הכלים א\"א כ\"א ע\"י צמצום בתחילה (ובאמת גם המשכת האור הוא ע\"י צמצום שהרי הוא לפי ערך הכלי), וזהו בחי' יו\"ד דש' הוי', ואח\"כ בחי' ההתפשטות אורך ורוחב ז\"ע בחי' ה' דש' הוי', והוא\"ו הוא בחי' המשכה כו'. ובדרך פרט יש בחי' ש' הוי' לכל ספי' וספירה בפ\"ע, כמ\"ש מזה במ\"א בד\"ה אנת הוא חד<sup data-n=\"729\">5</sup> ולא בחושבן, וכלליות ע\"ס זהו ג\"כ ש' הוי' ע\"ד הנ\"ל יו\"ד צמצום ה' התפשטות כו'. והנה המצות הם כלים לאורות עליונים, ולכן נק' רמ\"ח איברים דמלכא, שפי' מלכא הוא בחי' ז\"א דאצי', ובחי' האיברים שלו ז\"ע בחי' הכלים דשמות הוי' שיש לכל ספי' שבו בפרט כו', וז\"ע המבואר במ\"א בפי' הפסוק ויעש דוד שם<sup data-n=\"730\">6</sup> שע\"י המצות עושים וממשיכים למעלה בחי' שם, והיינו בחי' שם דהוי' הנ\"ל. ויש פרטי המצות שרומזים ד' פרטי אותיות דש' הוי', כמ\"ש בקריאת שמע שעל המטה אם פגמתי באות יו\"ד בביטול ק\"ש<sup data-n=\"731\">7</sup>, ובאות ה' בביטול תפילין וא\"ו ציצית ה' אחרונה תפילה, ובד\"כ מצות התפילין ז\"ע המשכת מוחין שראשיתן היא החכמה בחי' יו\"ד דש' הוי', וז\"ע פ' קדש",[["728","4","<b>שהיו\"ד . . בחי' צמצום וה\"א התפשטות</b>: ראה לקו\"ת נצבים שם מה, ג. דרושים לשמע\"צ צב, ד. מאמרי אדה\"ז תקס\"ה ח\"ב שם ס\"ע תתעז-ח. ובארוכה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540107\" data-slug=\"torat-chaim\" data-id=\"2300540107\">תו\"ח שמות</a> (הוצאת תשס\"ג) קנ, א ואילך. סה\"מ תרנ\"א שם ע' כב ואילך. תרנ\"ו ע' תרנ ואילך. המשך תרס\"ו ע' רז ואילך. ועוד."],["729","5","<b>כמ\"ש מזה במ\"א בד\"ה אנת הוא חד</b>: ראה סידור עם דא\"ח קסב, א."],["730","6","<b>המבואר במ\"א בפי' הפסוק ויעש דוד שם</b>: אגה\"ק סי' ה (קו, ב ואילך. קט, ב). וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380901\" data-slug=\"likkutei-torah\" data-id=\"4001380901\">לקו\"ת נצבים שם מה, ג</a>."],["731","7","<b>המצות . . אותיות דש' הוי' . . אם פגמתי באות יו\"ד בביטול ק\"ש</b>: ראה בארוכה לקו\"ת דרושים לשבת שובה סד, ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקיב ואילך. מאמרי אדהאמ\"צ דברים ח\"ג ע' א'פב ואילך. סה\"מ תרס\"ה ע' לה ואילך. תרפ\"ג ע' קטז ואילך. ס\"ע קכג ואילך. תש\"ז ס\"ע 161 ואילך וע' 169 ואילך."]]],[2002180257,"שבתפילין שרומזת לבחי' החכמה, ובפרטיות בחי' תפילין הוא בבחי' ה' דש' הוי' לפי שמוחין דז\"א נמשכים מהבינה, ועכ\"ז גם בחי' החכמה כלול בבינה, ע\"ד וחכם בבינה. ומצות סוכה<sup data-n=\"732\">8</sup> בכלל זהו בבחי' ה' ראשונה דש' הוי' כי בינה מקור המקיפים. ותורה ותפילה הם בחי' ו\"ה דש' הוי'. וז\"ע שנק' המצות בש' מצות הוי' להיותם תלוים באותיות דש' הוי' בכללן ובפרטן כו'.\n<b>אך</b> הנה מי שפגם ועבר על המצות התלוי' בד' אותיות הוי' כנ\"ל, א\"א להיות תיקונו מבחי' זו עצמו שפגם בו, כ\"א להמשיך מבחי' הגבוה יותר, אשר משם יומשך למלאות הפגם שפגם, ועד\"מ הנהר שנתקלקלו מימיו ונתמעטו כ\"כ עד שאין עוברים והולכים כדרכם, העצה לזה לחפור בעומק יותר, ועד\"ז יובן בענין מי שהעביר על הדרך ופגם בש' הוי' צריך לחפור בעומק יותר, וכמ\"ש ממעמקים קראתיך ה', וזהו ע\"י מצות התשובה דוקא.\n<b>ושרש</b> הדברים הוא לפי שלמעלה מבחי' הק\"ו אין שם בחי' אורות בכלים עדיין, להיות כי אינו עדיין בבחי' גילוי אור, ושם נאמר ישת חשך סתרו, והוא בחי' העלם העצמיות דא\"ס דלא ידע לי' בר איהו, וזהו הנק' אנכי מי שאנכי כו' ועד בחי' זו מגיע מצות התשובה דוקא. והטעם מפני מה דוקא מצות התשובה מגעת לבחי' [זו] ולא שארי המצות זולת התשובה, יובן ע\"פ ידיעה בתחלה שרש ענין פי' ממעמקים קראתיך ה', שפי' ממעמקים הוא ב' עומקים<sup data-n=\"733\">9</sup> דב' יסודות דאו\"א, וז\"ע תשובה שהיא תשוב ה' ויש ה' במילוי יו\"ד, ויש במילוי ה'<sup data-n=\"734\">10</sup>, שהה' הוא ביסוד אימא, והיו\"ד הוא ביסוד אבא הגנוז ביסוד אימא. וביאור הדברים הנה בחי' עומק הראשון הוא הנק' עומקא דבירא היינו בחי' יסוד אימא שהוא כמשל באר מים חיים המכונסים בה כבר כו', ובחי' המעיין אשר נובע תמיד בתחתיות הבאר וממלא את הבאר בתמידות הוא משל לבחי' יסוד אבא שגנוז ביסוד אימא, והיינו להיותו בהעלם תחת הארץ, וזהו בחי' עומק השני כו'.\n<b>ובעבודת</b> ה' ב' בחי' עומקים אלו זהו בחי' רצו\"ש, שהרצוא הבא מסיבת ההתבוננות שהיא בחי' רשפי אש התשוקה בהתלהבות כי בהיותו מתבונן איך דכולא קמי' כלא חשיב יתפעל בלבבו לצאת מנרתק גופו בבחי' כלות",[["732","8","<b>ומצות סוכה . . בינה מקור המקיפי'</b>: ראה סידור עם דא\"ח רסה, סע\"א ואילך. אוה\"ת בראשית (כרך ב) תכה, ב. ביאוה\"ז להצ\"צ ח\"א ע' פד-ה. סה\"מ תרכ\"ט ס\"ע שסט. וש\"נ. וס\"ע שעד. ועוד."],["733","9","<b>שפי' ממעמקים הוא ב' עומקים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380902\" data-slug=\"likkutei-torah\" data-id=\"4001380902\">לקו\"ת נצבים שם מה, ד</a>. מאמרי אדה\"ז תקס\"ה ח\"ב שם ע' תתפ וע' תתקמג ואילך. סה\"מ תרכ\"ו שם ע' רמז-ח. תרל\"ח שם ע' שיט ואילך."],["734","10","<b>ויש ה' במילוי יו\"ד ויש במילוי ה'</b>: ר\"ל שיש ה\"א במילוי יו\"ד (”ה\"י\") ויש ה\"א במילוי ה' (”ה\"ה\"). וכאן קאי באות ה\"א במילוי יודי\"ן ”ה\"י\". ראה לקמן בהמאמר: שהה' . . והיו\"ד. וראה ד\"ה להבין כו' תקס\"ה שם: וזהו מילוי ה\"י דתשובה תשוב ה\"י. ועד\"ז ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380901\" data-slug=\"likkutei-torah\" data-id=\"4001380901\">לקו\"ת נצבים מה, ג</a> שם: תשובה תשוב ה', וה' זו יש בה מילוי יו\"ד (ה\"י)."]]],[2002180258,"הנפש וזהו אם רץ לבך, וה\"ז כמשל הבאר שמימיו נובעים מתתא לעילא בבחי' העלאה כו'. והעומק השני דיסוד אבא זהו בחי' השוב שאחרי הרצוא והוא בחי' הביטול<sup data-n=\"735\">11</sup> כו'. וב' עומקים<sup data-n=\"736\">12</sup> אלו נק' עומק רום ועומק תחת, והם מתלבשים זה בזה, והיינו שעומק השוב דחכמה היינו בחי' הביטול גנוז ברצוא דיסוד אימא, כמשל המעין שגנוז בבאר. וז\"ע תשובה תשוב ה\"י במילוי יו\"ד שתשוב הה\"י ברצו\"ש יחד למעלה מעלה, שעולים ומתבטלים שניהם ומתכללים למעלה מעלה בבחי' כתר עליון שלפני בחי' הויות דאו\"א ודז\"א, והוא בחי' אנכי מי שאנכי שלפני הק\"ו. וזהו ממעמקים קראתיך הוי' פי' אחר ההעלאה יש המשכה וירידה, שאחר שנתעלה הה\"י במילוי יו\"ד והוא ב' עומקים הנ\"ל למעלה בבחי' אנכי, אזי נמשך מלמעלמ\"ט להיות מהות כל ההויות דאו\"א ודז\"א, וזהו קראתיך מלמעלמ\"ט להיות הוי' בע\"ס.\n<b>ובכ\"ז</b> יובן שרש ענין הוא, שאמר אנכי אנכי הוא, דהנה ב\"פ אנכי זהו ענין העלאת ב' יסודות דאו\"א, והיינו אחר שמתעלה אור אימא ונכלל באור אבא ועולים שניהם בבחי' עתיקא סתימאה שנק' הוא, וכמ\"ש במ\"א ע\"פ ועבד הלוי הוא<sup data-n=\"737\">13</sup>, והוא בבחי' העלם העצמות שלפני הצמצום דק\"ו, ומשם נמשך האור להאיר בתוס' הארה חדשה באצי', ולכן נמשך משם הסליחה והמחילה שימולא כל הפגמים שבע\"ס, וזהו הוא דוקא מוחה פשעיך, להיות נושא עון ועובר על פשע. וזהו ע\"י התשובה דוקא שהיא בחי' תשוב ה\"י במילוי יו\"ד כו', כי ע\"י תשובה דוקא מגעת לבחי' אנכי. והגם שגם במ\"ת נאמר אנכי, י\"ל שבמ\"ת ניתן מצות התשובה ג\"כ. ועוי\"ל, שבמ\"ת נאמר פ\"א אנכי, והיינו שזהו ההמשכה מבחי' אנכי שיהי' הוי' אלקיך היינו ההויות דאו\"א וז\"א, אמנם הגורם להיות המשכה גם לא בזמן מ\"ת זהו ע\"י התשובה שמגעת למעלה יותר, והיינו ב' בחי' אנכי היינו ב' הבחי' דכתר א\"א וע\"י, וגם בחי' הוא דסתים ונעלם, ומשם נמשך להיות נושא עון כו' שז\"ע מוחה פשעיך. ואומרו למעני, היינו בכדי שיומשך ההויות באו\"א וז\"א כו', וגם י\"ל למעני מפני כי נתאוה הקב\"ה להיות לו ית' דירה בתחתונים, ולכן הגם כי מאי איכפת לי' עכ\"ז מפני שנתאוה כו' לכן ה\"ז למעני כו'.",[["735","11","<b>השוב שאחרי הרצוא והוא בחי' הביטול</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370006\" data-slug=\"torah-or\" data-id=\"3901370006\">תו\"א בראשית ב, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380833\" data-slug=\"likkutei-torah\" data-id=\"4001380833\">לקו\"ת ראה כט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381312\" data-slug=\"likkutei-torah\" data-id=\"4001381312\">שה\"ש מו, א</a> ואילך. ובכ\"מ."],["736","12","<b>וב' עומקי' אלו נק' עומק רום ועומק תחת</b>: ראה ביאוה\"ז לאדהאמ\"צ צט, ג. שערי תשובה ח\"א כג, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670311\" data-slug=\"torat-chaim\" data-id=\"2300670311\">תו\"ח בראשית ה, ד</a> ואילך [ובהנסמן בהמ\"מ שם]."],["737","13","<b>וכמ\"ש במ\"א ע\"פ ועבד הלוי הוא</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370049\" data-slug=\"torah-or\" data-id=\"3901370049\">תו\"א ר\"פ לך לך יא, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380535\" data-slug=\"likkutei-torah\" data-id=\"4001380535\">לקו\"ת קרח נה, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670111\" data-slug=\"torat-chaim\" data-id=\"2300670111\">תו\"ח לך לך פא, ב</a> ואילך."]]],[2002180259,"<h3>ויקהלו אל המלך שלמה כו'</h3>\n<b></b><b>בס\"ד (חג הסוכות, תר\"ם).</b>\n<b></b>באתי לגני כו' איתן כו' טו\"מ דתורה - ז\"פ\nחה\"ס\n<b>ויקהלו</b> אל המלך שלמה<sup data-n=\"738\">1</sup> כל איש ישראל בירח<sup data-n=\"739\">2</sup> האתנים בחג הוא החדש השביעי. ירח האתנים הוא חדש תשרי לפי שבו מאיר בחי' איתן האזרחי, והנה אותיות איתן משמשות לע\"ל<sup data-n=\"740\">3</sup>, שלע\"ל יהי' גילוי בחי' איתן, וזהו משכיל לאיתן האזרחי פי' שלע\"ל יזרח בישראל בחי' איתן, וכתיב כל האזרח בישראל ישבו בסוכות פי' כל מה שעתיד להזריח בישראל, עכשיו ישבו בסוכות, שהארה מבחי' זו מתגלה בחגה\"ס וע' בהג\"ה לד\"ה ראה אנכי<sup data-n=\"741\">4</sup> נותן בענין אזרח שהוא ש' ע\"ב שלמעלה מס\"ג מ\"ה תהו ותיקון, ולכן נק' ירח האתנים כו'.\n<b>והענין</b> הוא, דהנה ארז\"ל עוה\"ב אין בו לא אכילה ולא שתי', והנה עוה\"ב קאי על עולם התחי'<sup data-n=\"742\">5</sup>, שאין לומר שהוא קאי על עולם הנשמות דא\"כ מאי רבותי' שאין בו לא אכילה ולא שתי', ועוד דקחשיב התם במשנה ואלו שאין להם חלק לעוה\"ב, האומר אין תחיית המתים מן התורה הוא כפר בתחיית המתים ע\"כ לא יקום בתחיית המתים, נמצא מבואר שעוה\"ב קאי על עולם התחי' שיעמדו הנשמות בגופים דוקא ואעפ\"כ לא יהי' אכילה ושתי'. ולכאורה אינו מובן איך יכול להיות שהגוף יחי' בלא אכילה ושתי'. אך הענין הוא דהנה לע\"ל יהי' נמשך תוס' וריבוי אורות ועי\"ז",[["738","1","<b>ויקהלו אל המלך שלמה</b>: הוא ד\"ה זה בסה\"מ תרכ\"ט ע' שעה ואילך. וכאן הוא בתוס' איזה הגהות. פ\"א מהמאמר ופ\"ה ואילך מיוסד על ביאור לד\"ה האזינו בס' מאמרי אדה\"ז תקס\"ז ע' שס ואילך. והערות ע\"ז באוה\"ת האזינו ע' א'תרמב ואילך [ולכמה ענינים שבהמאמר ראה ד\"ה האזינו ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381018\" data-slug=\"likkutei-torah\" data-id=\"4001381018\">לקו\"ת האזינו עג, ד</a>. ובס' מאמרי אדה\"ז תקס\"ז שם ע' שנה ואילך]. פרקים ב-ד מהמאמר מיוסדים על הערות לביאור האזינו הנ\"ל באוה\"ת האזינו (כרך ו) ע' ב'תקכב ואילך.\nהמאמר נמצא עם הוספות ושינויים בד\"ה אני לדודי שבסה\"מ תרס\"ג ח\"ב ע' שכד ואילך. ובד\"ה להבין ענין שמח\"ת בסה\"מ תש\"ל ע' 33 ואילך.\nפרקים ה-ו מהמאמר נמצאים בתוס' ביאור ובאריכות: בד\"ה לך לך בהמשך תרס\"ו ס\"ע נז-סג. ובד\"ה כי לי בנ\"י בסה\"מ תרפ\"ז ע' קעה ואילך. ובד\"ה מרגלא בפומי' כו' תכלית חכמה בסה\"מ תרפ\"ט ע' 105 ואילך. וראה גם ד\"ה מרגלא בפומי' תשכ\"ט. תש\"מ (סה\"מ מלוקט ח\"ה ע' צד ואילך). תשמ\"ו."],["739","2","<b>ירח האתנים הוא חדש תשרי</b>: ראה בארוכה ד\"ה ויקהלו ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450663\" data-slug=\"or-hatorah-hb\" data-id=\"8316450663\">אוה\"ת נ\"ך ע' סא</a> ואילך. וראה גם אוה\"ת ראה ע' תרסג. ובכ\"מ. לעיל ד\"ה החודש הזה לכם."],["740","3","<b>בחי' איתן האזרחי . . אותיות איתן משמשות לע\"ל</b>: ראה לקו\"ת דברים יח, א. אוה\"ת ויחי שצב, סע\"א ואילך. סה\"מ תרכ\"ו (הוצאת תשמ\"ט) ע' רח. ובכ\"מ [באוה\"ת ויחי שם כותב ע\"ז: מה שאותיות איתן משמשות לעתיד, דהנה פי' הפשוט דאזרח היינו לשון עתיד, אזרח עתיד אני להזריח אור, מפני שאותיות האל\"ף הוא מאותיות איתן שמשמשות לעתיד]."],["741","4","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450636\" data-slug=\"or-hatorah-hb\" data-id=\"8316450636\">וע' בהג\"ה</a> לד\"ה ראה אנכי</b>: אוה\"ת ראה ע' תרלו. וראה גם סה\"מ תרכ\"ו ע' רח."],["742","5","<b>עוה\"ב קאי על עולם התחי'</b>: כדעת הרמב\"ן בשער הגמול בסופו, וכ\"ה ההכרעה בתורת החסידות, ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380138\" data-slug=\"likkutei-torah\" data-id=\"4001380138\">לקו\"ת צו טו, ג</a>. דרושים לשבת שובה סה, סע\"ד. דרך מצותיך יד, ב. ובאוה\"ת חוקת ס\"ע תתט (ועד\"ז שם כרך ה ע' א'תרלז): ורבינו ז\"ל בכל הדרושים הזכיר רק דעת הרמב\"ן לבד."]]],[2002180260,"יהי' גם הגוף ניזון מזיו השכינה<sup data-n=\"743\">6</sup>, וכמ\"ש במד\"ר ע\"פ ואתה מחי' את כולם<sup data-n=\"744\">7</sup>, וכך לע\"ל שיהי' בחי' תוס' אורות עי\"ז יהי' גם הגוף ניזון מזיו שכינתו ית', ולא יהי' צריך לאכילה ושתי' גשמי', וכמו למשל אבוקה גדולה מאירה למרחוק מאד, וכך לפי שיהי' מאיר בחי' תוס' אורות שהוא בחי' אבוקה יהי' הגוף ג\"כ ניזון מזיו השכינה. והנה תוס' אורות שיהי' נמשך לע\"ל זהו ע\"י היום לעשותם שהוא בחי' עולם המעשה, דהיינו ע\"י המצות שמקיימין עתה, ועי\"ז יהי' נמשך תוס' אורות וכמ\"ש ויניחהו בג\"ע לעבדה ולשמרה, לעבדה זו רמ\"ח מ\"ע ולשמרה זו שס\"ה ל\"ת ועי\"ז נמשך תוס' אור בג\"ע, וכך לע\"ל ע\"י המצות יהי' נמשך תוס' אורות כו' ועי\"ז יהי' גם הגוף הגשמי ניזון כו'.\nב) <b>ולהבין</b> זה בתוס' ביאור<sup data-n=\"745\">8</sup>, צ\"ל מקודם מ\"ש באתי לגני אחותי כלה אכלתי יערי עם דבשי כו', ופי' בזהר אכלתי יערי זו בחי' יוצר אור, עם דבשי זו ק\"ש, שנק' בשם אכילה, לפי שתפלות כנגד תמידין תקנו, והנה בקרבנות נאמר את קרבני לחמי לאשי שהקרבנות נק' בשם לחם לחמי כו', וכך התפלה נק' בשם אכילה אכלתי יערי כו'. ולהבין איך שייך למעלה בחי' אכילה, שהרי משה כשהי' בהר עם ה' לחם לא אכל ואיך יתכן למעלה בחי' האכילה. אך הענין הוא שע\"ז פי' בזהר באתי לגני אכלתי יערי אבל באתרי' לאו אורחי' למיכל<sup data-n=\"746\">9</sup>. והענין הוא דהנה הקרבנות שהיו מקריבין ע\"ג המזבח היינו שהיו מקריבין בהמה גשמי' ע\"ג המזבח והיתה נכללת באש שלמטה ובאש שלמעלה, ועי\"ז היתה נתעלי' לשרשה שהוא בחי' פני שור מהשמאל<sup data-n=\"747\">10</sup>, ועי\"ז שהיתה נכללת בשרשה עי\"ז נעשה והחיות נושאות את הכסא דהיינו גם בחי' אדם שעל הכסא, וכמ\"ש ועל דמות הכסא דמות כמראה אדם, והיינו כי אדם הוא בחי' קוין<sup data-n=\"748\">11</sup> בחי' מדות עליונות, חסד דרועא ימינא גבורה דרועא שמאלא כי אמרתי עולם חסד יבנה מכלכל חיים בחסד כו'. אך הנה עצמות אוא\"ס הוא לאו מכל",[["743","6","<b>לע\"ל . . גם הגוף ניזון מזיו השכינה</b>: ראה בארוכה המשך וככה תרל\"ז פפ\"ח ואילך. פצ\"א-ב. ד\"ה אלה תולדות נח תרל\"ז. וראה גם אוה\"ת בראשית לד, סע\"ב ואילך. סה\"מ תרכ\"ט ע' כא-כב. תרנ\"ט ע' קה ואילך. המשך תרס\"ו ע' תקכח. המשך תער\"ב ח\"ג ע' א'תמג. סה\"מ תרח\"צ ע' ריט. ס' השיחות תורת שלום ע' 127 ואילך. ובכ\"מ."],["744","7","<b>וכמ\"ש במד\"ר ע\"פ ואתה מחי' את כולם</b>: ראה שמו\"ר פל\"ב, ד: שאין מלאכי השרת ניזונין אלא מזיו השכינה שנאמר ואתה מחי' את כולם. ושם פמ\"ז, ז: ומאין הי' משה אוכל מזיו השכינה שנאמר ואתה מחי' את כולם. וראה גם אוה\"ת דרושים ליוהכ\"פ ע' א'תקפז-ח."],["745","8","<b>ולהבין זה בתוס' ביאור</b>: בהבא להלן [פרקים ב-ד] ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770301\" data-slug=\"or-hatorah-hb\" data-id=\"8316770301\">אוה\"ת</a> האזינו שם ע' ב'תקכב ואילך. וראה גם מאמרי אדה\"ז תקס\"ד ע' קמג-ד. אוה\"ת אחרי ע' רצז וע' שא-ב. שה\"ש (כרך ב) ע' תפג-ד."],["746","9","<b>אכלתי יערי אבל באתרי' לאו אורחי' למיכל</b>: ראה בכ\"ז [בנוסף להנסמן בהע' הקודמת] סידור עם דא\"ח רנא, ב. ובתוס' הגהות ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940091\" data-slug=\"or-hatorah-hb\" data-id=\"8159940091\">אוה\"ת אחרי ע' צא</a>. ביאוה\"ז להצ\"צ ח\"ב ע' תתריט. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650120\" data-slug=\"or-hatorah-hb\" data-id=\"8316650120\">אוה\"ת</a> שה\"ש שם ע' תפה. וראה גם אוה\"ת ויקרא (כרך ד) ע' תתקצט. פנחס ע' א'עז ואילך. ואתחנן ס\"ע רכד ואילך. נ\"ך ריש ע' שז וע' שח-ט. שם (כרך ב) ע' תתמט."],["747","10","<b>נתעלי' לשרשה . . פני שור מהשמאל</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381243\" data-slug=\"likkutei-torah\" data-id=\"4001381243\">לקו\"ת שה\"ש כח, ג</a>. וראה גם סה\"מ תרכ\"ט ע' סט. וע' קיא."],["748","11","<b>והחיות נושאות את הכסא . . אדם שעל הכסא . . אדם . . בחי' קוין</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370323\" data-slug=\"torah-or\" data-id=\"3901370323\">תו\"א יתרו עב, ד</a> ואילך. סה\"מ תרל\"ב ח\"א ע' יב ואילך וס\"ע טו ואילך."]]],[2002180261,"אינון מדות כלל, לאו דאית לך צדק ידיעא ואינו בערך להיות מקור למדות, וכדי שיהי' התחברות אוא\"ס בבחי' מדות זהו ענין הקרבנות שנק' לחם דהיינו שע\"י הקרבנות שהיו מקריבין ע\"ג המזבח והיתה נכללת בשרשה והיתה עולה עד רזא דא\"ס כידוע, עי\"ז נעשה המשכת אוא\"ס בבחי' מדות כו', וזהו למשל כמו הלחם שמחבר את הנשמה עם הגוף<sup data-n=\"749\">12</sup>, שהגוף אינו בערך אל הנשמה, וכדי שיהי' התחברות הנשמה אל הגוף זהו ע\"י הלחם, שהלחם נתברר באצטומכא ונתהפך לדם, ועי\"ז נמשך ומתחבר הנפש בגוף, כי הדם הוא הנפש וכן אמרו רביעית דם שהנפש תלוי בו דהיינו שבדברים* דקים שבדם<sup data-n=\"750\">13</sup> מלובש הנפש, נמצא שהמאכל הוא ממוצע ומחבר את הנפש עם הגוף, וכך כדי שיהי' התחברות אוא\"ס עם בחי' מדות שנק' בשם גוף וכמ\"ש וכמה גופין תקינת לון, זהו ע\"י הלחם של הקרבנות. ועכשיו שאין לנו קרבנות תפלות כנגד קרבנות תקנו, וע\"כ נק' התפלה בשם אכילה, אכלתי יערי הוא בחי' יוצר אור, כי יוצר אור הוא כדי להעלות ולהפך את הנה\"ב ששרשו מבחי' פני שור, ועי\"ז שמתבונן איך שהמלאכים עומדים ברום עולם ומשמיעים ביראה והם בתכלית הביטול לאלקות עי\"ז נתפעל גם הנה\"ב ומתהפך ג\"כ לקדושה, וע\"י שנתהפך המדות דנה\"ב עי\"ז נעשה בחי' לחם למעלה שיהי' התחברות אוא\"ס בבחי' מדות כו'.\nג) <b>אך</b> זהו דוקא כשבאתי לגני<sup data-n=\"751\">14</sup> אז אכלתי, אז שייך לומר בחי' לחם, אבל באתרי' לאו אורחי' למיכל. והענין הוא דהנה איהו וחיוהי חד ואיהו וגרמוהי חד, והנה עכצ\"ל שאף שאיהו וגרמוהי ג\"כ חד, אעפ\"כ אינו דומה לבחי' איהו וחיוהי<sup data-n=\"752\">15</sup> חד, דא\"כ הי' צ\"ל איהו וחיוהי וגרמוהי חד, וכיון שהוא מחלק ואומר איהו וחיוהי חד ואיהו וגרמוהי חד, ע\"כ צ\"ל שאינו דומה בחי' איהו וחיוהי לבחי' איהו וגרמוהי חד כו'. והנה חיוהי הוא בחי' חכמה וכמ\"ש והחכמה תחי', וגם בינה נק' חיוהי, לפי שחו\"ב הם תרדל\"מ וכיון שחכמה נק' חיוהי ממילא גם בינה נק' חיוהי וכמ\"ש כי עמך מקור חיים שקאי על בחי' בינה כו'. והנה בחי' לחם זה דהיינו מה שע\"י",[["749","12","<b>הקרבנות שנק' לחם . . כמו הלחם שמחבר את הנשמה עם הגוף</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381028\" data-slug=\"likkutei-torah\" data-id=\"4001381028\">לקו\"ת האזינו עו, ב</a>. סה\"מ תרכ\"ט ע' קו ואילך. וע' קיב ואילך."],["750","13","<b>שבדברים דקים שבדם</b>: כ\"ה בכת\"י מעתיק, ואוצ\"ל: שבגידים דקים שבדם. וראה שערי אורה לאדהאמ\"צ צד, ב ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540639\" data-slug=\"torat-chaim\" data-id=\"2300540639\">תו\"ח שמות</a> (הוצאת תשס\"ג) קג, א ואילך (ובמ\"מ שם)."],["751","14","<b>אך זהו דוקא כשבאתי לגני</b>: בהבא להלן ראה אוה\"ת אחרי שם ע' צא. וראה גם אוה\"ת פנחס ע' א'עג."],["752","15","<b>שאיהו וגרמוהי . . אינו דומה לבחי' איהו וחיוהי</b>: ראה ס' מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' סא ואילך וס\"ע סו ואילך. סה\"מ תרל\"ג ח\"ב ע' שמו ואילך. וש\"נ. וככה תרל\"ז פרק עו. סה\"מ תרנ\"ג ע' רכו ואילך. המשך תער\"ב ח\"א ע' שא. ד\"ה איהו וחיוהי תשט\"ז."]]],[2002180262,"אתעדל\"ת שע\"י הקרבנות או תפלה גורם המשכת אלקות זהו דוקא בבחי' איהו וגרמוהי, לפי שגרמוהי הוא בחי' כלים בחי' גוף, וכדי שיהי' התחברות אוא\"ס בבחי' מדות שהוא בחי' גרמוהי<sup data-n=\"753\">16</sup> זהו ע\"י הלחם דוקא, וכמו למשל למטה בנפש האדם. משא\"כ בבחי' איהו וחיוהי חד א\"צ כלל לבחי' לחם לפי שבחכמה מתאחד שם אוא\"ס ממש. וכמו למשל למטה כדי שיתאחדו כחות הנפש עצמן עם הנפש אינו צריך כלל לבחי' לחם, רק כדי שיתחבר הנפש עם הגוף שהגוף אינו בערך כלל אל הנפש שזה רוחני וזה גשמי צריך לבחי' לחם, משא\"כ כחות הנפש עם הנפש שאינו צריך לבחי' לחם, כך בחי' איהו וחיוהי חד שם אינו צריך לבחי' לחם. ואף שנאמר כולם בחכמה עשית שגם החכמה אינו בערך כלל אל אוא\"ס, מ\"מ כלי החכמה הוא באופן אחר ממש, עד שאינו שייך<sup data-n=\"754\">17</sup> לומר כלל על בחי' חכמה בחי' גרמוהי, רק שנק' בחי' חיוהי שהוא בחי' חיות, וע\"כ נעשה בחי' איהו וחיוהי חד גם לא ע\"י לחם העלאת מ\"ן מלמטה למעלה, כי זווג דאו\"א הוא יחוד תמידי תרדל\"מ לעלמין כו' (ומה שאמרו ישראל מפרנסין לאביהם שבשמים שקאי על בחי' חכמה, זהו בחי' חכמה שבמדות מוחין דז\"א, משא\"כ בבחי' חכמה עצמה אינו שייך כלל שם בחי' לחם ישראל מפרנסין). וזהו באתרי' לאו אורחי' למיכל דהיינו בבחי' איהו וחיוהי חד אינו שייך כלל לומר בחי' לחם. ודרך כלל ההפרש בין איהו וחיוהי לאיהו וגרמוהי חד זהו ההפרש בין יחוד י\"ה ליחוד ו\"ה, שבחי' י\"ה שם אינו שייך בחי' לחם, ובבחי' ו\"ה שם שייך בחי' לחם כו'. וזהו שהקרבנות היו רק על המזבח החיצון, משא\"כ על מזבח הפנימי<sup data-n=\"755\">18</sup> לא הי' שום קרבן, לפי שמזבח הפנימי הוא ענין מה שבאתרי' לאו אורחא למיכל, וע\"כ לא היו מקריבין ע\"ג המזבח הפנימי שום קרבן.\nד) <b>ובזה</b> יובן ענין עוה\"ב שאין בו אכילה ושתי'<sup data-n=\"756\">19</sup>, והיינו לפי שבעוה\"ב יהי' בחי' המשכת תוס' אורות, שיהי' התגלות בחי' איהו וחיוהי דהיינו שיהי' התגלות בחי' חכמה, כי אותיות איתן משמשות לעתיד, שלע\"ל יהי' התגלות בחי' איתן בחי' חכמה כו' שהוא בחי' איתן. וזהו מ\"ש ביוסף ותשב באיתן קשתו<sup data-n=\"757\">20</sup>, והיינו כי יוסף הוא ע\"ש תוס' אורות שקאי על לע\"ל וכמ\"ש והי' ביום ההוא יוסיף אד' שנית ידו, ולע\"ל יהי' גילוי בחי' איתן שהוא בחי' י\"ה, ע\"כ נא' ביוסף ותשב באיתן קשתו",[["753","16","<b>חיוהי הוא בחי' חכמה . . וגם בינה . . שגרמוהי הוא בחי' כלים . . מדות שהוא בחי' גרמוהי</b>: בהמשך מים רבים תרל\"ו ע' קסה [ועד\"ז בכ\"מ שנסמנו בהערה הקודמת, ובליקוט פירושים ומ\"מ לתניא אגה\"ק ריש ס\"כ] מובא ב' פירושים בחיוהי וגרמוהי: א', פי' רבינו הזקן שחיוהי הם האורות גם האורות דזו\"נ וגרמוהי הם הכלים גם כלי החכמה ובינה. ב', פי' האריז\"ל שחיוהי הם ג' ראשונות האור וכלי, וגרמוהי הם ז' תחתונות האור וכלי. ובכ\"מ נכללו שני הפירושים יחד. וראה עד\"ז בסה\"מ תש\"ח ע' 161. ועוד."],["754","17","<b>שאינו שייך לומר כלל על בחי' חכ' בחי' גרמוהי</b>: ראה גם אוה\"ת אחרי ע' פו וע' צא."],["755","18","<b>וזהו שהקרבנות היו רק על המזבח החיצון משא\"כ על מזבח הפנימי</b>: ראה גם לקו\"ת האזינו עח, ד. דרושים לשמע\"צ פז, סע\"א. מאמרי אדה\"ז תקס\"ד ס\"ע סו ואילך. וע' עב ואילך. מאמרי אדהאמ\"צ שמות ח\"ב ע' תרעג ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550132\" data-slug=\"torat-chaim\" data-id=\"2300550132\">תו\"ח שמות תמג, א</a> ואילך. דרך מצותיך פו, ב ואילך. אוה\"ת ויקהל ע' ב'קפה-ו. ב'קצה ואילך. ב'ריג ואילך. סה\"מ תרל\"ה ח\"א ע' קלז ואילך. תרנ\"א ע' קלה ואילך. סה\"מ מלוקט ח\"ב ע' קכב-ג. ד\"ה תפלה לדוד תשמ\"ז. ועוד."],["756","19","<b>ובזה יובן ענין עוה\"ב שאין בו אכילה ושתי'</b>: בהבא להלן [עד סוף הפרק] ראה גם לקו\"ת דרושים לשבת שובה סה, ד. מאמרי אדה\"ז תקס\"ח ח\"א ס\"ע קעא-ב. תק\"ע ע' נט. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770407\" data-slug=\"or-hatorah-hb\" data-id=\"8316770407\">אוה\"ת שה\"ש (כרך ב) ע' תשעה</a>-ו וע' תשצא-ב. שם (כרך ג) ע' א'כד-ה. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380138\" data-slug=\"likkutei-torah\" data-id=\"4001380138\">לקו\"ת צו טו, ג</a>-ד. אוה\"ת ואתחנן שם ס\"ע רכד ואילך. נ\"ך שם ע' שח-ט."],["757","20","<b>וזהו מ\"ש ביוסף ותשב באיתן קשתו</b>: ראה גם אוה\"ת ויחי שפז, ב. שצב, סע\"א ואילך."]]],[2002180263,"כו'. ולכן הי' יוסף חלוק מכל השבטים, כי השבטים היו מרכבתא תתאה כי השבטים הם בבריאה כשם שאין בלבך כו' יחו\"ת<sup data-n=\"758\">21</sup>, משא\"כ יוסף הי' מבחי' אצי' שהוא בחי' תוס' אורות כו', דהיינו שיהי' התגלות בחי' י\"ה וכמ\"ש ביום ההוא יהי' ב\"פ י\"ה דהיינו שגם בו\"ה יהי' התגלות בחי' י\"ה ממש, ואף שגם עתה נמשך בחי' י\"ה בו\"ה זהו רק המשכת ההארה, משא\"כ לע\"ל יהי' התגלות בחי' י\"ה בו\"ה ממש, וע\"כ אין בו אכילה ושתי'. וגם הגוף גשמי יהי' ניזון מאלקות ולא יהא צריך לבחי' לחם, וכמו שמצינו במשה שהי' בהר ארבעים יום לחם לא אכל, לפי שהי' ניזון מאלקות ממש רק שבמשה הי' לפי שעה, וגם איתא במדרש שהי' מצטער, והיינו לפי שהי' ילוד אשה ע\"כ לא הי' יכול הגוף שלו כלל לקבל את עוצם הגילוי הגדול, משא\"כ לע\"ל שיתבררו הגופים וכמ\"ש ועצמותיך יחליץ, דהנה עכשיו שינתה הארץ, דהנה כתיב תדשא הארץ כו' עץ פרי שיהי' טעם עצו ופריו שוה<sup data-n=\"759\">22</sup>, והיינו שהגוף נק' עץ וכמ\"ש כי האדם עץ השדה והנשמה נק' פריו, והי' הציווי שהגוף יהי' כמו הנשמה ולא יהי' הגוף מסתיר, ועכשיו שינתה הארץ שאין טעם עצו ופריו שוה, שאין הגוף כמו הנשמה, משא\"כ לע\"ל יהי' טעם עצו ופריו שוה, שהגוף יהי' כמו הנשמה ממש, ע\"כ גם הגוף יהי' יכול לקבל גילוי אלקות ויהי' ניזון מזיו השכינה<sup data-n=\"760\">23</sup> ולא יהי' צריך למזון גשמי כלל כו', וה\"ז עוד תירוץ איך יוכל הגוף להיות ניזון מזיו השכינה.\nה) <b>אך</b> עדיין צ\"ל שהרי איתא שלית מח' תפיסא בי' כלל, ואיך יהיו יכולים לקבל גילוי בחי' איתן שהוא בחי' גילוי עצמות החכמה שהרי לית מח' תפיסא בי' כלל. אך הענין הוא דהנה איתא בזהר<sup data-n=\"761\">24</sup> לית מח' תפיסא בי' אבל נתפס הוא ברעותא דליבא, והענין הוא דהנה רעו\"ד הוא בחי' רצון פשוט, דהנה אית רצון ואית רצון, אית רצון הנמשך ע\"פ שכל והשגה דהיינו שע\"י שמתבונן באלקו' בבחי' השגה והבנה עי\"ז נמשך לו הרצון לאלקות. אך זהו עדיין בחי' חיצוני' הלב, לפי שרצון זה נמשך מבחי' דעת והשגה כו'. אך פנימי' הלב הוא בחי' רעו\"ד שהוא בחי' רצון פשוט",[["758","21","<b>השבטים . . בבריאה כשם שאין בלבך . . יחו\"ת</b>: ראה בכ\"ז בארוכה לעיל ח\"א ד\"ה הללוי' גו' במרומים. וש\"נ."],["759","22","<b>לע\"ל שיתבררו הגופים וכמ\"ש ועצמותיך יחליץ . . שיהי' טעם עצו ופריו שוה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381130\" data-slug=\"likkutei-torah\" data-id=\"4001381130\">לקו\"ת ברכה ק, סע\"ב</a>. מאמרי אדה\"ז תקס\"ו ע' קפא-ב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770091\" data-slug=\"or-hatorah-hb\" data-id=\"8316770091\">אוה\"ת</a> בראשית לב, סע\"ב ואילך. ראה גם אוה\"ת אחרי שם ע' פו. וע' צא. שה\"ש (כרך ב) ע' תפד. ביאוה\"ז להצ\"צ ח\"ב ע' תרעה. סה\"מ תרכ\"ט ע' כב."],["760","23","<b>וה\"ז עוד תירוץ . . השכינה</b>: תיבות אלו נוספו בגוכתי\"ק בספר תרל\"ט."],["761","24","<b>איתא בזהר לית מח' תפיסא בי' אבל נתפס הוא ברעו\"ד</b>: ”כן הובא בשם הזהר בכ\"מ בדא\"ח. וראה זח\"ג רפט, ב (באד\"ז): דלא אתידע ולא אשתמודע כו' אלא ברעותא דלבא. ובתקו\"ז בהקדמה (”פתח אליהו\") יז, א: לית מחשבה תפיסא בך כלל\" (סה\"מ מלוקט ח\"ה ע' צד הערה 19). במאמרי אדה\"ז תקס\"ג שם ע' שסג הובא בשם הר\"מ. וראה גם [נוסף להנסמן לעיל בתחילת המאמר] תו\"א וישב כו, א. מאמרי אדהאמ\"צ במדבר ח\"ב ע' תטו. אוה\"ת תצא ע' תתר-רא. סה\"מ תרס\"ט ריש ע' קעו."]]],[2002180264,"שלמעלה מהשכל והשגה בבחי' מס\"נ ממש, וזהו בחי' איתן<sup data-n=\"762\">25</sup> שהוא בחי' קשה, בחי' קשה עורף הוא, רצון שלמעלה מן השכל. ובזה יובן מה שריב\"ז בכה וא' איני יודע באיזה דרך מוליכין אותי<sup data-n=\"763\">26</sup>, ולכאורה אינו מובן הלא ארז\"ל אמרו עליו על ריב\"ז שלא הניח דבר גדול ודבר קטן והי' עוסק בתומ\"צ כל ימי חייו ואעפ\"כ בכה וא' שאינו יודע באיזה דרך כו'. אך לפי הנ\"ל יובן דמה שהוא ע\"פ השגה ושכל בזה לא הי' טועה, כי מה שהוא מחכמה ולמטה דהיינו בבחי' רצון התחתון הי' יודע שיצא ידי חובת שמים, אך מה שבכה זהו שמחמת ענוה טעה בעצמו בבחי' רעו\"ד שלמעלה מן השכל והשגה שהוא בחי' מס\"נ, בזה טעה ואמר שאינו יודע, אבל בבחי' הרצון שנמשך מבחי' השכל בזה לא הי' יכול לטעות כלל כו'.\nוא\"ו) <b>והנה</b> להבין מאין נמשך בחי' רצון פשוט זה שלמעלה מן השכל בנפש. הענין הוא, דהנה כתיב בנים אתם להוי' אלקיכם, ולכאורה אינו מובן איך שייך לומר בנים להוי' אלקיכם. אך הענין הוא, דהנה כמו שהבן נמשך ממוח האב<sup data-n=\"764\">27</sup> דהיינו מבחי' עצמות החכמה ואינו כמו שאר השפעה כמו שכל או דבור שנמשך ג\"כ מבחי' חכמה אך זהו רק חיצוני' החכמה, וזהו ענין המלאכים שאף ששרשן ג\"כ מבחי' חכמה אך זהו רק חיצוני' החכמה, משא\"כ נש\"י עלו במח' דהיינו במח' הקדומה שהוא בחי' עצמות החכמה, וכמ\"ש עם המלך במלאכתו ישבו, במי נמלך בנשמותיהן של צדיקים, וע\"כ נק' בנים כמו שהבן נמשך מעצמותו שהרי מוליד בדומה לו ממש, כך נש\"י שרשן מבחי' עצמות החכמה ממש. והנה לפי שנש\"י נמשכין מבחי' עצמות החכמה בחי' איתן, ע\"כ נמצא בהם בחי' רעו\"ד רצון פשוט שלמעלה מן השכל.\n<b>אך</b> הנה בחי' רעו\"ד הוא בבחי' אהבה מוסתרת שאינו בגילוי כו', וכדי שיומשך מן ההעלם אל הגילוי כו' זהו דוקא ע\"י רצון התחתון הנמשך מבחי' השגה ושכל כו', שחיצוני' הלב הוא כלי לבחי' פנימי' הלב, שמתחלה צריך שיתבונן באלקות בבחי' השגה והבנה, ועי\"ז אח\"כ נמשך בבחי' רעו\"ד הנמשכת מבחי' עצמי' החכמה. וזהו מ\"ש ואהבת את הוי' אלקיך, ולכאורה אינו מובן איך שייך ציווי על האהבה<sup data-n=\"765\">28</sup> כו',",[["762","25","<b>פנימי' הלב הוא בחי' רעו\"ד . . וזהו בחי' איתן</b>: באוה\"ת האזינו שם ע' ב'תקכב כותב ע\"ז: אף כי משכיל לאיתן זהו חכמה, ורעו\"ד זהו פנימיות הלב. וי\"ל כי פנימיות הלב מתאחדת עם המוח כמ\"ש בד\"ה בכ\"ה בכסלו [<a class=\"ft-cite\" href=\"#/read/torah-or/3901370137\" data-slug=\"torah-or\" data-id=\"3901370137\">תו\"א וישב כט, ג</a>] ובד\"ה הנך יפה רעייתי [<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381184\" data-slug=\"likkutei-torah\" data-id=\"4001381184\">לקו\"ת שה\"ש יג, ד</a>] בפירוש יפה את רעייתי רעו\"ד, כתרצה הרצון שבמוח, וכמש\"ש בענין נחל איתן ההמשכה מבחי' איתן בו\"ק."],["763","26","<b>שריב\"ז בכה וא' איני יודע באיזה דרך מוליכין אותי</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380295\" data-slug=\"likkutei-torah\" data-id=\"4001380295\">לקו\"ת</a> הוספות לס' ויקרא נ, ד. מאמרי אדה\"ז הקצרים ע' שט. על מארז\"ל ע' לא [ובהנסמן בהמ\"מ שם]. אוה\"ת פנחס ע' א'נט ואילך. סה\"מ תרכ\"ו (הוצאת תשמ\"ט) ע' קעב ואילך. תרל\"ב ח\"ב ע' שנא ואילך וע' שצט ואילך. תרמ\"ו ס\"ע יד ואילך. תרע\"ח ע' שסא ואילך. עטר\"ת ע' שעט ואילך. תרפ\"א ע' שיג ואילך. תרפ\"ד ע' רמ ואילך. תרפ\"ז ע' רכז ואילך. תרפ\"ח ע' קיג ואילך. תרצ\"ו ע' 50 ואילך. ה'ש\"ת ע' ב ואילך. סה\"מ מלוקט ח\"א ע' קלט ואילך. ועוד."],["764","27","<b>בנים אתם להוי' אלקיכם . . כמו שהבן נמשך ממוח האב</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>. אוה\"ת האזינו שם ע' א'תרמג."],["765","28","<b>ואהבת את הוי' . . איך שייך ציווי על האהבה</b>: ראה גם לעיל ס\"ע סו. וש\"נ."]]],[2002180265,"אך הענין הוא לפי שהאהבה ישנו בטבע בכל א' לפי שנש\"י עלו במח', רק שהאהבה היא מוסתרת ונעלמ' וצריך להמשיכה מההעלם אל הגילוי ע\"י התבוננות כו'. והנה אח\"כ כתיב והיו הדברים האלה דהיינו שהכלי לבחי' אהבה זו היא בחי' התורה דוקא, וכמארז\"ל בספרי שמתוך כך אתה מכיר את מי שאמר והי' העולם כו'.\n<b>וזהו</b> מ\"ש<sup data-n=\"766\">29</sup> כל הנק' בשמי ולכבודי בראתיו יצרתיו אף עשיתיו, כל הוא בחי' נש\"י שנק' כל, ובחי' כל<sup data-n=\"767\">30</sup> זה הוא הנק' בשמי, שמי הוא בחי' מל' שהוא בחי' זיו והארה בעלמא, ונש\"י הם הממשיכים בבחי' שמי, והכלי לבחי' המשכה זו זהו מ\"ש אח\"כ ולכבודי בראתיו אין כבוד אלא תורה, בראתיו הוא בחי' תושב\"כ, ויצרתיו הוא בחי' תושבע\"פ, דהנה כתיב יוצר אור ובורא חשך, שבריאה נק' חשך לפי שהוא בחי' העלם כו', וכך תושב\"כ הוא בחי' העלם לפי שהוא ברמז ובקיצור גדול ואינו מבואר בה עדיין איך לעשות המצוה, כמו תפילין אעפ\"י שנאמר בה מצות תפילין עדיין אינו יודע איך לעשות התפילין, וע\"כ נק' בראתיו בורא חשך, ותושבע\"פ נק' יצרתיו לפי שהוא בחי' גילוי ההעלם<sup data-n=\"768\">31</sup> בחי' צורה לחומר, שנת' בה כל מצוה ומצוה איך לעשותה. אף עשיתיו הוא בחי' מעשה המצות, וע\"כ נאמר עשיתיו, כי אף הוא מרבה בחי' רביעית<sup data-n=\"769\">32</sup>, והיינו כדי שיגיעו לבחי' רעו\"ד רצון פשוט שלמעלה מן השכל זהו דוקא ע\"י מעשה המצות, לפי שמעשה הוא בחי' כפי' והכרח כמו גט המעושה, מעשין על הצדקה שהוא ענין כפי' והכרח ביטול הרצון שלמעלה מן השכל, וע\"י ביטול רצון זה יגיעו לבחי' רעו\"ד. וזהו מ\"ש שמוע מזבח טוב<sup data-n=\"770\">33</sup>, שמוע הוא ענין ביטול הרצון בלי טו\"ד הוא למעלה יותר, כי שאול הלך אחר הטעם וא' הקימותי את דבר ה', אך טעה בזה כי צריך להיות בחי' שמיעה ביטול הרצון בלי טו\"ד, וזהו טוב יותר. וזהו דעת המ\"ד מעשה גדול לפי שמעשה הוא בחי' ביטול<sup data-n=\"771\">34</sup>, ועי\"ז נמשך המשכת אוא\"ס שא\"א כ\"א ע\"י צמצום, וכדי שיהי' בחי' צמצום זה זהו דוקא ע\"י ביטול הרצון התחתון. וזהו אף עשיתיו, שאף הוא מרבה בחי' רביעית דהיינו בחי' רעו\"ד. אך ע\"ז נאמר אל תט באף עבדך<sup data-n=\"772\">35</sup>, כי ג' פתחו באף, ומבחי' אף עשיתיו יכול ח\"ו ליפול בבחי' אף שהוא ענין ג\"ק הטמאות, וע\"ז ביקש דוד אל תט באף עבדך, ויש ב' מיני עבד, כי עבד הוא בחי' קבלת עול שהוא ענין יראה, ויש ב' מיני יראה יר\"ע ויר\"ת, והיינו",[["766","29","<b>וזהו מ\"ש כל הנקרא בשמי ולכבודי</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380586\" data-slug=\"likkutei-torah\" data-id=\"4001380586\">לקו\"ת ר\"פ בלק סז, א</a> ואילך. ועוד."],["767","30","<b>ובחי' כל זה הוא הנקרא בשמי</b>: במאמרי אדה\"ז תקס\"ז שם ע' שסו מוסיף: דהנה פי' כל הנקרא בשמי היינו ענין לשון נפעל שנקרא ונמשך בתוך שמי כי כך מורה לשון הנקרא בשמי שבחי' שמי למטה ממי שנקרא ונמשך שם מלמעלה."],["768","31","<b>תושב\"כ . . ברמז ובקיצור גדול . . ותושבע\"פ . . גילוי ההעלם</b>: ראה בכ\"ז בארוכה לעיל ד\"ה החודש הזה לכם. וש\"נ."],["769","32","<b>אף הוא מרבה בחי' רביעית</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380097\" data-slug=\"likkutei-torah\" data-id=\"4001380097\">לקו\"ת ויקרא ה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380597\" data-slug=\"likkutei-torah\" data-id=\"4001380597\">בלק סט, ד</a>."],["770","33","<b>וזהו מ\"ש שמוע מזבח טוב</b>: ראה סה\"מ תרכ\"ט ע' שו. וש\"נ."],["771","34","<b>מעשה גדול לפי שמעשה הוא בחי' ביטול</b>: ראה בכ\"ז בארוכה לעיל ד\"ה ושננתם. וש\"נ."],["772","35","<b>אך ע\"ז נאמר אל תט באף עבדך</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381019\" data-slug=\"likkutei-torah\" data-id=\"4001381019\">לקו\"ת</a> דרושים לשבת שובה סז, א. האזינו עד, סע\"א."]]],[2002180266,"שע\"י התהפכות בחי' אף דוקא שהו\"ע אתהפכא מחשוכא לנהורא, עי\"ז הוא מרבה בחי' רביעית, שיגיע לבחי' רעו\"ד שהוא בחי' יר\"ע כו', ולזה סובר המ\"ד מעשה גדול כו'. וזהו מ\"ש וצדקה כנחל איתן כו', שע\"י צדקה דוקא שהוא בחי' מעשה עי\"ז נמשך בחי' נחל איתן שהוא בחי' רעו\"ד.\nז) <b>אך</b> צ\"ל שהרי סתם לן תנא שת\"ת כנגד כולם, שמשמע שאין בזה פלוגתא כלל. אך הענין הוא דהנה כתיב יערוף כמטר לקחי תזל כטל אמרתי, שיש שני בחי' בתורה בחי' מטר ובחי' טל<sup data-n=\"773\">36</sup>. והנה מטר שהוא מים, מים יורדים מגבוה לנמוך שהוא ענין המשכת התורה לברר בירורים כשר פסול כו', וזהו ענין התורה ששייך לבחי' מעשה תלמוד גדול כו' מפני שמביא לידי מעשה. אך יש בחי' בתורה שנק' בשם טל, והנה טל הוא בחי' אור וכמ\"ש כי טל אורות טליך, שאור הוא למעלה מבחי' מים, והיינו שהוא בחי' תורה שאינו שייך למעשה כלל. וכמו למשל תורה של ענין הקרבנות שאינם שייכים עתה למעשה כלל, ודרך כלל טל תורה הו\"ע פנימי' התורה, כי טל הוא בחי' א' עם מן וכמ\"ש וברדת הטל על המחנה לילה ירד המן עליו, והנה מן הוא לחם מן השמים שהוא מזונא דחכמתא שהו\"ע פנימי' התורה, וזהו ענין טל תחי' שיהי' לע\"ל<sup data-n=\"774\">37</sup>, וכמשארז\"ל כל העוסק בתורה טל תורה מחייהו, והיינו שלע\"ל יהי' גילוי בחי' טל תורה כו'. ועוד יש מעלה בטל, דהנה ארז\"ל כנס\"י שאלה שלא כהוגן ויבא כגשם לנו, והקב\"ה השיבם כהוגן אהי' כטל לישראל, וההפרש שבין גשם לטל שגשם הוא מלמטה למעלה דהיינו בבחי' אתעדל\"ת אתעדל\"ע, אבל טל לא מיעצר לעלמין לפי שהוא בחי' אתעדל\"ע לבד בלי אתעדל\"ת כלל. וזהו מ\"ש סתם ות\"ת כנגד כולם שמשמע שאין בזה שום מחלוקת כלל, והיינו כי בבחי' גשם של תורה שהוא בחי' תורה השייך למעשה בזה יש מחלוקת שיש סברא שתלמוד גדול, ויש סברא שמעשה גדול, אך בבחי' טל תורה בזה אין שום מחלוקת שכ\"ע סברי שת\"ת כנגד כולם.\n<b>והנה</b> בזה יובן ענין ירח האתנים שהוא חדש תשרי, והיינו כי בחדש תשרי הוא התגלות בחי' איתן, וזהו מ\"ש כל האזרח בישראל ישבו בסוכות, כל האזרח בישראל היינו בחי' איתן האזרחי שהוא בחי' טל תורה כו', בחי' אתעדל\"ע לבד",[["773","36","<b>שיש שני בחי' בתורה בחי' מטר ובחי' טל</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381015\" data-slug=\"likkutei-torah\" data-id=\"4001381015\">לקו\"ת האזינו עג, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381020\" data-slug=\"likkutei-torah\" data-id=\"4001381020\">עד, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380488\" data-slug=\"likkutei-torah\" data-id=\"4001380488\">עטרת ראש מד, א</a> ואילך. פירוש המלות לאדהאמ\"צ י, ג. מאמרי אדהאמ\"צ במדבר ח\"ב ע' שנד. וע' תרמג ואילך. סה\"מ תרכ\"ט ע' תד ואילך. וש\"נ. תרל\"ד ע' מא. וע' מג. המשך תער\"ב ח\"ב ס\"ע א'סט ואילך."],["774","37","<b>מן הוא לחם מן השמים . . טל תחי' שיהי' לע\"ל</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380768\" data-slug=\"likkutei-torah\" data-id=\"4001380768\">לקו\"ת ר\"פ עקב יג, ג</a> ואילך."]]],[2002180267,"שיהי' בבחי' גילוי לע\"ל ישבו בסוכות, דהיינו שעתה בסוכות נמשך בחי' איתן האזרחי, אך שהוא רק בבחי' מקיף<sup data-n=\"775\">38</sup> לבד. והנה איתן הוא אותיות תנאי, והיינו שמתחלה צריך שיהי' בחי' תנאים וכמ\"ש וישב הים לפנות בקר לאתנו, וארז\"ל לתנאו, שע\"י שמקיים את התנאי עי\"ז בא לאיתנו, וכך שיבא לבחי' איתן צריך שיהי' מתחלה בחי' תנאים שהוא ענין גשם של תורה שהוא בחי' אתדל\"ת ויבא כגשם לנו, ובחי' זו נק' תנאים אם יש אתעדל\"ת אז הוא בחי' אתעדל\"ע, ואם לאו שאין אתעדל\"ת ממילא אין אתעדל\"ע שזהו בחי' תנאים, וזהו מ\"ש אם בחוקתי תלכו אם הוא תנאי וכשמקיימים התנאי אז ונתתי גשמיכם בעתם, ולהיפך ח\"ו נא' ואם לא תשמעו כו'. ובעבודה זהו\"ע עשרת ימי תשובה שהוא בחי' אתעדל\"ת, ועי\"ז נמשך אח\"כ בסוכות בחי' איתן כל האזרח בישראל, אך עתה הוא רק בבחי' מקיף, ולע\"ל יהי' בבחי' גילוי ממש, טל תורה מחייהו כו'.",[["775","38","<b>כל האזרח בישראל היינו בחי' איתן האזרחי . . ישבו בסוכות . . בבחי' מקיף</b>: ראה לקו\"ת דרושים לשמע\"צ פח, ג. מאמרי אדה\"ז הקצרים ס\"ע עג-ד. תקס\"ד ע' רלא. סה\"מ תרכ\"ז ע' תט. תרכ\"ט ע' שפג. תרל\"ב ח\"ב ע' תקכד. ע' תקכט. תרל\"ו ח\"ב ע' שסט. המשך תער\"ב ח\"א ע' קנז. סה\"מ תש\"ג ע' 52. סה\"מ מלוקט ח\"א ע' קעט. רנא. שנט. תמו. ועוד."]]],[2002180268,"<h3>מזמור לתודה (ש\"פ אמור)</h3>\n<b>ש\"פ אמור ט\"ל, לפ\"ק.</b>\n<b></b><b>הנחות כ\"ק אדמו\"ר אור עולם נזר ישראל ותפארתו כקש\"ת מוהר\"ר שלום דובער זצוקללה\"ה נבג\"מ זי\"ע מליובאוויטש</b>\n<b>מזמור</b> לתודה<sup data-n=\"776\">1</sup> 'הריעו 'לה' 'כל 'הארץ ר\"ת הלכה, וצ\"ל מה שייך הלכה לתודה. והענין דהנה אמרז\"ל כל הקרבנות בטלים לע\"ל<sup data-n=\"777\">2</sup> חוץ מקרבן תודה, והלכות ג\"כ אינם בטלות לע\"ל לכן שייך הלכות לקרבן תודה. והנה על מה שאמרז\"ל כל הקרבנות בטלים לע\"ל מקשים והלא אנו אומרים בנוסח תפלת מוסף ושם נעשה לפניך את קרבנות חובותינו הרי שם נעשה כו'. והתירוץ הוא שקרבנות לא יהי' בטלים לע\"ל רק קרבנות יחיד, ומ\"מ קרבן תודה יהי' שייך לע\"ל ג\"כ. והנה אי' בסידור האריז\"ל מזמור לתודה הוא או\"א דיצי', והענין דהנה אמרז\"ל ארבעה צריכים להודות<sup data-n=\"778\">3</sup> יורדי הים כו' ופירש\"י כשיוצאים מהסכנה אז צריכים להודות, ומספר הארבעה הוא נגד ד' אותיות הוי'<sup data-n=\"779\">4</sup> ונגד ד' גאולות ונגד ד' לשונות של גאולה והוצאתי והצלתי וגאלתי ולקחתי.\n<b>והענין</b> דהנה כתי' אל דעות הוי' שיש ב' דעות ד\"ע וד\"ת, וע\"ד הקבלה הם יסוד אבא ויסוד ז\"א, ועל ל' החסידות ד\"ע הוא איך שכלא קמי' כל\"ח ולמעלה היש ולמטה אין, וד\"ת הוא שלמטה הוא יש ולמעלה אין, וזהו\"ע בריאה יש מאין. דיש השתל' עו\"ע והוא כמו מחו\"ד הרי הי' הדיבור תחלה במח', וכמו מדות ושכל היו המדות תחלה כלולים בשכל, דהנה לידת המדות הם מהשכל, דהנה אמרז\"ל חמשים שערי בינה נבראו בעולם<sup data-n=\"780\">5</sup>, דמלך הוי' הגדולה עד לך ה' הממלכה יש ז' מדות וכ\"א כלול מז', דתיקון הוא התכללות, הרי מ\"ט, דכל פרט ופרט היינו חסד שבחסד גבו' שבחסד יש לו שער בפ\"ע שממנו נולד, דהנה המדה שהוא רצון לאיזהו דבר ה\"ז מצד ההתבוננות שמתבונן בשכלו שטוב לו הדבר ההוא רוצה בו, וזהו הטיית השכל לדבר ההוא, ונמשך ממוח ללב דעיקר המדות הם בלב ונמשכים מהמוח ללב, והטיות השכל זהו השער שממנו נולד המדה, הרי המדה קודם שנולדה היתה כלולה בהמוח ונק' אז מדות שבשכל והיו בהעלם ונמשכו מהעלם לגילוי, וכמו\"כ השתל' עו\"ע העלול הי' כלול תחלה בהעילה ואח\"כ יצא מהעלם אל הגילוי. וכמו\"כ דיבור ומח', דקודם שדובר צריך לחשוב תחלה, ובעת שדובר צריך ג\"כ",[["776","1","<b>מזמור לתודה</b>: הוא הנחת כ\"ק אדמו\"ר מהורש\"ב, מהמאמר שנדפס לעיל ע' שסז ואילך. וראה בהנסמן שם לכללות המאמר."],["777","2","<b>אמרז\"ל כל הקרבנות בטלים לע\"ל</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650243\" data-slug=\"or-hatorah-hb\" data-id=\"8316650243\">אוה\"ת נ\"ך (כרך ב) ע' תתקעב</a>. תתקפו. יהל אור לתהלים ע' שסט. שעב."],["778","3","<b>והענין דהנה אמרז\"ל ארבעה צריכים להודות</b>: בכ\"ז ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650247\" data-slug=\"or-hatorah-hb\" data-id=\"8316650247\">אוה\"ת נ\"ך שם ס\"ע תתקעו</a> ואילך. וראה בהבא לקמן גם מאמרי אדהאמ\"צ נ\"ך ע' קנב ואילך."],["779","4","<b>ומספר הארבעה הוא נגד ד' אותיות הוי'</b>: ראה גם יהל אור לתהלים ע' תיט. סה\"מ תשמ\"ו (הוצאת תשס\"ב) ע' 219. תשמ\"ח (הוצאת תשס\"ב) ע' 427."],["780","5","<b>דהנה אמרז\"ל חמשים שערי בינה נבראו בעולם</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380351\" data-slug=\"likkutei-torah\" data-id=\"4001380351\">לקו\"ת במדבר י, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380663\" data-slug=\"likkutei-torah\" data-id=\"4001380663\">מטות פה, ב</a>. ובארוכה סה\"מ תרנ\"ח ע' לט. תרע\"ח ע' פו-ז. תרח\"צ ע' קסג ואילך. וראה גם פיה\"מ לאדהאמ\"צ צט, א. סה\"מ מלוקט ח\"ה ס\"ע עה ואילך. וש\"נ."]]],[2002180269,"לחשוב שאם אינו חושב אין להדיבור חיות כלל, הרי הי' הדיבור כלול תחלה במח' ואח\"כ יצא מהעלם לגילוי, וזהו ג\"כ משל להשתל' עו\"ע.\n<b>אבל</b> בריאה יש מאין אינו שייך לומר שמציאות העולם, היש כמו שהוא, הי' כלול בהאין דכמו שאומרים החוקרים שהוא דבר מלא דבר<sup data-n=\"781\">6</sup>, פי' שמלא דבר נעשה דבר, אינו שייך לומר שבלא דבר הי' דבר, וכמו\"כ מה שאומרים יש מאין הנה יש הוא מה שמושג ואין הוא דבר בלתי מושג ואיך שייך לומר שבדבר בלתי השגה יהי' השגה, שאם נא' שיש בו השגה ה\"ה יש, דתי' אין שולל ההשגה שאינו מושג, ובל' תורה שמרצון וחפץ ה' נעשה מציאות שהוא יש ודבר נפרד מאין שהוא אינו מושג, שבתורה אין אנו מוצאים כ\"א ל' בריאה<sup data-n=\"782\">7</sup> וכמו אם בריאה יברא ופי' רש\"י אם בריאה כו' ואם לאו יברא ה' (ובגמ' פריך והלא אין כל חדש תחת השמש ומתרצין<sup data-n=\"783\">8</sup>).\n<b>וזהו\"ע</b> בריאה יש מאין והוא ענין ד\"ת, והוא ג\"כ אמת שה\"ה שם אלקים, דל\"ב פעמים אלקים במע\"ב, דאלקים בגי' הטבע. והנה הגם שא\"צ ראיות ששם אלקים הוא אמת שה\"ה מז' שמות שאינם נמחקים, מ\"מ ה\"ז מרומז בתורה דכתי' בראשית ברא אלקים, ול\"ב פעמים ש' אלקים יש במע\"ב, ובסוף כתי' אשר בר\"א אלקי\"ם לעשו\"ת ס\"ת אמת<sup data-n=\"784\">9</sup> להורות דשם אלקים הוא אמת. אך יש מדרי' באמת, יש שפת אמת, ואמת, ואמת לאמיתו<sup data-n=\"785\">10</sup>. וביאור הענין דהנה כתי' תתן אמת ליעקב ומקשים ו[כי] שייך לומר שחו\"ג אינו אמת ח\"ו<sup data-n=\"786\">11</sup>, והענין דחו\"ג יש להם מנגדים דחסד מנגד לגבורה וגבורה מנגד לחסד, דמצד החסד להשפיע לכל דטבע הטוב להיטיב שישפיע לכל והטוב הוא שלא יהיו דקדוקים כלל, והגבו' הוא מונע ומעכב ההשפעה וה\"ז הפסק, וכמו\"כ מצד הגבו' הן שמים לא זכו בעיניו, ומצד החסד ישפיע, הרי יש להם מנגדים אבל מדת הת\"ת הוא מדת הרחמים, דמדה\"ד קאמר שע\"פ הדין א\"צ",[["781","6","<b>דכמו שאומרים החוקרים שהוא דבר מלא דבר</b>: לעל ע' שסט הובא זה בשם הרס\"ג. וראה בהנסמן שם."],["782","7","<b>שבתורה אין אנו מוצאים כ\"א ל' בריאה</b>: ראה פי' הרמב\"ן עה\"ת קרח טז, ל. (הובא לעיל ע' שסט. וש\"נ)."],["783","8","<b>(ובגמ' פריך והלא אין כל חדש תחת השמש ומתרצין)</b>: ראה סנהדרין קי, סע\"א: דרש רבא מאי דכתיב ואם בריאה יברא ה' ופצתה האדמה את פיה, אמר משה לפני הקב\"ה אם בריאה גיהנם מוטב, ואם לאו יברא ה', למאי אילימא למבריה ממש והא אין כל חדש תחת השמש (ואי גיהנם לא איברי עד ההוא שעתא הוה ליה חדש — רש\"י), אלא לקרובי פתחא (שיקרב פתחה של גיהנם ותפתח הארץ במקום שהן, רש\"י). וראה גם נדרים לט, ב. ועוד."],["784","9","<b>אשר בר\"א אלקי\"ם לעשו\"ת ס\"ת אמת</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560089\" data-slug=\"or-hatorah-hb\" data-id=\"8316560089\">אוה\"ת בראשית (כרך ג) תקיא, א</a>. אוה\"ת נ\"ך (כרך ב) שם ע' תתקעז. סה\"מ תרל\"ה ח\"ב ע' רצ. עטר\"ת ע' תה. הש\"ת ע' 80."],["785","10","<b>אך יש מדרי' באמת, יש שפת אמת, ואמת, ואמת לאמיתו</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310018\" data-slug=\"tanya\" data-id=\"3401310018\">תניא פי\"ג (יט, א</a>). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380248\" data-slug=\"likkutei-torah\" data-id=\"4001380248\">לקו\"ת בהר מ, א</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450686\" data-slug=\"or-hatorah-hb\" data-id=\"8316450686\">אוה\"ת ראה ע' תרפו</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600595\" data-slug=\"or-hatorah-hb\" data-id=\"8316600595\">נ\"ך ע' תקצה</a>. סה\"מ תרכ\"ז ע' שצט. תרכ\"ט ס\"ע שיד ואילך. תרל\"ו ח\"ב ע' שיט-כ."],["786","11","<b>דהנה כתי' תתן אמת ליעקב ומקשים ו[כי] שייך לומר שחו\"ג אינו אמת ח\"ו</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380656\" data-slug=\"likkutei-torah\" data-id=\"4001380656\">לקו\"ת מטות פג, סע\"ג</a>-ד. וראה גם דרמ\"צ קפ, סע\"א ואילך."]]],[2002180270,"להשפיע לו והת\"ת נותן מקום לשניהם<sup data-n=\"787\">12</sup> לזה ולזה, לו יהא שע\"פ הדין א\"צ ליתן לו צריכים לרחם עליו, וע\"ז גם מה\"ד מודה שאומר שרק ע\"פ הדין א\"צ ליתן לו אבל מצד הרחמים זה הוא מודה, ונמצא שאין לו מנגדים. ופעמים מקשים באו\"א והלא כתי' ונתתם לי אות אמת דא אות ו' מדתו של יעקב, ומה צריכים ליתן לו אמת<sup data-n=\"788\">13</sup>, והתירוץ שהוא אמת וניתוסף לו אמת לאמיתו. היוצא מזה שיש כמה מדריגות באמת, וזהו ששם אלקים ג\"כ אמת, וזהו אל דעות הוי', שבחי' שם אל מחבר הדעות ששניהם אמת, והם יחו\"ע ויחו\"ת, דשם הוי' הוא יחו\"ע ושם אלקים יחו\"ת ושניהם כחות אלקות, אלא דשם אלקים הוא כח אלקי שמסתיר ומעלים על אור הוי' שיהי' ממנו מציאות התהוות היש בכדי שהיש יהי' בטל להאין ה\"ז ג\"כ אמת.\n<b>והנה</b> להבין זה, הנה בטבע יש מחלוקת בין החוקרים<sup data-n=\"789\">14</sup>, בתשו' ח\"צ כ' שטבע היא תיבה מחודשת<sup data-n=\"790\">15</sup> זה ערך ג' מאות שנה, דבאמת אינו שייך כלל לומר שהוא טבע, כמו צמיחת הצומח אינו שייך לומר שהוא טבע, שהרי כדי שיהי' צמיחה צ\"ל גשם וצריך להתקשר שמים עבים וכתי' המכסה שמים עבים המכין לארץ מטר המצמיח הרים חציר, ואינו שייך כלל לומר שהוא טבע, הרי אומר שטבע הוא ניסים תכופים<sup data-n=\"791\">16</sup> שהוא מחודש. ושארי חכמי המחקר אומרים שברה\"ע הוא בריאה יש מאין וטבע הוא כמ\"ש במשנה ולהגיד גדולתו של הקב\"ה שאדם טובע כמה מטבעות בחותם אחד וכולם דומין זה לזה אבל הקב\"ה טבע את כל אדם בחותמו של אדה\"ר ואין א' דומה לחבירו, הרי תי' טבע הוא ל' טבעת וקאי על ההנהגה.\n<b>ועפ\"ז</b> יובן המדרש ע\"פ ויכל אלקים<sup data-n=\"792\">17</sup> ביום השביעי, ולכאו' צ\"ל והלא כתי' ששת ימים עשה כו' ומהו אומרו ביום השביעי, ובאמת שינו לתלמי המלך וכ' ביום השישי כדי שלא יקשה, אבל באמת צריכים להבין זה. ואי' במדרש משל למלך שעשה לו טבעת מה הי' חסירה חותם, כך מה הי' העולם חסר חותם בא שבת בא חותם. דהנה טבעת הוא בריאה יש מאין, והחותם הוא מ\"ש ביום עשות הוי' אלקים",[["787","12","<b>מדת הת\"ת הוא מדת הרחמים . . נותן מקום לשניהם</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370045\" data-slug=\"torah-or\" data-id=\"3901370045\">תו\"א נח יא, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380174\" data-slug=\"likkutei-torah\" data-id=\"4001380174\">לקו\"ת תזריע כג, ג</a>. מאמרי אדה\"ז תקס\"ה ח\"א ע' שעא-ב. וע' שעה ואילך. ביאוה\"ז להצ\"צ ח\"א ס\"ע שיג ואילך. סה\"מ תרכ\"ז ע' תקא.. וש\"נ."],["788","13","<b>ופעמים מקשים באו\"א . . אמת . . מדתו של יעקב ומה צריכים ליתן לו אמת</b>: ראה אגה\"ק סי' ו (קט, ב ואילך). וראה גם סה\"מ תרל\"ד ע' רסא. וע' שס. ועוד."],["789","14","<b>והנה להבין זה הנה בטבע יש מחלוקת בין החוקרים</b>: בהבא לקמן ראה אוה\"ת נ\"ך (כרך ב) שם ע' תתקעז. שה\"ש (כרך א) ס\"ע שיד-טו. יהל אור לתהלים ע' קנד. סה\"מ תשי\"א [לכ\"ק אדמו\"ר מהוריי\"צ] ע' 290 ואילך. [ובהנסמן בהע' שלאח\"ז]."],["790","15","<b>בתשו' ח\"צ כ' שטבע היא תיבה מחודשת</b>: הובא גם ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380806\" data-slug=\"likkutei-torah\" data-id=\"4001380806\">לקו\"ת פ' ראה כב, ג</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010008\" data-slug=\"or-hatorah-hb\" data-id=\"8159010008\">אוה\"ת בראשית (כרך ז) תתשסא, א</a>. נ\"ך (כרך ב) שם ע' תתקעז. א'קיא. אוה\"ת שה\"ש שם ס\"ע שיד. סה\"מ תרע\"ח שם ס\"ע פח ואילך. תרח\"צ שם ע' קסז ואילך. סה\"מ מלוקט ח\"ה ע' קח ואילך."],["791","16","<b>שטבע הוא ניסים תכופים</b>: ראה סה\"מ מלוקט ח\"א ע' תעה. וש\"נ."],["792","17","<b>ועפ\"ז יובן המדרש ע\"פ ויכל אלקים</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560089\" data-slug=\"or-hatorah-hb\" data-id=\"8316560089\">אוה\"ת בראשית (כרך ג) תקיא, א</a>. שם (כרך ז) תתשס, ב ואילך. תשא ע' א'תתקנו-ז. סה\"מ תרל\"ה ח\"ב ע' רצ. עטר\"ת ע' תד ואילך. הש\"ת ע' 80 ואילך."]]],[2002180271,"וכמ\"ש שבת להוי'. והענין דהנה כתי' השמים מספרים<sup data-n=\"793\">18</sup> כבוד אל ופי' בסידור הזהר השמים הוא שמים עילאין מספרים מנהרין ומנצצין לכבוד אל דנהיר לכל עזקא ועזקא, עיזקא הוא טבעת והחותם מאיר להטבעת, והו\"ע עיגולים ויושר כמו רב שמסביר שכל לתלמיד<sup data-n=\"794\">19</sup> הנה כשעדיין התלמיד אינו מבין השכל הוא בבחי' עיגולים שהוא מקיף את שכל התלמיד, וכשהוא מבין את השכל הוא יושר והוא מקיף אותו<sup data-n=\"795\">20</sup>, וזהו עיגולים הוא עולמות והיכלות, דעולם הוא ל' העלם והחותם הוא שיאיר מהעלם לגילוי. והענין דהנה לכאו' צ\"ל איך שייך לומר שהבריאה הוא משם אלקים והלא כתי' בדבר הוי' שמים נעשו, יהללו את שם הוי' כי הוא צוה ונבראו, כל אשר חפץ הוי' עשה, ואיך אנו אומרים שהוא מצד שם אלקים, ובאמת הלא כתי' בראשית ברא אלקים. והענין דהחילוק הוא בין ברא ובין ונבראו<sup data-n=\"796\">21</sup>, דברא הוא כח הפועל בנפעל וזה שייך בשם אלקים, מה הנשמה ממלאה את הגוף כמו\"כ הקב\"ה ממלא את כל העולם, דכמו בגוף יש התחלקות ראש גוף ורגל דבראש יש חיות יותר ובידים יותר מברגלים כמו\"כ למעלה יש התחלקות בראתיו יצרתיו אף עשיתיו דבבריאה גילוי אלקות יותר מיצי' וביצי' יותר מעשי' דבכל עולם לפי ערכו, אבל בשם הוי' אינו שייך לומר מה הנשמה כו' דהלא כתי' אני הוי' לא שניתי שלא יש שום שינוי, דאפי' הארה המהווה הוא ג\"כ אינו מלובש והוא סוכ\"ע, והעיקר המהווה הוא בחי' סוכ\"ע רק שהוא בהעלם, דפי' סובב אינו שסובב ומקיף<sup data-n=\"797\">22</sup> מכל צד (בל\"א רונד „ רום) שהרי כתי' את השמים ואת הארץ אני מלא הרי שהוא מלא בתוכו אלא שהוא בהעלם. וזהו ויכל אלקים ביום השביעי שמאיר מהעלם לגילוי, ואין זה מלאכה, וכמו התלמיד שתחלה אינו מבין השכל ואח\"כ מבין אותו וה\"ה מקיף את השכל ההוא, כמו\"כ כאן העולם הוא העלם והחותם הוא שיהי' מאיר בהטבעת. וזהו וארא אל אברהם אל יצחק באל שדי ושמי הוי' כו', ופירש\"י לא נכרתי במדת אמיתיות שלי, ו[כי] שייך לומר ששם שדי ושם אל בחסד כו' אינו אמת חלילה, אלא שהם אמת, ושם הוי' הוא אמת לאמיתו.\n<b>ועתה</b> יובן ענין הנס דהנה נס הוא התרוממות וכמו ושים אותו על נס<sup data-n=\"798\">23</sup>, שהוא מבחי' שלמעלה מסדר השתל', הגם שהוא מלובש בטבע מ\"מ הוא למעלה",[["793","18","<b>ופי' בסידור הזהר השמים . . מספרים</b>: ר\"ל שבסידור מפרש את הזהר. וראה הלשון לקמן בהנחות השומעים: בסידור בשם הזהר. וראה סידור עם דא\"ח קעח, סע\"ב ואילך. ובארוכה בפירוש המלות לכ\"ק אדהאמ\"צ ה, סע\"ב ואילך."],["794","19","<b>והו\"ע עיגולים ויושר כמו רב שמסביר שכל לתלמיד</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380462\" data-slug=\"likkutei-torah\" data-id=\"4001380462\">לקו\"ת שלח לז, ג</a> [ובהנסמן בהמ\"מ שם]. מאמרי אדה\"ז תקס\"ב ח\"א ע' מו ואילך. אוה\"ת תרומה ע' א'תסו ואילך. א'תסט ואילך. סה\"מ תרס\"ה ע' קמט ואילך. ועוד."],["795","20","<b>והוא מקיף אותו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא רפ\"ה</a>: כשמשכיל ומשיג בשכלו איזה מושכל הרי השכל תופס את המושכל ומקיפו בשכלו כו'."],["796","21","<b>והענין דהחילוק הוא בין ברא ובין ונבראו</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381187\" data-slug=\"likkutei-torah\" data-id=\"4001381187\">לקו\"ת שה\"ש יד, ג</a> ואילך. לעיל ח\"א ע' קע. וש\"נ."],["797","22","<b>דפי' סובב אינו שסובב ומקיף</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310053\" data-slug=\"tanya\" data-id=\"3401310053\">תניא פמ\"ח (סז, ב</a>). ובכ\"מ."],["798","23","<b>נס הוא התרוממות וכמו ושים אותו על נס</b>: ראה פיה\"מ לאדהאמ\"צ שם פקל\"ט. אוה\"ת בשלח ע' תרסה. שה\"ש ע' כט. ועוד."]]],[2002180272,"מסדר השתל', וזהו ארבעה צריכים להודות נגד ד' אותיות הוי', דנס הוא מצד שם הוי'.\n<b>ובסידור</b> האריז\"ל כ' שהוא או\"א דיצי'. דהנה חו\"ב זיווגייהו תדיר לצורך קיום העולמות, דהנה חכ' ובינה הוא יש ואין<sup data-n=\"799\">24</sup>, בינה הוא יש וכמ\"ש להנחיל אוהבי יש, וחכ' הוא אין וכמ\"ש והחכ' מאין תמצא, וצ\"ל מהו הראי' שהחכ' הוא ג\"כ אין<sup data-n=\"800\">25</sup>, שאפ\"ל שהחכ' הוא נמצא מאין אבל חכ' בעצם הוא יש. אך הענין הוא דהנה אם הי' כתי' נברא היינו אומרים כן, אבל לאחר דכתי' תמצא צ\"ל שהוא כמו מציאה שזה מוצא מה שזה אבד, וכמו כשראובן מצא מה ששמעון אבד הנה צ\"ל שאותו דבר כמו שהוא שאבד שמעון מצא ראובן, שאל\"כ אינו מחויב להחזיר לו לפי שבאמת אינו שלו, וכמו\"כ כאן כשאומרים והחכ' מאין תמצא פי' שהוא ג\"כ אין, ובינה הוא יש השגה, וכמו שבד\"ת היש אין לו השגה בהאין כמו\"כ כאן בינה שהוא השגה אין לו השגה בהאין, וכמו בד\"ת יחו\"ת היש בטל להאין כמו\"כ צ\"ל כאן שהבינה הוא בטל תמיד להחכ' והחכ' תמיד משפיע בבינה, ויחו\"ע הוא דכל מה שלמעלה הוא יש וההארה<sup data-n=\"801\">26</sup> הוא אין, דהנה באין יש ב' פי' הא' אין שאינו מושג, הב' אין הארה, וזהו שהאין דחכ' שלמעלה מבחי' ששופע לבינה הוא כמו האין דכתר ונק' אין מפני שאינו שייך שם השגה, ובאמת הוא יש אמיתי, וההארה שנמשך משם זהו אין, וזהו יחו\"ע ד\"ע.\n<b>וזהו</b> מזמור לתודה, שבבחי' זו אינו שייך השגה כ\"א הודאה, וכמו מודים חכמים לר\"מ הגם שאינם משיגים מ\"מ מודים שכן, כמו\"כ כאן מודים שכן הוא. וזהו אל דעות הוי' שיש ב' דעות ד\"ע וד\"ת, ובאמת ד\"ת ג\"כ אמת אך העיקר הוא ד\"ע איך שכולא קמי' כלא חשיב.",[["799","24","<b>דהנה חכ' ובינה הוא יש ואין</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380065\" data-slug=\"likkutei-torah\" data-id=\"4001380065\">לקו\"ת פקודי ו, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380221\" data-slug=\"likkutei-torah\" data-id=\"4001380221\">אמור לג, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380399\" data-slug=\"likkutei-torah\" data-id=\"4001380399\">נשא כב, ד</a>. לעיל ח\"א ע' קעב. שכ. ועוד."],["800","25","<b>והחכ' מאין תמצא וצ\"ל מהו הראי' שהחכ' הוא ג\"כ אין</b>: ראה בכ\"ז המשך וככה תרל\"ז פמ\"ז (ס\"ע סט ואילך). סה\"מ תרנ\"ח ס\"ע יז-ח. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380054\" data-slug=\"likkutei-torah\" data-id=\"4001380054\">לקו\"ת פקודי ג, סע\"ג</a>-<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380376\" data-slug=\"likkutei-torah\" data-id=\"4001380376\">ד. במדבר יז, א</a>. ועוד."],["801","26","<b>באין יש ב' פי' . . שאינו מושג . . הארה</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830010\" data-slug=\"or-hatorah-hb\" data-id=\"8158830010\">אוה\"ת מסעי</a> בהוספות (הוצאת תש\"ס) ע' 51. [ובהנסמן שם]. סה\"מ תרכ\"ז ע' שסו. תרל\"א ח\"א ע' חצר ואילך. [ובהנסמן שם בתחילת המאמר]. לעיל ד\"ה תקעו בחודש פ\"ו."]]],[2002180273,"<h3>עבדו את ה' בשמחה (ל\"ג בעומר)</h3>\n<b>ל\"ג בעומר ט\"ל, לפ\"ק.</b>\n<b>עבדו</b> את ה' בשמחה<sup data-n=\"802\">1</sup> בואו לפניו ברננה דעו כי ה' הוא אלקים, ואי' במגלה עמוקות<sup data-n=\"803\">2</sup> עבדו כו' הו\"ע עבודת הכהנים כהנים בעבודתם ועכשיו בתפלה הוא פ' הקרבנות שעד ב\"ש, ובואו לפניו כו' הו\"ע עבודת הלוים לוים בדוכנם שהו\"ע שירה וזמרה, ובתפלה הוא פסוד\"ז וברכת ק\"ש, דעו כו' הוא ק\"ש ומפרש זה על פסוק ראשון דק\"ש.\n<b>והענין</b> דהנה בק\"ש אנו אומרים שמע ישראל<sup data-n=\"804\">3</sup> ה' אלקינו ה' אחד, וצ\"ל למי אומרים שמע ישראל, והענין שאומרים זה להנשמה דכתי' נשמה שנתת בי טהורה היא אתה בראת אתה יצרת אתה נפחת, וצ\"ל דהול\"ל תחילה בראת יצרת נפחת ואח\"כ יאמר השבח שהיא טהורה<sup data-n=\"805\">4</sup>. והענין דהנה לא כל הנשמה מתלבשת בגוף כ\"א הארה ממנה, ועיקר הנשמה היא למעלה, דכל הנשמה הגוף קטן מהכיל אותה, שהרי מלאך בשליש עולם עומד<sup data-n=\"806\">5</sup> מכ\"ש נשמה שלמעלה מהמלאך אינו שייך שהגוף יכיל אותה אלא שהוא רק הארה ומקצת מהנשמה ועיקר הנשמה למעלה, ועלי' נא' אע\"ג דאיהו לא חזי מזלייהו חזי שהמזל רואה גילוי אלקות, והגם שאמרז\"ל דאין מזל לישראל<sup data-n=\"807\">6</sup> היינו שאין להם מזלות הרקיע אבל אין מזל לישראל שהמזל הוא בחי' אין. ובאמת הרי מח' של ישראל קדמה לכל דבר, ה\"ז כלל שלכל דבר קדמה מח' של ישראל, ובפרט הנה אי' שני דברים קדמו לעולם תורה וישראל אבל איני יודע איזה מהם קדם אומר אני ישראל קדם. דפעמים אי' ישראל מתקשראין באורייתא ואורייתא בקוב\"ה הרי שהתקשרות ישראל באלקות הוא ע\"י אמצעית התורה הרי התורה למעלה מישראל, וכתי' תורה צוה לנו משה מורשה א\"ת מורשה אלא מאורסה שהתורה כלה מאורסה לאיש כנס\"י הרי ישראל חתן<sup data-n=\"808\">7</sup>. והענין דהנה מצד שרש הנשמה ישראל למעלה מתורה, דהגם דאורייתא מחכ' נפקת, מ\"מ הלא כתי' בנים אתם<sup data-n=\"809\">8</sup> לה' אלקיכם כמו שהבן נמשך מעצמיות מוח האב כמו\"כ ישראל הם",[["802","1","<b>עבדו את ה' בשמחה</b>: הוא הנחת כ\"ק אדמו\"ר מהורש\"ב מהמאמר ד\"ה זה שנדפס לעיל ע' שפג ואילך. וראה בהנסמן שם לכללות המאמר."],["803","2","<b>ואי' במגלה עמוקות</b>: הובא גם ביהל אור לתהלים ע' שסט. סה\"מ תרנ\"ח ע' מח."],["804","3","<b>והענין דהנה בק\"ש אנו אומרים שמע ישראל</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381196\" data-slug=\"likkutei-torah\" data-id=\"4001381196\">לקו\"ת שה\"ש טז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381197\" data-slug=\"likkutei-torah\" data-id=\"4001381197\">יז, א</a>. וראה בכ\"ז בארוכה סה\"מ תרכ\"ט ע' קמה ואילך. תרל\"ה ח\"ב ס\"ע תכד ואילך. ועוד."],["805","4","<b>וצ\"ל דהול\"ל תחילה בראת . . ואח\"כ . . השבח שהיא טהורה</b>: ראה גם אוה\"ת מטות ע' א'רנו. סה\"מ תרל\"ג ח\"ב ע' שכז. וע' שעב. תרע\"ח ע' שלז. המשך תער\"ב ח\"ג ע' א'תד ואילך. ועוד."],["806","5","<b>שהרי מלאך בשליש עולם עומד</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381022\" data-slug=\"likkutei-torah\" data-id=\"4001381022\">לקו\"ת האזינו עד, סע\"ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381119\" data-slug=\"likkutei-torah\" data-id=\"4001381119\">ברכה צח, א</a>. סה\"מ תרל\"ג ח\"א ע' כד. וש\"נ."],["807","6","<b>ועלי' נא' אע\"ג דאיהו לא חזי מזלייהו חזי . . דאין מזל לישראל</b>: בהבא לקמן ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381010\" data-slug=\"likkutei-torah\" data-id=\"4001381010\">לקו\"ת האזינו עא, ד</a>. סה\"מ תרל\"ג ח\"א ע' רלט. וש\"נ."],["808","7","<b>דפעמים אי' ישראל מתקשראין באורייתא . . הרי התורה למעלה מישראל וכתי' תורה צוה . . הרי ישראל חתן</b>: בהבא לקמן ראה סה\"מ תרכ\"ט שם ע' קמה ואילך. תרל\"ה ח\"ב שם ע' תכה. תורת שמואל דרושי חתונה ע' סח."],["809","8","<b>בנים אתה לה' אלקיכם כמו שהבן נמשך מעצמיות מוח האב</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא פ\"ב</a>. ובכ\"מ."]]],[2002180274,"מעצמיות החכ' והוא האין דחכ' דכתי' והחכ' מאין תמצא אין דחכ' כמו שנמצא מהאין דכתר, ומצד בחי' זו ישראל ממשיכים בתורה, וזהו טהורה שהוא שרש ומקור הנשמה. אבל הנשמה שמתלבשת בגוף שעוברת ע\"י בחי' בראת יצרת נפחת, לגבי בחי' זו תורה למעלה ממנה, והתקשרותה לאלקות הוא ע\"י התורה. והנה ע\"ז נא' שמע ישראל ה' אלקינו ה' אחד, יחו\"ע.\n<b>וכ\"ז</b> הוא שרש הנשמה, אבל הנשמה המתלבשת בגוף ע\"ז נא' אח\"כ ואהבת את ה' אלקיך בכל לבבך בשני יצריך כמ\"ש במשנה, וצ\"ל והאיך אפשר היצה\"ר לבוא לאהבה לאלקות. והענין דהנה יצר הם מדות, ויש יצ\"ט ויצה\"ר הם מדות טובות ומדות רעות<sup data-n=\"810\">9</sup>, ונת\"ל דלמדות יש מוחין מאין שיולד המדה דהיינו שממנה מתגלה המדה, דכל פרט ופרט מהמדה יש לו שער<sup data-n=\"811\">10</sup> שממנה מתגלה, וכמו\"כ מדות רעות יש להם מוחין ומצדו אפשר לבא לאהבה לאלקות. וזהו ממה שאומרים תחילה בשכמל\"ו, דהנה מלכות הוא מ\"ש מלכותך מל' כל עולמים שהוא רק שם והארה בעלמא וכמ\"ש מלך שמו נק' עליהם כמו השם שהוא רק הארה בעלמא, כמו\"כ מל' הוא רק הארה, וכבוד הוא הארה ממל', ושם כבוד הוא הארה דהארה, ובכלל הם נגד ג' עולמות בי\"ע<sup data-n=\"812\">11</sup>, וכשיתבונן בשכלו שהמקור הוא רק הארה א\"כ אינו שייך לומר שהעולם הוא מציאות היש, וא\"כ יסכים ג\"כ על הביטול. ואח\"כ בכל נפשך בכל כחות הנפש אפי' נוטל כו' כמ\"ש במשנה, דהנה מ\"ש בזהר למסור נפשו באחד היינו להנה\"א ובכל נפשך הוא (הנפש המחי' את) הגוף, [ובכל מאדך] הוא [לא שיומשך שיהי' גילוי המדות אהוי\"ר אלא שיהי' רעותא דליבא רצון לאלקות].\n<b>וזהו</b> שארז\"ל כל המאריך באחד<sup data-n=\"813\">12</sup> שצריכים אריכות ההתבוננות כדי שיבוא לאחד ולועד, דהנה דורות הראשונים היו ממעטים בתפלה<sup data-n=\"814\">13</sup> וכ\"ש בפסוד\"ז מפני שהיו מבחי' מוחין דגדלות והיו תמיד מקושרי' לאלקות, ומאחר שהוא מקושר תמיד א\"צ להתבוננות וכמו רשב\"י בחד קטירא אתקטרנא בי' אחידא בי' להיטא, וכן אמרו (ר\"י הנשיא הי') מעביר ידיו ע\"ג עיניו ויצא בזה, וכן ר\"י הוה מצלי מתלתין יומין לתלתין יומין, שלא הי' צריך הרצוא דתפלה רק מתלתין יומין לתלתין יומין, ושאר הזמן הי' בבחי' שוב דתורה, וזהו מפני שהי' מבחי' מוחין דגדלות. אבל אנו שנתגשמו ונתרחקנו מאלקות נשמות דעקבתא דמשיחא אנו צריכים ריבוי התבוננות עד שנבוא לאחד וועד, וכמו קטן שלומדים עמו הלכה שהוא דבר זר ממנו ואינו יודע בטיב",[["810","9","<b>יצ\"ט ויצה\"ר הם מדות טובות ומדות רעות</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370174\" data-slug=\"torah-or\" data-id=\"3901370174\">תו\"א מקץ לח, ב</a>. יהל אור לתהלים ע' תלח. ועוד."],["811","10","<b>ונת\"ל דלמדות יש מוחין . . דכל פרט . . מהמדה יש לו שער</b>: לעיל ד\"ה מזמור לתודה ע' שסח."],["812","11","<b>מל' . . הארה . . ושם כבוד הוא הארה דהארה . . נגד ג' עולמות בי\"ע</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380244\" data-slug=\"likkutei-torah\" data-id=\"4001380244\">לקו\"ת אמור לט, סע\"ג</a>-ד. ועוד."],["813","12","<b>וזהו שארז\"ל כל המאריך באחד</b>: בהבא לקמן ראה לקו\"ת ואתחנן יב, ב-ג. וראה גם לעיל ח\"א ע' קסו."],["814","13","<b>דהנה דורות הראשונים היו ממעטים בתפלה</b>: ראה (נוסף ללקו\"ת ואתחנן שם) לקו\"ת חוקת סב, א."]]],[2002180275,"העולם ובכלל ההלכה מדברת בטיב העולם צריכים ריבוי הסבר עד שיבין ההלכה שגדול א\"צ כלל לזה, כמו\"כ אנו צריכים ריבוי התבוננות כמו הללו את ה' מן השמים הללוהו במרומים הללוהו כל מלאכיו כו' והוא אריכות הענין כמו שכ\"א בטל לאלקות<sup data-n=\"815\">14</sup>, ואח\"כ ברכת ק\"ש היינו כמו שהמקור ושרש שלו בטל, דנה\"ב שרשו משמרי אופנים ומאחר ששרשו בטל פועל בו הזזה שלא יהי' מונע ומעכב הביטול דנה\"א.\n<b>וזהו\"ע</b> בואו לפניו ברננה שהוא עבודת הלוים, דהנה כתי' ועבד הלוי הוא, הוא הוא עלדאת\"כ, ועבודת הלוים הי' ע\"י שירה וזמרה<sup data-n=\"816\">15</sup> להעלות עלדאת\"ג בעדאת\"כ, היינו שבעלדאת\"ג יהי' הגילוי כמו בעלמא דאתכסייא. דהנה ענין השיר מוציא מהעלם לגילוי, דהנה אחד שמתבונן ומתפעל מזה מ\"מ אין ההתפעלות ניכרת שהוא בקרירות, אבל כשמשורר ניגון הנה הניגון מוציא מהעלם לגילוי שיהי' התפעלות ניכרת, דכל תנועה מוליד חום והוא מוציא ההתפעלות מהעלם לגילוי. וזהו כל בעלי השיר יוצאין בשיר<sup data-n=\"817\">16</sup>, דהנה מלאכים יש להם גופים, הגם דכתי' עושה מלאכיו רוחות משרתיו אש לוהט הרי שהגופים שלהם הם מב' יסודות הדקים<sup data-n=\"818\">17</sup> וכל הגופים הם מד' יסודות מ\"מ הרי יש להם גוף, וכשצריכים לצאת מגופם הוא ע\"י שיר. וכמו\"כ נשמות שיושבים בג\"ע ומשיגים השגות, כל השגה הוא הגבלה וכשצריכים לעלות מהשגה להשגה שלמעלה ממנה הוא ע\"י שיר, ובכלל הוא העמוד המחבר ג\"ע העליון וגעה\"ת, ובאמת יש בגעה\"ת גופא כמה מדרי', וכל העלאה הוא ע\"י שיר וזהו\"ע עבודת הלוים בבחי' שיר וזמרה.\n<b>והנה</b> הלוים היו נושאי המשכן<sup data-n=\"819\">18</sup> וגם הארון והלוחות, שע\"י עבודתם הי' בכוחם לחבר משכן עם משכן [נ\"ל שצ\"ל לוחות] העדות<sup data-n=\"820\">19</sup>. דהנה כתי' והחיות רצו\"ש כמראה הבזק ופירש\"י כמו להב הכבשן עולה למעלה ואח\"כ חוזר כך החיות מגביהים ראשיהם למעלה מהרקיע ונרתעים לאחוריהם מפני פחד השכינה, מגביהין ראשיהם היינו הרצוא, ונרתעים לאחוריהם הוא אם רץ לבך שוב לאחד. וכמו\"כ",[["815","14","<b>ריבוי התבוננות כמו הללו . . מן השמים . . במרומים . . כמו שכ\"א בטל לאלקות</b>: ראה בארוכה לעיל ח\"א ד\"ה הללוי' גו' מן השמים ע' קסה ואילך. רסז ואילך. שטו ואילך."],["816","15","<b>ועבודת הלוים הי' ע\"י שירה וזמרה</b>: בהבא לקמן ראה לעיל ח\"א ע' קנד. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370280\" data-slug=\"torah-or\" data-id=\"3901370280\">תו\"א בשלח סב, ג</a>."],["817","16","<b>וזהו כל בעלי השיר יוצאין בשיר</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381119\" data-slug=\"likkutei-torah\" data-id=\"4001381119\">לקו\"ת ברכה צח, א</a>. לעיל ח\"א שם ע' קנד. וש\"נ."],["818","17","<b>מלאכים יש להם גופים . . מב' יסודות הדקים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370015\" data-slug=\"torah-or\" data-id=\"3901370015\">תו\"א בראשית ד, ב</a>. לקו\"ת ברכה שם. ובהנסמן לעיל ח\"א שם ע' קנד."],["819","18","<b>והנה הלוים היו נושאי המשכן</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380062\" data-slug=\"likkutei-torah\" data-id=\"4001380062\">לקו\"ת פקודי ה, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380072\" data-slug=\"likkutei-torah\" data-id=\"4001380072\">ח, א</a>."],["820","19","<b>לחבר משכן עם משכן </b> [נ\"ל שצ\"ל לוחות]<b> העדות</b>: כ\"ז (גם לשון: נ\"ל כו') הוא בגוכי\"ק כ\"ק אדמו\"ר מהורש\"ב נ\"ע. וראה לעיל ע' שפז: שהלוים נשאו המשכן וגם הארון והלוחות, ונודע כי משכן הוא ו\"ה והארון והלוחות הם י\"ה . . וע\"י הזמרה שלהם הי' ביכולתם לשאת המשכן בחי' ה' תתאה עם בחי' וא\"ו לחברם עם בחי' י\"ה משכן העדות. עכ\"ל. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380058\" data-slug=\"likkutei-torah\" data-id=\"4001380058\">לקו\"ת פקודי שם ד, ג</a> ואילך. ו, א ואילך."]]],[2002180276,"הלוים ע\"י עבודתם חברו משכן שהוא ו\"ה עם הארון והלוחות, שעל הלוחות הי' עשה\"ד וארו\"ן אור נו\"ן והוא חו\"ב והיינו שחברו ו\"ה עם י\"ה.\n<b>וזהובואו</b> לפניו ברננה, דהנה כתי' נר הוי' נשמת אדם, כמו נר שטבעו לעלות למעלה ואח\"כ חוזר כך ישראל תחילה הרצוא ואח\"כ השוב, ועי\"ז דעו כי הוי' הוא אלקים דהנה בפסוק א' דק\"ש כתי' ה' אלקינו שהוא חו\"ב וכאן כתי' הוי' הוא אלקים הוא ג\"כ חו\"ב אך כאן כתי' הוי' הוא אלקים ולא אלקינו, דפ\"ר אמר משה אלקינו מפני שמשה זכה לבינה, אבל אח\"כ אמר אלקיך<sup data-n=\"821\">20</sup> מפני שהוא יחו\"ת. וזהו שאמר כאן הוי' הוא אלקים שנכלל בו יחו\"ע ויחו\"ת והיינו החיבור דיחו\"ע ויחו\"ת.\n<b>אך</b> קודם לזה צ\"ל עבדו את ה' בשמחה שהוא עבודת הכהנים והוא אתעדל\"ע שמעורר אתעדל\"ת, דהנה כתי' ובהעלות אהרן את הנרות שאהרן מעלה הנרות הוא בחי' נר הוי' נשמת אדם וזהו\"ע פ' הקרבנות ומשנה איזהו, היינו מה שמוצאים ענין הקרבנות בתושבע\"פ, והודו שאמרו זה לפני הארון עד והלל להוי', עד שירו בתמיד של שחר<sup data-n=\"822\">21</sup> והשאר בתמיד של בין ערביים, והוא הכנה להיחוד (כמדומה לי שאמר ליחוד י\"ה). וזהו עבדו את ה' בשמחה הוא דוגמת עבודת הכהנים, ובאו* לפניו כדי שיבוא לפנימיות זהו ברננה, דעו כי הוי' הוא אלקים הוא פנימיות חבור יחו\"ע ויחו\"ת, וצ\"ל תחילה עבדו את ה' בשמחה ואח\"כ בואו לפניו ברננה ואז דעו כי הוי' הוא אלקים שהוא חבור יחו\"ע ויחו\"ת.",[["821","20","<b>דפ\"ר </b> [ דפ' ראשונה]<b> אמר משה אלקינו . . אבל אח\"כ אמר אלקיך</b>: ראה בכ\"ז אוה\"ת ואתחנן ע' רכ."],["822","21","<b>עד שירו בתמיד של שחר</b>: ראה מדרש (יל\"ש שמו\"ב רמז קמב, מל\"א רמז קפח, והובא באוה\"ת סידור ע' כב) שבתמיד של שחר היו אומרים מהודו לה' עד ובנביאי אל תרעו. ובתמיד של בין הערביים היו אומרים מן שירו לה' עד ויאמרו כל העם אמן והלל לה'. והובא כ\"ז גם בסה\"מ תרכ\"ז ע' מא (ומציין שם גם לטור וב\"י ע\"ש)."]]],[2002180277,"<h3>מזמור לתודה (ש\"פ בהר בחוקותי)</h3>\n<b>ש\"פ בהב\"ח ט\"ל, לפ\"ק.</b>\n\n*)ובאו לפניו כדי שיבוא לפנימיות: בשולי הגליון נרשם בגוכי\"ק: להסיר חיצוניות הלב שיתגלה פנימיות הלב."],[2002180278,"מזמור לתודה<sup data-n=\"823\">1</sup> 'הריעו 'לה' 'כל 'הארץ ר\"ת הלכה, וצ\"ל מה שייך הלכה לתודה. והענין דהנה אמרז\"ל לא ניתנו ד\"ת למשה חתוכין<sup data-n=\"824\">2</sup> אלא מ\"ט פנים טמא ומ\"ט פנים טהור, שנאמר מזוקק שבעתיים זפ\"ז מ\"ט. והנה המ\"ט פנים כו' אינם על הדברים הכתובים בתורה בפי' לאיסור כמו חזיר שכתי' בתורה שהוא אסור ע\"ז א\"צ מ\"ט פנים, וכמו\"כ על שארי דברים האסורים הכתובים בתורה בפי', אלא קאי על מחלוקת. דהנה בנוגה יש שאפשר להעלות לקדושה ויש שא\"א להעלות, ובזה חולקים יש שאוסרין היינו שאומרים שא\"א להעלות אותו, והמתירין אומרים שאפשר להעלות אותו דבר, וע\"ז הם המ\"ט דברים.\n<b>והנה</b> הלכה כדברי המכריע<sup data-n=\"825\">3</sup> שנותן מקום לשניהם, והוא בחי' ת\"ת מדתו של יעקב, דהנה שרשו למעלה משניהם, וזהו\"ע והנורא בוא\"ו, דהנה הגדול הגבור בלא וא\"ו והנורא בוא\"ו שמקבל מאל עליון<sup data-n=\"826\">4</sup> שלמעלה מסדר השתל', דהנה ו' בראשו יו\"ד וקוש\"י, דהנה יש בחי' אין דכתר ויש מ\"ש והחכ' מאין תמצא שהוא האין דחכ' כמו שנמצא מכתר, ולכן יכול להכריע. ועוי\"ל כמשארז\"ל המשל ופחד עמו עושה שלום במרומיו מיכאל שר של מים וגבריאל שר של אש ואינם מכבים זה את זה והוא מפני שמאיר עליהם ממדרי' שלמעלה משניהם, וכמו\"כ כאן מפני הארת הכתר שבת\"ת לכן אפשר להכריע.\n<b>והנה</b> גבי דוד כתי' וה' עמו הלכה כמותו בכ\"מ, ומהו\"ע וה' בתוס' ו', דהנה הלכה הוא מבחי' הקו שנמשך בכתר וחכ', ולכן דוד כיוון אל ההלכה, דהנה הכלי לבחי' זו הוא שפלות ודוד אמר ע\"ע עני ואביון אני, וכתי' והייתי שפל בעיניי, לכן הוא הי' הכלי לבחי' זו וכיוון אל ההלכה. וזהו מ\"ש מרום וקדוש אשכון את דכא ושפל רוח, מרום וקדוש אפ\"ל שהוא הקו שמאיר בכתר וחכ' שעיקר הקו מאיר בחכ' וע\"י נמשך בכל האצי'. וזהו שאמרז\"ל אלו ואלו דברי אלקים חיים והלכה כב\"ה, ופריך בגמ' מאחר דאלו ואלו דא\"ח ולמה הלכה כב\"ה, ולכאו' הי' צ\"ל ההלכה כב\"ש",[["823","1","<b>מזמור לתודה</b>: הוא הנחת כ\"ק אדמו\"ר מהורש\"ב מהמאמר ד\"ה ”ומעתה יובן ענין הריעו לה' כל הארץ\", שנדפס לעיל ע' שעד ואילך. — מאמר זה הוא המשך למאמר ד\"ה מזמור לתודה (הא') שנדפס לעיל."],["824","2","<b>והענין דהנה אמרז\"ל לא ניתנו ד\"ת למשה חתוכין</b>: בהבא לקמן ראה מאמרי אדה\"ז הקצרים ע' שכז. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460078\" data-slug=\"or-hatorah-hb\" data-id=\"8316460078\">אוה\"ת</a> בראשית לב, א. יתרו ע' תתצג ואילך. משפטים ס\"ע א'קח-ט. סה\"מ תרכ\"ז ע' שא ואילך. שיד ואילך. המשך תרס\"ו ע' תכב ואילך. סה\"מ עת\"ר ס\"ע קיז ואילך. עטר\"ת ע' תמט ואילך. תרפ\"ח ע' קכט ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151245\" data-slug=\"likkutei-sichot\" data-id=\"1300151245\">לקו\"ש חט\"ו ע' 233</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211110\" data-slug=\"likkutei-sichot\" data-id=\"1300211110\">חכ\"א ע' 110</a> ואילך."],["825","3","<b>והנה הלכה כדברי המכריע</b>: בהבא לקמן ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211111\" data-slug=\"likkutei-sichot\" data-id=\"1300211111\">לקו\"ש חכ\"א ע' 111</a> ואילך. ובמקומות שנסמנו בהערה הקודמת."],["826","4","<b>והנורא בוא\"ו שמקבל מאל עליון</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370045\" data-slug=\"torah-or\" data-id=\"3901370045\">תו\"א נח יא, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370278\" data-slug=\"torah-or\" data-id=\"3901370278\">בשלח סב, א</a>. לקו\"ת ואתחנן ח, סע\"א. וראה גם מאמרי אדה\"ז ענינים ע' נח. [ובהנסמן בהמ\"מ לשם]."]]],[2002180279,"שהיו מחדדי טפי, ותירוץ מפני שהם נוחין ועלובין פי' סבלנים, מפני שהיו סבלנים לכן כיוונו אל ההלכה.\n<b>והנה</b> צ\"ל ההפרש בין מ\"ש אלו ואלו דא\"ח להלכה כמותו, דלכאורה כשאומרים שההלכה כמותו ה\"ה האמת וא\"כ הדיעה [הב'] אינו אמת ח\"ו, וזה אינו שייך לומר שהרי אלו ואלו דא\"ח. והענין דהנה הלכה הוא הארת הפנים כמ\"ש יאר ה' פניו אליך והו\"ע תיקון ואמת שהוא פנוי משערות<sup data-n=\"827\">5</sup> וע\"ז נא' חכמת אדם תאיר פניו וכמו כשא' ממציא איזה שכל ניכר העונג בפנים, וכמו ר\"א מצא תוס' חדתא צהבו פניו, שגילוי העונג הוא בפנים שפנוי משערות, ואינו שייך לומר חלילה ששארי תיקונים אינם אמת חלילה, אלא ששאר תיקונים ג\"כ אמת אלא שהוא כמו שנמשך ע\"י צמצום דשערות, ותיקון ואמת הוא פנוי משערות. וכמו\"כ יובן כאן דהנה הסברא של החולק שלא כהלכה ג\"כ אמת<sup data-n=\"828\">6</sup>, ויש לה שער שממנה נמשכה, דהנה חמשים שערי בינה נבראו בעולם והמ\"ט הם שערים<sup data-n=\"829\">7</sup> שמהם נמשך לידת והתגלות המדה, וכל סברה מאיזה מדה שהיא יש לה שער שממנו נולדה, וכמו\"כ בי\"ג מדות שהתורה נדרשת שהם נגד יגת\"ד יש להם מקום שם ג\"כ, אלא שהם משארי תיקונים שנמשכים ע\"י צמצום דשערות, וזהו אלו ואלו דא\"ח, אלא שבגמ' אמר הל' אלקים חיים שהוא בבינה מפני שמדבר בהמ\"ט שערים, אבל באמת נמשכים מהתיקונים, ומ\"ש הלכה כמותו זה נמשך מתיקון ואמת שהוא פנוי משערות. ולכן הוא כמו תודה, שהודאה הוא ענין ד\"ע איך שכולא קמי' כ\"ח, וכמו\"כ הלכה הוא מבחי' תיקון ואמת שפנוי משערות.\n<b>ועפ\"ז</b> יובן מ\"ש הלכות אינם בטילות לע\"ל, אפ\"ל אפי' אותן ההלכות שלא כהלכה ג\"כ אינם בטילות מפני ששרשן מיגת\"ד מו\"ס. והענין דהנה כתי' ואמר ביום ההוא הנה אלקינו זה, הוא הוא עלמין סתימין דלא אתגליין וזה הוא עלמא דאתגלייא, ולע\"ל יהי' הוא בבחי' זה, ולכן הלכות אינם בטילות לע\"ל, דבחי' זו סתים גם מבחי' הוא, והוא בחי' סדכ\"ס<sup data-n=\"830\">8</sup> ולכן אינם בטילות לע\"ל. ואינו דומה לנבואה שיהי' בטל לע\"ל, אין לומר שיבטלו ח\"ו אלא שלא יחשב, דהנה נבואה הוא נו\"ה ולגבי הגילוי דלע\"ל לא יחשב, וע\"ד שרגא בטיהרא דעכשיו הוא גילוי ולע\"ל לא יחשב זה לגילוי. אבל הלכות שהם סדכ\"ס אינם בטלים לע\"ל.\n<b>עוד</b> יש ד\"א שתודה והלכות שוין, דהנה אמרז\"ל כל המנחות באות מצה חוץ מתודה ושתי הלחם, והנה בכלל מנחות נכלל כל הקרבנות, הגם דמנחות הוא",[["827","5","<b>והו\"ע תיקון ואמת שהוא פנוי משערות</b>: ראה בכ\"ז בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380696\" data-slug=\"likkutei-torah\" data-id=\"4001380696\">לקו\"ת מסעי צג, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380707\" data-slug=\"likkutei-torah\" data-id=\"4001380707\">צה, ד</a>. סה\"מ מלוקט ח\"א ע' צא ואילך. ועוד."],["828","6","<b>הסברא של החולק שלא כהלכה ג\"כ אמת</b>: ראה עד\"ז בארוכה בלקוטי לוי יצחק אגרות קודש ע' רסג ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041025\" data-slug=\"likkutei-sichot\" data-id=\"1300041025\">לקו\"ש ח\"ד ע' 25</a> (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301410107\" data-slug=\"likkutei-sichot\" data-id=\"1301410107\">הע' 43</a>). ח\"ל ע' 12. חל\"ג ע' 118 (ובהע' 38). ועוד."],["829","7","<b>חמשים שערי בינה נבראו בעולם והמ\"ט הם שערים</b>: ראה בכ\"ז בארוכה לעיל ד\"ה מזמור לתודה (הא')."],["830","8","<b>הלכות אינם בטילות לע\"ל . . והוא בחי' סדכ\"ס</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370409\" data-slug=\"torah-or\" data-id=\"3901370409\">תו\"א מג\"א צ, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370414\" data-slug=\"torah-or\" data-id=\"3901370414\">צב, א</a>. ובכ\"מ."]]],[2002180280,"מנחת מחבת ומרחשת, זה פרט קרבן מנחה, אבל בכלל כל הקרבנות נק' מנחה<sup data-n=\"831\">9</sup>, דמנחה הוא העלאת מ\"ן וזה מרומז במנחה שהוא מ\"ן והוא העלאת מ\"ן ח' הוא מזל השמיני ונוצר ה'<sup data-n=\"832\">10</sup> שיומשך בבחי' בהבראם בה' בראם היינו בחי' מל'. וזהו\"ע הקרבת המנחה שהקריב יעקב אל עשו אחיו עזים מאתים תישים עשרים כו', לא כמו הקרבנות שלנו<sup data-n=\"833\">11</sup>, דיעקב בירר חלקו בעולם התהו ולכן הקריב המנחה לתהו כמו שידע הוא, ואנחנו לא נדע איך הוא הקרבן, שתורה שלנו הוא מעולם התיקון וגילוי עולם התהו יהי' לע\"ל, אבל יעקב שכבר בירר חלקו לכן הקריב הקרבן לתוהו. וזהו כללות הקרבנות אבל פרט קרבן מנחה באות מצה חוץ מתודה כו'.\n<b>דהנה</b> ההפרש בין חמץ למצה<sup data-n=\"834\">12</sup>, דהנה אותיותיהם שוים אלא שמצה הוא בה' וחמץ בח', דהנה ה' הפתח קטן שבין הגג להקו האמצעי<sup data-n=\"835\">13</sup> הוא מורה על מ\"ש פיה פתחה בחכ' הוא בחי' שפלות, וחמץ הוא הגבהה והתנשאות, והקו השמאלי הוא בחי' נה\"י, ומבחי' [זו] אפשר לימשך גם ליצה\"ר דהנה נצח שמואל תיקן מדת הנצח, דהנה כתי' ויגע בכף יריכו, ושמואל שא' וגם נצח ישראל לא ישקר ולא ינחם כי לא אדם הוא להנחם תיקן מדת הנצח, אבל מהוד<sup data-n=\"836\">14</sup> אפשר להימשך גם ליצה\"ר, שהוא חמץ כמ\"ש מכף מעול וחומץ, והפתח שלמטה שבח' הוא לפתח חטאת רובץ וכמארז\"ל שא' רבי קרא מסייע כו'<sup data-n=\"837\">15</sup>. ולכן כל המנחות באות מצה, שחמץ שהוא יצה\"ר א\"א להקריב על המזבח, חוץ מתודה ושתי הלחם שבאות חמץ, דתודה הי' עשר חלות של חמץ ושתי הלחם ג\"כ חמץ, וגם זה נאכל לכהנים אבל לא למזבח.\n<b>וע\"ד</b> דוגמא כמו נדרים עכשיו צ\"ל בלא נדר<sup data-n=\"838\">16</sup>, אך ענין הנדרים הוא כשמשער שאין ביכולתו לברר<sup data-n=\"839\">17</sup> דבר זה ומתירא שמא יוריד אותו הוא נודר ממאכל ההוא,",[["831","9","<b>כל הקרבנות נק' מנחה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370119\" data-slug=\"torah-or\" data-id=\"3901370119\">תו\"א וישלח כה, רע\"ג</a>. סה\"מ תרכ\"ז ע' מט."],["832","10","<b>מרומז במנחה . . העלאת מ\"ן ח' . . ה'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370120\" data-slug=\"torah-or\" data-id=\"3901370120\">תו\"א וישלח שם כה, ד</a>. סה\"מ תרכ\"ז שם ע' נב. ועוד."],["833","11","<b>המנחה שהקריב יעקב אל עשו . . לא כמו הקרבנות שלנו</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370116\" data-slug=\"torah-or\" data-id=\"3901370116\">תו\"א וישלח כד, סע\"ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370121\" data-slug=\"torah-or\" data-id=\"3901370121\">כו, א</a>. סה\"מ תרכ\"ז שם ס\"ע נד-ה."],["834","12","<b>דהנה ההפרש בין חמץ למצה</b>: בהבא לקמן ראה בארוכה סידור עם דא\"ח מה, א ואילך. סה\"מ תרל\"ג ח\"א ע' קנו-ז."],["835","13","<b>ה' הפתח קטן שבין הגג להקו האמצעי</b>: כ\"ה בגוכי\"ק. וראה הלשון לעיל ע' שעו: שהה\"א יש לו פתח קטן בין גגו ובין רגל השמאלי."],["836","14","<b>נצח שמואל תיקן . . וגם נצח ישראל לא ישקר . . אבל מהוד</b>: ראה בכ\"ז בארוכה מאמרי אדה\"ז תקס\"ה ח\"א ע' תיט ואילך. דרך מצותיך יב, א ואילך. ד\"ה זכור גו' עמלק בסה\"מ תרל\"א ח\"א. וש\"נ."],["837","15","<b>וכמארז\"ל שא' רבי קרא מסייע כו'</b>: ראה סנהדרין צא, ב: אמר ליה אנטונינוס לרבי מאימתי יצה\"ר שולט באדם משעת יצירה או משעת יציאה (כשיוצא ממעי אמו, רש\"י), א\"ל (רבי) משעת יצירה, אמר לו (אנטונינוס) א\"כ בועט במעי אמו ויוצא, אלא משעת יציאה, אמר רבי דבר זה למדני אנטונינוס (מדבריו למדתי, רש\"י) ומקרא מסייעו שנאמר לפתח חטאת רובץ."],["838","16","<b>נדרים עכשיו צ\"ל בלא נדר</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380651\" data-slug=\"likkutei-torah\" data-id=\"4001380651\">לקו\"ת מטות פב, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380656\" data-slug=\"likkutei-torah\" data-id=\"4001380656\">פג, רע\"ג</a>. לעיל ד\"ה וידבר גו' המטות."],["839","17","<b>ענין הנדרים הוא כשמשער שאין ביכולתו לברר</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380651\" data-slug=\"likkutei-torah\" data-id=\"4001380651\">לקו\"ת מטות שם פב, ב</a>. פג, סע\"ב. סה\"מ תר\"ל ע' רטז ואילך. וע' רכג ואילך. לעיל ד\"ה וידבר גו' המטות."]]],[2002180281,"היינו שמדחה אותו, וחכם שמתיר הנדר היינו מה שהוא אינו יכול להעלות החכם מעלה אותו. ובכלל הוא ההפרש בין אתכפיא לאתהפכא, דהנודר היינו בחי' אתכפייא והחכם שמתיר הנדר<sup data-n=\"1046\">18</sup> הוא בחי' אתהפכא חשוכא לנהורא. וע\"ד דוגמא כמו שאמרז\"ל ע\"ה אסור לאכול בשר<sup data-n=\"840\">19</sup>, והיינו ע\"ה שלהם שהיו בורים ומפני התאוה דבשר ועצם הבשר יגשם אותו יותר, ות\"ח אמרז\"ל עד דלא אכילנא בשרא דתורא<sup data-n=\"841\">20</sup> לא צלינא דעתאי, שהוא גורם צלילות הדעת, דב\"ח<sup data-n=\"842\">21</sup> שרשו למעלה מאדם לכן עי\"ז נעשה הדעת צלול. וע\"ד דוגמא כמו שאמרז\"ל הקנאה התאוה והכבוד מוציאין את האדם מן העולם הרי שהכבוד מוציא האדם מהעולם, וגבי אהרן כתי' ועשית בגדי קדש לאהרן אחיך לכבוד ולתפארת<sup data-n=\"843\">22</sup>, דוקא כבוד, דאהרן הוא אותיות נראה [והוא בחי' יראה] והי' בבחי' מ\"ה וכמ\"ש ונחנו מה, שגם אהרן בכלל, וכתי' ואהרן מה הוא כי תלינו עליו, וכתי' כבוד חכמים ינחלו, דבחכ' אתברירו דמצד החכ' אפשר לברר גם כבוד ג\"כ. וכמו\"כ תודה שהוא ההודאה לבחי' חכ' לכן באות חמץ. וכמו\"כ שתי הלחם שהוא תורה שבכתב ותושבע\"פ דאורייתא מחכ' נפקת ואמרז\"ל אם פגע בך מנוול זה משכהו לבהמ\"ד שע\"י התורה אפשר לברר היצה\"ר ג\"כ. ודוקא לכהנים שהו\"ע קו הימין חח\"ן, כה\"ג חסד, סגן גבורה, כהן הדיוט נצח<sup data-n=\"844\">23</sup>, ובכח החכ' לברר חמץ ג\"כ.\n<b>ועוי\"ל</b> דהנה כתי' אם האכל יאכל בשתי אכילות הכתוב מדבר אחת אכילת אדם ואחת אכילת מזבח<sup data-n=\"845\">24</sup>, דהנה המזבח הנה בבית ראשון הי' ארי' דאכיל קורבנין וזהו דכתיב אשה ריח ניחוח והו\"ע מ\"ה מברר ב\"ן בבי\"ע, אבל אדם הוא כלול מכל המדריגות וזהו\"ע אכילת כהנים. וזהו שאמרו הל' אכילת אדם והכוונה על כהנים שע\"י אכילתם מעוררים למעלה אכילת אדם. והנה כמו [שתודה] הוא מדריגה גבוה כמו\"כ חנוכה הנה נ\"ח משמאל, דהנה הנס הי' שמצאו פך שמן כו' ומפני שהוא מדרי' גבוה אפשר לברר גם קו השמאל<sup data-n=\"846\">25</sup>.",[["1046","18","<b>והנה זה מובן . . החכם שמתיר הנדר</b>: ראה בכ\"ז אוה\"ת מטות ע' א'שח ואילך."],["840","19","<b>וע\"ד דוגמא כמו שאמרז\"ל ע\"ה </b> [ עם הארץ]<b> אסור לאכול בשר</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380436\" data-slug=\"likkutei-torah\" data-id=\"4001380436\">לקו\"ת בהעלותך לא, ג</a> ואילך. סה\"מ תרל\"ב ח\"ב ע' תיג. וש\"נ. וע' תכ."],["841","20","<b>אמרז\"ל עד דלא אכילנא בשרא דתורא</b>: הובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא פ\"ז (יא, ב</a>)."],["842","21","<b>דב\"ח</b>: דבעל חי."],["843","22","<b>שאמרז\"ל הקנאה התאוה והכבוד . . וגבי אהרן כתי' . . לכבוד ולתפארת</b>: ראה בכ\"ז אוה\"ת תצוה (כרך ח) ע' ב'תשנב-ג. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380194\" data-slug=\"likkutei-torah\" data-id=\"4001380194\">לקו\"ת אחרי כז, ג</a>. אוה\"ת בא ע' רמו."],["844","23","<b>לכהנים שהו\"ע קו הימין חח\"ן, כה\"ג חסד, סגן גבורה, כהן הדיוט נצח</b>: ראה לעיל בהמאמר ע' שעח: הכהנים הם מקו הימין, חח\"ן מימין, שהם כה\"ג חכמה, סגן חסד, כהן הדיוט נצח. — וראה בכ\"ז ביאוה\"ז לאדהאמ\"צ קלג, א. ולהצ\"צ ח\"א ע' קיד. ח\"ב ע' תרפא. תרפח. תרצג. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158670037\" data-slug=\"or-hatorah-hb\" data-id=\"8158670037\">אוה\"ת ויצא קפח, א</a>. וראה המובא ע\"ז באוה\"ת בראשית (כרך ב) תסא, ב."],["845","24","<b>דהנה כתי' ואם האכל יאכל בשתי אכילות . . אכילת אדם . . מזבח</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380105\" data-slug=\"likkutei-torah\" data-id=\"4001380105\">לקו\"ת צו ז, ב</a>."],["846","25","<b>חנוכה הנה נ\"ח משמאל . . לברר גם קו השמאל</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370191\" data-slug=\"torah-or\" data-id=\"3901370191\">תו\"א מקץ מב, סע\"ג</a>-ד. אוה\"ת חנוכה רפג, ב. ואילך. שכו, ב. ובארוכה ס' תורת שמואל דרושי חתונה ע' מב. וס\"ע מה ואילך. וש\"נ."]]],[2002180282,"<b>וזהו</b> ענין מזמור לתודה הריעו לה' כל הארץ עבדו את ה' בשמחה<sup data-n=\"847\">26</sup>, דהנה מזמור לתודה הוא חכ', ועבדו את ה' בשמחה הוא בינה, דשמחה שייך בבינה דוקא, דהנה כתי' וקראת לשבת עונג, הוא בחי' עונג שאינו בגדר שמחה<sup data-n=\"848\">27</sup>, ושמחה הוא כשא' משיג איזה שכל אז הוא שמח (וזהו אין שמחה אלא ביין בינה, ע' בלקו\"ת שה\"ש<sup data-n=\"849\">28</sup> ד\"ה ריח שמניך טובים שמן תורק שמך, וע' בד\"ה שיר השירים הא'<sup data-n=\"850\">29</sup> בענין כי טובים דודיך מיין, ואפ\"ל שהוא בחי' עונג וכמ\"ש באו\"ח עריבות ידידות נעימות מתיקות<sup data-n=\"851\">30</sup> עד שתגעל הנפש את הבשר ממש), וצ\"ל עבודה בשמחה שכ\"א יהי' שמח בחלקו שהרי הוא עובד ה' שלא יהי' במרירות ועצבות כ\"א בשמחה וכמ\"ש תחת אשר לא עבדת את ה' אלקיך בשמחה שצ\"ל עבודה בשמחה. וזהו ההפרש בכלל בין שבת ליו\"ט, דשבת הוא מוחין דאבא ויו\"ט הוא מוחין דאימא<sup data-n=\"852\">31</sup> אז דוקא מועדים לשמחה. באו לפניו ברננה<sup data-n=\"853\">32</sup> הוא השמחה שאחר המרירות, דהנה שמחה הו\"ע תמיד של שחר שמחה בצפרא, ורננה הוא תמיד של בין ערביים דרננה ברמשא, דלילה הוא בירורים והי' מרוחק תחילה ואח\"כ מקריבין אותו ע\"ג המזבח הרי מקרבין אותו ומזה הוא השמחה.\n<b>דעו</b> כי הוי' הוא האלקים<sup data-n=\"854\">33</sup> הוא דעת, דהנה חכ' הוא כשלומד איזה מס' ויודע אותה וכן כששומע הלכה מהרב ומבין ההלכה ה\"ה נק' חכם הגם שהוא שכל שאינו שלו כ\"א של זולתו מ\"מ נק' חכם. ובינה מוסיף על החכ' דהיינו שאומרין לו איזה דבר והוא מבין מזה עוד דבר והיינו להבין דבר מתוך דבר, וזהו דכתי' הבו לכם אנשים חכמים ונבונים וידועים ואח\"כ כתי' ואקח מכם ראשי שבטיכם אנשים חכמים וידועים ואילו נבונים אפי' בימי משה לא אשתכח. ודעת הנה יש בו ג' פי'<sup data-n=\"855\">34</sup>, רש\"י פי' שיודע ליתן טעם על דבריו ונמוקו עמו פי' שממשיך מעומק השכל, ור' יונה פי' ע\"ד במשנה לא במרכבה ביחיד אא\"כ הי' חכם ומבין מדעתו, מפני שמרכבה הוא סוד",[["847","26","<b>וזהו ענין מזמור לתודה . . עבדו את ה' בשמחה</b>: בהבא לקמן ראה סידור עם דא\"ח שם מה, סע\"ג-ד. פירוש המלות לאדהאמ\"צ צח, סע\"א ואילך. אוה\"ת נ\"ך (כרך ב) ע' תתקפו."],["848","27","<b>בשמחה הוא בינה . . עונג שאינו בגדר שמחה</b>: ראה סה\"מ תרל\"ה ח\"ב ע' תכד. ובארוכה סה\"מ תרנ\"ז ע' קעג ואילך. תרס\"ח ע' קסב ואילך. תש\"ט ע' 130 ואילך."],["849","28","<b>ע' ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381140\" data-slug=\"likkutei-torah\" data-id=\"4001381140\">לקו\"ת שה\"ש</a> ד\"ה לריח שמניך</b>: דף ב, ד."],["850","29","<b>וע' בד\"ה שיר השירים הא'</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381137\" data-slug=\"likkutei-torah\" data-id=\"4001381137\">לקו\"ת שה\"ש ב, סע\"א</a>-ב."],["851","30","<b>וכמ\"ש באו\"ח עריבות ידידות נעימות מתיקות</b>: אור החיים עה\"ת ר\"פ אחרי. — הובא במאמרי אדה\"ז אתהלך לאזניא ס\"ע לג. על מארז\"ל ע' תסה. דרך חיים שער התפלה מ, ב. סה\"מ תרכ\"ט ע' רפ. וש\"נ."],["852","31","<b>ההפרש . . בין שבת ליו\"ט . . מוחין דאבא . . מוחין דאימא</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380123\" data-slug=\"likkutei-torah\" data-id=\"4001380123\">לקו\"ת צו יא, ד</a> ואילך. סידור עם דא\"ח ר, ב. רצו, ד ואילך. סה\"מ תר\"ל ע' רסב-ג. תרל\"ב ח\"א ע' סז-ח. וש\"נ."],["853","32","<b>באו לפניו ברננה הוא השמחה שארח המרירות</b>: ראה בארוכה מאמרי אדה\"ז תקס\"ג ח\"א ע' רז ואילך. וע' שצב ואילך. יהל אור לתהלים ע' שעג-ד."],["854","33","<b>דעו כי הוי' הוא האלקים</b>: בהבא לקמן ראה בארוכה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650259\" data-slug=\"or-hatorah-hb\" data-id=\"8316650259\">אוה\"ת נ\"ך (כרך ב) ע' תתקפח</a>-ט."],["855","34","<b>ודעת הנה יש בו ג' פי'</b>: הובאו ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650259\" data-slug=\"or-hatorah-hb\" data-id=\"8316650259\">אוה\"ת נ\"ך שם ע' תתקפח</a>-ט. ובארוכה באוה\"ת משפטים ע' א'קז ואילך."]]],[2002180283,"ופלא לכן אין דורשין אפי' ביחיד אא\"כ מבין מדעתו שאומרים לו ברמיזה והוא מבין והו\"ע די לחכימא ברמיזא, ובמדרש פי' שהוא הנהגות המדות דכל ת\"ח שאין לו דעה נבילה טובה ממנו, ועל משה כתי' כלי יקר שפתי דעת שהגם שהי' מקורב מ\"מ לא הלך אא\"כ קרא אותו. והנה כל הפי' אמת דהנה אל דעות ה' שיש ד\"ע וד\"ת, והנה פי' רש\"י שנימוקו עמו ופי' ר\"י ע\"ד די לחכימא ברמיזא היינו הדעת שלמעלה מחו\"ב ומשם נמשך שיהי' יחוד חו\"ב, ויש דעת שבין הכתפין<sup data-n=\"856\">35</sup> היינו שיומשך ממוחין למדות, ולכן כל ת\"ח שאינו ממשיך ממוחין למדות נבילה טובה ממנו שהעיקר הוא להמשיך ממוחין למדות והו\"ע ד\"ת. וזהו דעו כי כו' הו\"ע ד\"ע וד\"ת. וזהו מזמור לתודה חכ', בואו לפניו ברננה בינה, דעו כי ה' הוא האלקים ד\"ע וד\"ת.",[["856","35","<b>הדעת שלמעלה מחו\"ב . . ויש דעת שבין הכתפין</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370090\" data-slug=\"torah-or\" data-id=\"3901370090\">תו\"א תולדות יט, ב</a>. ועוד."]]],[2002180284,"<h3>מי זאת הנשפקה (ש\"פ במדבר)</h3>\n<b>ש\"פ במדבר ט\"ל, לפ\"ק.</b>\n<b>מי</b> זאת הנשקפה<sup data-n=\"857\">1</sup> כמו שחר יפה כלבנה ברה כחמה איומה כנדגלות, נדגלות הו\"ע עשיית הדגלים וכתי' תחלה שאו את ראש בנ\"י לגולגלותם שצריכים לישא אותם עד בחי' גולגלותם ואח\"כ הוא עשיית הדגלים, כמו\"כ כאן כדי שיהי' איומה כנדגלות צ\"ל תחילה מי זאת הנשקפה כמו שחר יפה כלבנה. והענין דהנה אמרז\"ל במד' ע\"פ כי תבואו אל הארץ וקצרתם את קצירה והבאתם את עומר ראשית קצירכם אל הכהן א\"ר ברכי' אמר הקב\"ה כשנתתי לכם את המן נתתי עומר לכאו\"א הדה\"ד עומר לגולגלותם, וכשאני נוטל איני נוטל אלא עומר א' מכולכם, ולא עוד אלא של שעורים. וצ\"ל מהו\"ע עומר של שעורים.\n<b>וצ\"ל</b> תחילה ענין המן דהנה כתי' ויאמר משה אכלוהו היום<sup data-n=\"858\">2</sup> כי שבת היום היום לא תמצאהו בשדה, וצ\"ל מהו\"ע המן שלא ירד בשבת דהרי כל ההשפעות נשפעים גם בשבת כמו צמיחה הרי בשבת ג\"כ צומח, והמן לא ירד בשבת שנחסר ההשפעה בשבת וצ\"ל למה. ועוד אומרו אכלוהו היום, הלא בכל יום היו אוכלים את המן. והענין דהנה גבי מן כתי' הנני ממטיר לכם לחם מן השמים כו' למען אנסנו הילך בתורתי אם לאו, וצ\"ל מהו הנסיון דמן, ועוד מה שייך מן לתורה, וגם הל' הילך והול\"ל היקיימו.",[["857","1","<b>מי זאת הנשקפה</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב מהמאמר הנדפס לעיל ע' שפט ואילך. לכללות המאמר ראה בהנסמן שם."],["858","2","<b>וצ\"ל תחילה ענין המן . . ויאמר משה אכלוהו היום</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370290\" data-slug=\"torah-or\" data-id=\"3901370290\">תו\"א בשלח סה, סע\"א</a>-ב."]]],[2002180285,"<b>והענין</b> דהנה עיקר קיום העולם הוא ע\"י התורה כמ\"ש אם לא בריתי יומם ולילה חקות שמים וארץ לא שמתי, הרי שו\"א תלוי בברית יומם ולילה, שהוא תורה. וארז\"ל תנאי התנה הקב\"ה במע\"ב אם יקיימו ישראל את תורתי מוטב וא\"ל אחזיר את העולם לתהו ובוהו, עשרה עשרה הכף בשקל הקדש עשה\"ד מכוון נגד עש\"מ, שע\"י עשה\"ד קיים עש\"מ, ובזהר אי' באורייתא אתקיים עלמא, וכן אי' בכמה מקומות בזהר ובמדרש. וארז\"ל אלה תולדות השמים וארץ, אלה בזכות מי נבראו ובזכות מי עומדים בזכות אלה שמות בנ\"י, ואלה בזכות מי נבראו ובזכות מי עומדים בזכות אלה העדות והחוקים והמשפטים, הרי שעיקר קיום העולם הוא ע\"י תורה. וזהו דכתי' אנכי עשיתי ארץ ואדם עלי' בראתי, מה שאנכי עשיתי ארץ הוא בשביל האדם, בראת\"י בגי' תרי\"ג, הרי שעיקר הקיום הוא תורה, וצ\"ל מה שייך תורה לעולם הלא ברה\"ע הי' תחילה ואח\"כ הי' מ\"ת, ומה שייכים זל\"ז.\n<b>והענין</b> דהנה כתי' אתה הוא ה' לבדך<sup data-n=\"859\">3</sup> אתה עשית את השמים ואת הארץ, אתה ה' לבדך כתי' בה' ואתה עשית כו' כתי' את בלא ה'. והענין דהנה אתה הוי' לבדך הוא משארז\"ל עד שלא נברה\"ע הי' הוא ושמו לבד וקאי על עולם האצי', דהנה כתי' כל הנק' בשמי ולכבודי בראתיו יצרתיו אף עשיתיו, הנה בראתי יצרתי כו' הוא לכבודי דכל מה שברא הקב\"ה לא ברא אלא לכבודו, וכל הנק' בשמי<sup data-n=\"860\">4</sup> הוא עולם האצי', וזהו אתה בה' שהם ה' פרצופים שכולם מאירים באצי' והם כח\"ב זו\"ן והם נגד ד' אותיות הוי' וקוש\"י וזהו נק' שמי. אתה עשית כו' דאימא עלאה מקננא בכורסייא שהוא בריאה, אבל כתר וחכ' אינו מאיר שם, ושית ספירן מקננא ביצי' שהם ז\"א מדות שנתמעט מעט מעט עד שאימא תתאה מקננא בעשי', וזהו בהבראם בה' בראם ה' זעירא, דהנה יש ג' מדרי' באותיות אתוון רברבין ואתווין זעירין ואתוון בינונין<sup data-n=\"861\">5</sup>, והנה כללות התורה הוא באתוון בינונין ויש אתוון זעירין היינו שנקטן ונתצמצם האור. והענין דהנה כתי' ואת תדבר אלינו א\"ל משה התשתם את כוחי כנקבה שאמרו לו את ל' נקבה, וכמו\"כ שאומר את עשית הוא ג\"כ בחי' התשתם את כוחי כנקבה.\n<b>והענין</b> דהנה אי' בזהר ע\"פ לסוסתי ברכבי פרעה דמיתיך רעייתי שיש סוסין דוכרין וסוסין נוקבין<sup data-n=\"862\">6</sup>, הנה סוסין הם אותיות וכמ\"ש כי תרכב על סוסיך<sup data-n=\"863\">7</sup>",[["859","3","<b>והענין דהנה כתי' אתה הוא ה' לבדך</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316520283\" data-slug=\"or-hatorah-hb\" data-id=\"8316520283\">אוה\"ת</a> ויחי שפה, ב ואילך. שצה, ב ואילך. בשלח ע' תרכז. תרל\"ב ח\"ב ע' תצ ואילך. תרנ\"ג ע' רנח-ט. תר\"ס ע' מג ואילך. עזר\"ת ע' קיז ואילך. סה\"מ קונטרסים ח\"ב רצו, א. תש\"א ע' 149. סה\"מ מלוקט ח\"ג ע' רכב ואילך."],["860","4","<b>וכל הנקרא בשמי הוא עולם האצי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370010\" data-slug=\"torah-or\" data-id=\"3901370010\">תו\"א בראשית ג, א</a>. מאמרי אדה\"ז תקס\"ז ע' לב. אוה\"ת בראשית (כרך ו) תתרמו, א. ועוד."],["861","5","<b><a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380079\" data-slug=\"likkutei-torah\" data-id=\"4001380079\">יש ג</a>' מדרי' באותיות . . רברבין . . זעירין . . בינונין</b>: ראה לקו\"ת ויקרא א, סע\"ב. ובארוכה מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרסח ואילך. וע' תרעז. ביאוה\"ז להצ\"צ ח\"א ע' קעו ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200012\" data-slug=\"or-hatorah-hb\" data-id=\"8159200012\">אוה\"ת ויקרא (כרך ג) ע' תשכד</a> ואילך. סה\"מ תרע\"ח ע' רלד ואילך. תרצ\"ט ע' 203 ואילך. תש\"ה ע' 130 ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171001\" data-slug=\"likkutei-sichot\" data-id=\"1300171001\">לקו\"ש חי\"ז ע' 1</a> ואילך."],["862","6","<b>והענין דהנה אי' בזהר ע\"פ לסוסתי . . סוסין דוכרין וסוסין נוקבין</b>: ראה בכ\"ז בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370285\" data-slug=\"torah-or\" data-id=\"3901370285\">תו\"א בשלח סג, ד</a> ואילך סד, ג ואילך."],["863","7","<b>סוסין הם אותיות וכמ\"ש כי תרכב על סוסיך</b>: ראה הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370522\" data-slug=\"torah-or\" data-id=\"3901370522\">תו\"א מג\"א קטז, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381174\" data-slug=\"likkutei-torah\" data-id=\"4001381174\">לקו\"ת שה\"ש יא, סע\"ב</a> ואילך. סה\"מ תרכ\"ז ע' רו ואילך. תרל\"ד ע' שנג. שנט. [ובהנסמן בהע' שלפנ\"ז]."]]],[2002180286,"מרכבותיך ישועה שהם אותיות התורה, דכמו הסוס נושא את הרוכב למקום שבעצמו לא הי' יכול לבוא לשם כמו\"כ האותיות ממשיכים בחי' זאת התורה אדם למטה. וזהו\"ע התורה שממשיכים ע\"י מבחי' אתה ה' לבדך לאתה עשית את השמים כו', דה' דאתה ה' כו' הוא ה' חומשי תורה שהם בחי' ה' עילאה בינה ששם שורה אוא\"ס וממשיכים זה למטה. ומ\"ש בכהאריז\"ל דה' הוא ה' פרצופים, יצדק ג\"כ דממשיכים בינה שבו שורה אוא\"ס למטה. וזהו נגילה ונשמחה בך, בך הוא ך\"ב אותיות התורה, ובך הוא עצמות אוא\"ס, והוא שע\"י התורה ממשיכים בחי' זו למטה. וזהו תורת ה' תמימה ויש כאן ג' פסוקים ובכ\"א יש ב' ענינים ובכל ענין יש ה' תיבות<sup data-n=\"864\">8</sup>, והנה ה' תיבות הם ה\"א עילאה וג' פסוקים ובכ\"א ב' ענינים הם וא\"ו והוא שמה\"א נמשך לוא\"ו.\n<b>וזהו\"ע</b> תורה שהיא המשכה, אך קודם לזה צ\"ל העלאה דתפלה וכמ\"ש אם ישים אליו לבו רוחו ונשמתו אליו יאסוף, שתחילה צ\"ל העלאה שהוא אם ישים אליו לבו, ואח\"כ רוחו ונשמתו אליו יאסוף שהוא המשכה.\n<b>ועפי\"ז</b> יובן<sup data-n=\"865\">9</sup> שכשהמלאכים בקשו התורה א\"ל כלום יצה\"ר יש ביניכם<sup data-n=\"866\">10</sup>, וצ\"ל והלא בלא יצה\"ר יותר טוב לקיים תורה, דהנה שאור שבעיסה מעכב אבל בלא יצה\"ר יכול ללמוד תורה. והענין דהנה כד אתכפיי' סט\"א אסתלק יקרי' דקוב\"ה בכולהו עלמין, דיתרון אור מתוך החושך דוקא, ולכן מ\"ת הי' במדבר שהוא מדבר עמים, דיתרון אור מתוך החשך דוקא. דהנה תפלה נמשל לאכילה וכמ\"ש אכלתי יערי עם דבשי, יערי הוא ברכת יוצר ודבשי הוא מתיקות דק\"ש<sup data-n=\"867\">11</sup>, דכמו שאכילה הנה הטוב נעשה ממנו דם ועולה ללב ומוח והפסולת נדחה לחוץ, כמו\"כ בתפלה הנה רוממות אל בגרונם וחרב פיפיות בידם לעשות נקמה בגוים, שע\"י רוממות אל היינו שמתבונן בגדולת ה', עי\"ז נעשה חרב פיפיות לעשות נקמה בהרע של עצמו, וכמ\"ש כמצרף לכסף וכור לזהב<sup data-n=\"868\">12</sup> איש לפי מהללו, לפי ערך ההילול והשבח ככה הבירור שמברר, וכמצרף לכסף וכור לזהב הנה כשרוצה לעשות כלי והוא מעורב בפסולת הנה כתי' הגו סיגים מכסף ויצא<sup data-n=\"869\">13</sup>.\n(ע\"כ נרשם בגוכי\"ק, וחסר סיום)",[["864","8","<b>וזהו תורת ה' תמימה . . ג' פסוקים ובכ\"א יש ב' ענינים . . ה' תיבות</b>: ראה בהנסמן לעיל ע' שצא."],["865","9","<b>ועפ\"ז יובן שכשהמלאכים בקשו התורה</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370291\" data-slug=\"torah-or\" data-id=\"3901370291\">תו\"א בשלח שם סה, ב</a>."],["866","10","<b>א\"ל כלום יצה\"ר יש ביניכם</b>: ראה גם לקמן ד\"ה צאינה וראינה."],["867","11","<b>וכמ\"ש אכלתי יערי עם דבשי . . ברכת יוצר . . מתיקות דק\"ש</b>: ראה סה\"מ תרל\"ג ח\"א ע' קט-י. וש\"נ."],["868","12","<b>וכמ\"ש כמצרף לכסף וכור לזהב</b>: ראה הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370497\" data-slug=\"torah-or\" data-id=\"3901370497\">תו\"א תשא קיא, ג</a>. סה\"מ תר\"ל ע' קיב. תרל\"ב ח\"א ע' צב. ועוד."],["869","13","<b>ויצא</b>: ע\"כ נרשם בגוכי\"ק. וראה המשך המאמר לעיל ע' שצב (באמצע פ\"ב)."]]],[2002180287,"<h3>צאינה וראינה (יום א' דחה\"ש קודם התפילה)</h3>\n<b></b><b>בס\"ד חה\"ש ט\"ל לפ\"ק יום א' קודם התפלה.</b>\n<b>צאינה</b> וראינה<sup data-n=\"870\">1</sup> בנות ציון במלך שלמה בעטרה שעטרה לו אמו ביום חתונתו, ואמרז\"ל מלך שהשלום שלו, הקב\"ה נק' שלמה שהוא מלך שהשלום שלו, ואמו היא כנס\"י, ביום חתונתו מפרש במשנה זו מתן תורה, וזהו שבעת מ\"ת אמו שהיא כנס\"י מעטר עטרה להקב\"ה, וזהו בעטרה שעטרה לו אמו. וצ\"ל והלא אמרז\"ל בשעה שהקדימו ישראל נעשה לנשמע ירדו מה\"ש וקשרו להם שני כתרים א' כנגד נעשה וא' כנגד נשמע, והאיך אומר כאן שאמו מעטר עטרה להקב\"ה, וכאן אומר שקשרו שני כתרים לישראל, ומהו וקשרו לה\"ם שני כתרים.\n<b>והענין</b> דהנה שניהם אמת, שהנה אי' במדרש ע\"פ קדושים תהיו כו' והתקדשתם והייתם קדושים כי קדוש אני משל למלך שעשו לו בני המדינה ג' עטרות מה עשה נטל א' ונתן בראשו ושנים נתן בראש בניו, כך העליונים מכתירים להקב\"ה ג' עטרות, וזהו כתר יתנו לך מלאכים המוני מעלה ועמך ישראל קבוצי מטה (הג\"ה, ונ\"ל כוונתו מ\"ש אח\"כ כולם קדושה לך ישלש\"ו וזהו הג' פעמים קדוש שאומרים וזהו הג' עטרות, עוי\"ל שאומר כתר יתנ\"ו וזהו ראי' שמכתירים לו כו'), נטל א' ונתן בראשו ושנים נתן בראש בניו, וכמ\"ש בנים אתם לה' אלקיכם, בני בכורי ישראל, וזהו הג' עטרות שהעליונים מכתירים לו ע\"י הג' פעמים קדוש, נטל א' ונתן בראשו זהו מ\"ש בעטרה שעטרה ל\"ו אמו, ושנים נתן בראש בניו זהו מ\"ש קשרו לה\"ם שני כתרים. אך צ\"ל שהרי הוא אומר העליוני\"ם מכתירים כו' והעליונים הם מלאכים בכלל וכאן אומר שאמו שהוא כנס\"י מעטר כו'. ובאמת אינו קושיא כלל דהנה אמרז\"ל אין המלאכים אומרים שירה עד שישראל אומרים ק\"ש שנא' ברן יחד כוכבי בקר והדר ויריעו בני אלקים, וזהו כתר יתנו לך מלאכים המוני מעלה ועמך ישראל קבוצי מטה, מה שהמלאכים אומרים שירה זהו ע\"י ועמך ישראל כו', וא\"כ מה שהעליונים מכתירים כו' זהו בכח התחתונים. אך צ\"ל לפ\"ז אומרו ביום חתונתו שרק במ\"ת אמו מעטר עטרה להקב\"ה והלוא בכ\"י אומרים ק\"ש וא\"כ בכ\"י אמו מעטר עטרה להקב\"ה. והענין דהנה אי' במדרש מהיכן זכו ישראל לק\"ש ממ\"ת כשאמר וידבר אלקים אמר שמע ישראל אנכי הוי' אלקיך כו' לא יהי' לך כו' נענו כולם ואמרו הוי' אלקינו הוי' אחד, וזהו הקבלה על שני המאמרים, ובאמת באנכי ולא יהי' לך כלול כל התורה, דאנכי כולל רמ\"ח מ\"ע ולא יהי' לך כולל שס\"ה מל\"ת, וזהו שכללות התורה מפי הגבורה שמענו, וע\"ז אמרו ה' אלקינו הוא קבלת מאמר דאנכי ורמ\"ח מ\"ע כלולים בו, ה' אחד הוא קבלת מאמר לא יהי' לך ושס\"ה מל\"ת<sup data-n=\"871\">2</sup> כלולים בו, ועי\"ז זכו לק\"ש, וא\"כ ק\"ש שייך למ\"ת. ומה שאומרים בכ\"י, הוא שבכ\"י יש מ\"ת,",[["870","1","<b>צאינה וראינה</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב מהמאמר ד\"ה זה שנדפס לעיל ע' תד ואילך. וראה בהנסמן שם לכללות המאמר."],["871","2","<b>ה' אלקינו . . מאמר דאנכי ורמ\"ח מ\"ע . . ה' אחד . . לא יהי' לך ושס\"ה מל\"ת</b>: ראה לעיל ע' תה. וש\"נ."]]],[2002180288,"וזהו שמברכין נותן התורה<sup data-n=\"872\">3</sup>, וצ\"ל בכ\"י קבלת התורה, וזהו שאומרים ק\"ש, וא\"כ בכ\"י יש מה שאמו מעטר עטרה להקב\"ה.\n<b>והנה</b> להבין ענין<sup data-n=\"873\">4</sup> [ביום חתונתו], הנה כתי' והי' הנשאר בציון והנותר בירושלים קדוש יאמר לו ואמרז\"ל עתידים צדיקים שיאמרו לפניהם קדוש כדרך שאומרים לפני הקב\"ה, וצ\"ל איך שייך שיאמרו קדוש לפני הצדיקים כדרך שאומרים לפני הקב\"ה. והנה בס' כלי פז מקשה זה ואומר קשה הדבר להולמו, שקשה לקבל דבר זה איך שייך שיאמרו לפניהם קדוש, וכ' שם שהרמ\"ק בפרדס<sup data-n=\"874\">5</sup> מתרץ זה דהנה צדיקים הם המקיימים תומ\"צ ויתעלו לצדיק וצדק שהם יסוד ומל' דאצי', ומלאכים דבריאה אומרים קדוש ליסוד ומל' וממילא דאומרים קדוש לצדיקים, וזהו ימר שממילא יאמ\"ר להם קדוש, אך הוא דוחק. ורבינו ז\"ל תירץ באו\"א<sup data-n=\"875\">6</sup>.\n<b>והענין</b> דהנה אמרז\"ל על ג' דברים העולם עומד על התורה ועל העבודה ועל גמ\"ח, והם הג' עטרות ג\"פ קדוש. והענין דהנה כתי' לרוקע הארץ<sup data-n=\"876\">7</sup> על המים כי לעולם חסדו. דהנה בתחילת הבריאה היו המים למעלה מהארץ, דהנה בכל דבר הנברא יש ד\"י ארמ\"ע, ובטבע הבריאה הוא שכל דבר שכבד יותר נופל למטה יותר, וידוע דעפר הוא כבד יותר מכל היסודות לכן נפל למטה יותר, והמים שהוא בערך קל יותר מהעפר הוא הקיף את הארץ והארץ הי' מוקף מהמים, והרוח הוא קל יותר לכן הי' על המים וכמ\"ש ורוח אלקים מרחפת על פני המים, והאש שהוא בערך רוחני יותר<sup data-n=\"877\">8</sup> לכן הוא למעלה מכולם, דיסוד האש הוא תחת גלגל הירח, ואח\"כ הי' הגזירה יקוו המים<sup data-n=\"878\">9</sup> אל מקום אחד ותראה היבשה שיהי' היפך טבע הבריאה שהארץ יהי' למעלה מהמים, וזהו שכתיב יורדי הים באניות שנק' יורדים מפני שהארץ הוא למעלה מהמים, וזהו לרוקע הארץ על המים כי לעולם חסדו, מפני חסד ה' שנמשך בעולם, דכדי שיהי' מציאות העולם צ\"ל ארץ.",[["872","3","<b>שבכ\"י יש מ\"ת וזהו שמברכין נותן התורה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370291\" data-slug=\"torah-or\" data-id=\"3901370291\">תו\"א בשלח סה, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380172\" data-slug=\"likkutei-torah\" data-id=\"4001380172\">לקו\"ת תזריע כג, א</a>. מאמרי אדהאמ\"צ שמות ח\"א ע' קעה. וש\"נ. אוה\"ת בשלח ע' תקצז. לעיל ע' שצב."],["873","4","<b>והנה להבין ענין </b> [ביום חתונתו]<b>: התיבות ”</b> [ביום חתונתו]<b>\" שבין חצאי ריבוע נוספו בגוכי\"ק כ\"ק אדמו\"ר מהורש\"ב. ובהמאמר ד\"ה זה הנדפס לעיל ע' תה הלשון הוא</b>: ולהבין ענין ג' עטרות והעטרה שנטל לעצמו."],["874","5","<b>והנה בס' כלי פז . . וכ' שם שהרמ\"ק בפרדס</b>: הובא ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650033\" data-slug=\"or-hatorah-hb\" data-id=\"8316650033\">אוה\"ת</a> ויקרא (כרך ד) ע' א'נח. נ\"ך (כרך ב) ע' תשסב. עיי\"ש."],["875","6","<b>ורבינו ז\"ל תירץ באו\"א</b>: בד\"ה קדושים תהיו בס' מאמרי אדה\"ז תקס\"ב ח\"א ס\"ע קעז-ח. ח\"ב ע' תכב. וראה אוה\"ת נ\"ך (כרך ב) שם ע' תשסא. עיי\"ש."],["876","7","<b>והענין דהנה כתי' לרוקע הארץ</b>: בהבא לקמן ראה אוה\"ת ויקרא שם ע' א'נט ואילך. סה\"מ תרכ\"ט ע' קעט ואילך. עזר\"ת ע' רד ואילך. תש\"ט ע' 185 ואילך. ועוד."],["877","8","<b>והאש שהוא בערך רוחני יותר</b>: ראה לעיל ע' תו בהערה."],["878","9","<b>ואח\"כ הי' הגזירה יקוו המים</b>: ראה אוה\"ת ויקרא (כרך ד) שם ס\"ע א'נט. סה\"מ תש\"ח ע' 205. וש\"נ."]]],[2002180289,"<b>וצ\"ל</b> למה הי' בתחילת הבריאה שהמים יכסה ארץ ואח\"כ יהי' הגזירה יקוו המים אל מקום אחד ותראה היבשה, הי' לו בתחילת הבריאה להיות כך שהארץ יהי' למעלה מהמים, הגם שבטבע הבריאה הוא שכל דבר שהוא כבד יותר נופל למטה יותר, אך הנה הקב\"ה הוא כל יכול ובאפשרי שיהי' הארץ למעלה מהמים כמו שאח\"כ הי' כן, והי' לו בתחילה להיות כן. וצ\"ל על מה זה מרמז. והענין דהנה ים ויבשה הוא עלדאת\"כ ועלדאת\"ג<sup data-n=\"879\">10</sup>, דהנה כל מה שיש בים יש ביבשה חוץ מן החולדה, וההפרש בין ברואים שבים לברואים שביבשה, דהברואים שבים הם מובלעים במי הים, דהנה כל עיקר מהותם הוא מהמים, כמו דגים שעיקר מהותם מהמים לכן יש להם קרירות כמו יסוד המים, וקבלת החיות שלהם ג\"כ מהמים וכשפורשין מהים הם מתים. וכמו\"כ נבראים דעלדאת\"כ כמו מלאכים הנה כ' בי נשבעתי נאום הוי'<sup data-n=\"880\">11</sup>, וצ\"ל איך אומר מלאך ע\"ע בי נשבעתי וכן נאום ה', והענין דהנה מלאך הוא שליח ויש בו כח המשלח, ובפ\"ע הוא אינו מהות כלל שהוא בטל בתכלית, והכלי שלו אינו מסתיר כלל על האור והחיות שלו, ודבר ה' הוא הדובר בו והיינו הכח המשלח, ולכן יכול לאמר ע\"ע בי נשבעתי נאום ה' שהוא הכח המשלח ובפ\"ע אינו מהות כלל, וכן ותקרא שם ה' הדובר אלי' מפני שאינו מהות כלל בפ\"ע והוא בטל בתכלית, הגם שיש לו גוף וכמ\"ש עושה מלאכיו רוחות משרתיו אש לוהט, רק שהוא מב' יסודות, דהנה כל דבר כלול מד' יסודות ארמ\"ע, אך זהו נבראים דעלדאת\"ג, אבל נבראים דעלדאת\"כ הם רק מב' יסודות הדקים, מ\"מ ה\"ה גוף, אלא שהגוף והכלי שלהם אינו מסתיר על האור והחיות שלהם וזהו נבראים דעלדאת\"כ. וזהו כמו משה שכ' מן המים משתיהו שהי' נשמה דעלדאת\"כ וכמו שהי' בעלדאת\"ג הי' ג\"כ בבחי' עלדאת\"כ, וזהו משה משה לא פסיק טעמא בינייהו, ונבראים דעלדאת\"ג הגם שהם מקבלים חיות מהארץ וכמ\"ש ארץ אשר ממנו תצא לחם, וכן כל הדברים צומח חי מדבר כולם מקבלים מהארץ, דצומח תחילה נרקב לגמרי והוא העלאת מ\"ן להכח הצומח שבארץ ואח\"כ הוא צומח מהכח הצומח שבארץ, הרי שהוא בהארץ דוקא דתחילה הוא נרקב לגמרי, וכמו\"כ האדם הנה כתי' וייצר ה' אלקים את האדם עפר מן האדמה, וכמו\"כ בע\"ח גופם מהארץ ומקבלים חיות ג\"כ מהארץ, ומ\"מ הם מופרדים מהארץ דהוא חי כשהוא שט באויר או בים, וכן צומח לאחר שנגדל א\"צ להארץ. וזהו\"ע נבראים דעלדאת\"ג שהם נפרדים מהארץ. וכמו\"כ יובן למעלה דנבראים דעלדאת\"כ הם בטלים לאלקות, ונבראים דעלדאת\"ג הם יש ודבר נפרד בפ\"ע. וזהו דכתי' גבי משה ונתתי מטר<sup data-n=\"881\">12</sup> ארצכם בעתו והאיך קאמר ונתתי, דמה שאומר ונתתי הוא מפני שקאי בא\"י, דהנה כתי' הנותן מטר בארץ השולח מים ע\"פ חוצות, דבשאר ארצות הוא שולח מים ע\"י שליח אבל בא\"י הוא נותן בעצמו, אך איך",[["879","10","<b>ים ויבשה הוא עלדאת\"כ ועלדאת\"ג</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380143\" data-slug=\"likkutei-torah\" data-id=\"4001380143\">לקו\"ת צו טז, ד</a> ואילך. מאמרי אדה\"ז פרשיות ח\"א ע' רנה ואילך. רסז ואילך. שער האמונה לאדהאמ\"צ פד, א ואילך. ועוד."],["880","11","<b>כמו מלאכים הנה כ' בי נשבעתי נאום הוי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380290\" data-slug=\"likkutei-torah\" data-id=\"4001380290\">לקו\"ת בחוקותי נ, א</a>. סה\"מ תרכ\"ט ע' ריד ואילך. תרל\"ב ח\"א ע' לט. תרל\"ג ח\"א ע' נא. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300031276\" data-slug=\"likkutei-sichot\" data-id=\"1300031276\">לקו\"ש ח\"ג ע' 1014</a>. ח\"ד ע' 1087. ובכ\"מ."],["881","12","<b>וזהו דכתי' גבי משה ונתתי מטר</b>: ראה בהנסמן בהערה שלפנ\"ז."]]],[2002180290,"הו\"א אומר כן. והענין דהנה משה הי' מעלדאת\"כ, וגם כמו שהי' בעלדאת\"ג הי' בבחי' עלדאת\"כ דכתי' עליו ונחנו מה פי' בלי מציאות ובלי מהות, וזה כתי' עליו כמו שהי' בעלדאת\"ג ושכינה מדברת מתוך גרונו, והי' בטל בתכלית ולכן א' ונתתי ששכינה מדברת מתוך גרונו. והנה בזהר נק' זה בשם נונא ימא רבא (במק\"מ ד\"ו א' מפרש ימא רבא הוא יסוד אימא) כמו ברואים שבים הם מובלעים במי הים כמו\"כ יש בנשמות ג\"כ שהם בבחי' עלדאת\"כ, ובכלל הוא ההפרש בין מלאכים בגופים<sup data-n=\"882\">13</sup>* ובין נשמות בגופים ולכן המלאך אינו בעל בחירה<sup data-n=\"883\">14</sup> שהרי הוא שליח ויש בו כח המשלח ובפ\"ע אינו מהות כלל ואינו שייך שישנה מאומה, אבל האדם הוא בעל בחירה ויכול לבחור שיהי' כמו משה, דהנה אמרז\"ל מתי יגיעו מעשיי למעשי אבותיי הם האבות אברהם יצחק ויעקב, וכמו\"כ כמו משה ג\"כ, ויכול לבחור ההיפוך לגמרי.\n<b>וזהו</b> שבתחילת הבריאה הי' מים למעלה מארץ, דבסדר השתל' מים למעלה מארץ, דהמים למעלה מארץ ורוח למעלה ממים ואש למעלה מרוח ושמים מקיף לכולם, מ\"מ עיקר הכוונה הוא הארץ [וזהו דאי' בכהאריז\"ל דלידת הנשמות הוא בשביעי ש\"פ מפני שאז הוא זמן קרי\"ס<sup data-n=\"884\">15</sup>], ולכן מ\"ת הי' בארץ דוקא, דהים אמר אין בי, תהום אמר אין עמדי, כ\"א בארץ דוקא. אפי' מלאכים כשבקשו תורה<sup data-n=\"885\">16</sup> ואמרו אשר תנה הודך על שמים וא\"ל כלום יש בכם יצה\"ר, וצ\"ל מהו הטענה והלא לא בקשו תורה בגשמיות שאם היו מבקשים בגשמיות יש מצות שצריכין יצה\"ר לקיימם, אבל הם בקשו ברוחניות ומהו הטענה כלום כו', אלא מפני שעיקר הכוונה שיהי' בארץ דוקא מפני שהוא מדרי' גבוה נמשך למטה יותר, וכמו אותיות החקוקים על אבן טוב מצד עוצם בהירות האבן<sup data-n=\"886\">17</sup> א\"א לקרות אותם כ\"א כשהם על השעוה שאז הם רק הפעולה אז אפשר לקרות אותם, והוא מצד בהירות האבן וכשנתרחקו מן האותיות<sup data-n=\"887\">18</sup> דוקא אז אפשר לקרותם, כמו\"כ בתורה מפני שהוא מדריגה גבוה לכן הוא דוקא בארץ. וזהו אנכי עשיתי ארץ ואדם עלי' בראתי, מה שאנכי עשיתי ארץ הוא בשביל אדם בראתי, בראתי בגימטריא תרי\"ג, ואדם הוא מ\"ש זאת התורה אדם, דהנה כתי' ועל דמות הכסא דמות כמראה אדם עליו מלמעלה וצ\"ל והלא אין לו דמות הגוף ולא גוף ואיך שייך לומר כמראה אדם אלא שהוא בחי' זאת התורה אדם, דרמ\"ח פקודין רמ\"ח אברין דמלכא ושס\"ה ל\"ת שס\"ה גידין. ובאמת הנה הארץ למעלה במדרי' מהשמים, דהנה יש פלוגתא שמים קדמה או ארץ קדמה ואלו אלו דא\"ח",[["882","13","<b>ההפרש בין מלאכים בגופים</b>: כ\"ה בגוכי\"ק. [ומבואר בכ\"מ דגופות המלאכים הם מיסודות רוחניים דאש ורוח. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370015\" data-slug=\"torah-or\" data-id=\"3901370015\">תו\"א ד, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381119\" data-slug=\"likkutei-torah\" data-id=\"4001381119\">לקו\"ת ברכה צח, א</a>. סידור ערה, ד. ועוד]."],["883","14","<b>המלאך אינו בעל בחירה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט (נב, רע\"ב</a>). <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560384\" data-slug=\"or-hatorah-hb\" data-id=\"8316560384\">אוה\"ת נח (כרך ג) תרנח, ב</a>. סה\"מ תרכ\"ט ע' קסד-ה. וש\"נ. תר\"ל ע' רסח. ועוד."],["884","15","<b>דלידת הנשמות הוא בשביעי ש\"פ . . זמן קרי\"ס</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380141\" data-slug=\"likkutei-torah\" data-id=\"4001380141\">לקו\"ת צו טז, סע\"ב</a> ואילך. שער האמונה לאדהאמ\"צ פס\"ב ואילך (צז, א ואילך)."],["885","16","<b>מלאכים כשבקשו תורה</b>: בכ\"ז ראה גם ביאוה\"ז לאדהאמ\"צ א, סע\"ד ואילך. ולהצ\"צ ע' תריב ואילך."],["886","17","<b>וכמו אותיות החקוקים על אבן טוב . . עוצם בהירות האבן</b>: ראה בכ\"ז סה\"מ תרכ\"ט ע' ריח-ט. ועוד."],["887","18","<b>וכשנתרחקו מן האותיות</b>: בסה\"מ תרכ\"ט שם הלשון: כ\"א כשחותמים אותם על השעוה שמתרחקים מן האבן טוב אז יכולים לקרותם."]]],[2002180291,"דבסדר השתל' שמים קדם ובשרש ארץ קדם<sup data-n=\"888\">19</sup>. וזהו לרוקע הארץ על המים כל\"ח, שהארץ הוא עיקר, כי לעולם חסדו הוא תורה דכתי' תורת חסד.\n<b>וביאור</b> הענין דהנה מי הים הם מלוחים<sup data-n=\"889\">20</sup> לכן אסור לרחוץ במי הים מפני שמחזי כרפואה, כן פירש\"י, וברמב\"ם פי' משום מעמל, והוא ג\"כ מפני המלח שבו, ולכן נק' המוליכים הספינה בשם מלחים כמ\"ש גבי יונה וייראו המלחים כשהתחיל לשבור הספינה<sup data-n=\"890\">21</sup>, וכן אניות הים ומלחיהם, והוא ע\"ש המלח. וכשהם בוקעים את עפר הארץ אז הם מים חיים. והנה יש מעלה במים חיים על הים, דהנה יש דעה דים הוא כמקוה ואינו מטהר רק באשבורן, ואפילו להדיעה שמטהר גם בזוחלין ודוקא טומאות הקלות, אבל זב, ואפי' זבה ג\"כ יש דעה בב\"י לפי' א' דרש\"י ולא פסקינן כן דאי' ברייתא בת\"כ חומר בזב מבזבה שהזב טעון מים חיים וזבה אינו טעון מים חיים, אבל טומאות החמורות כמו זב ומצורע וטמא מת דמי חטאת טעונין מים חיים<sup data-n=\"891\">22</sup>.\n<b>והנה</b> מ\"ש שמי הים הם מלוחים אינו לגריעותא שאומרים שמים חיים יש להם מעלה על מי הים, אינו כן, אלא שמים חיים הם מעולים יותר אבל מי הים הם ג\"כ מעלה. דהנה כתי' לא תשבית מלח<sup data-n=\"892\">23</sup> ברית אלקיך, כמו מלח שאין לו טעם בפ\"ע אלא שהוא מטעים את דבר האחר, כמו\"כ למעלה הנה טעמים הוא מדרי' גבוה דכמו שיש בתורה טנת\"א הנה טעמים הוא מדרי' הגבוה יותר ומאיר בחכ'<sup data-n=\"893\">24</sup>, וזהו מל\"ח בגי' מזל ע\"ה<sup data-n=\"894\">25</sup> שהוא מדרי' גבוה, וזהו שהמלח מפריד הדם שהוא גבורה, דהנה יניקת החיצונים הוא מקו השמאל גבו', והמלח מפריד את הדם, וזהו\"ע המלח שמטעים שם אלקים, דשם אלקים הם ק\"ך צירופי אלקים דכל אות יש בו ך\"ד וה' אותיות הרי ק\"ך<sup data-n=\"895\">26</sup>, וזהו שכ' בס\"י שתי אבנים בונים שתי בתים, שלשה בונים ששה בתים, ארבעה ך\"ד עד שעולה ק\"ך, וממ\"ח צרופים אחרונים דשם אלקים אפשר לקבל גם הקליפות, והמלח הוא מטעים שם אלקים שמחבר הוי' ואלקים, וזהו שמי הים הם מלוחים. דהנה כתי' ותשליך במצולות ים כל חטאתם, וזהו עמקי הקליפות,",[["888","19","<b>דבסדר השתל' שמים קדם ובשרש ארץ קדם</b>: ראה סה\"מ תרכ\"ז ע' רעו ואילך. תרכ\"ט ע' כג ואילך. שצח ואילך. תרל\"ב ח\"א ע' קט ואילך. וש\"נ."],["889","20","<b>וביאור הענין דהנה מי הים הם מלוחים</b>: בהבא לקמן ראה אוה\"ת ויקרא (כרך ד) שם ע' א'סא ואילך. סה\"מ תרכ\"ט ע' קפ ואילך. עזר\"ת ע' ריב ואילך."],["890","21","<b>כמ\"ש גבי יונה . . כשהתחיל לשבור הספינה</b>: ביונה א, ד: וה' הטיל רוח גדולה אל הים ויהי סער גדול בים והאני' חשבה להשבר."],["891","22","<b>טומאות החמורות . . טעונין מים חיים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380481\" data-slug=\"likkutei-torah\" data-id=\"4001380481\">לקו\"ת שלח מב, ב</a>. [ובהמ\"מ לשם]. אוה\"ת חוקת ע' תתס."],["892","23","<b>דהנה כתי' לא תשבית מלח</b>: בהבא לקמן ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380089\" data-slug=\"likkutei-torah\" data-id=\"4001380089\">לקו\"ת ויקרא ג, סע\"ד</a> ואילך."],["893","24","<b>שיש בתורה טנת\"א . . טעמים . . הגבוה יותר ומאיר בחכ'</b>: ראה בארוכה לעיל ח\"א ע' קכ. וש\"נ."],["894","25","<b>מל\"ח בגי' מזל ע\"ה </b> [ עם הכולל]<b></b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380090\" data-slug=\"likkutei-torah\" data-id=\"4001380090\">לקו\"ת ויקרא ד, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380498\" data-slug=\"likkutei-torah\" data-id=\"4001380498\">שלח מו, ג</a>. [וראה לעיל ע' תי בהערה]."],["895","26","<b>ק\"ך צירופי אלקים דכל אות . . ך\"ד וה' אותיות הרי ק\"ך</b>: ראה סה\"מ תש\"ט ע' 188 בהערה."]]],[2002180292,"אך זהו סתם ים, אבל מה שאומרים שמי הים הם מים מלוחים הוא, דהנה אלקים הוא ים אלה, ומים אפשר גם לקליפות לינק, וזהו שמי הים מלוחים להמתיק הגבורות דש' אלקים.\n<b>אמנם</b> מים חיים הוא מדרי' היותר גבוה. ובכלל הוא ההפרש בין צדיקים לבע\"ת, דהנה צדיקים אי' בזהר מאן דנטר ברית איקרי צדיק, וזהו שא' ברית אלקיך והול\"ל אלקיך, אלא שזהו מאן דנטר כו', דהנה עצם קיום מצות מילה זהו ברית, ומאן דנטיר ברית איקרי צדיק. ובע\"ת הוא מדרי' היותר גבוה דמקום שבע\"ת עומדים צדיקים גמורים אינם יכולים לעמוד, וזהו דבע\"ת משכין לי' בחילא יתיר מצדיקים. וזהו משיחא אתא לאתבא צדיקייא בתיובתא, שגם צדיקים יבואו למדרי' תשובה, דמי שהוא במדרי' עבודת הצדיק אינו במדרי' בע\"ת וזה שמשיחא כו' שגם צדיקים יהיו במדרי' בע\"ת, וזהו דוקא ע\"י שנתלבשה הנשמה בגוף שע\"י הסתר הגוף יכול לבוא לבחי' זו, וכמו מים שסוכרין הילוכה עי\"ז היא הולכת בכח און רייסט דורך, כמו\"כ ע\"י הסתר עי\"ז יבואו לבחי' זו.\n<b>ובכלל</b> הוא ההפרש* בין אהבה דבכל נפשך לאהבה דבכל מאדך, דהנה אהבה דבכל נפשך הוא לאהבה את ה' אלקיך כי הוא חייך כמו שהאדם אוהב חיי נפשו וזה יודע מי שהוא חלוש שרוצה שיבריא והוא שיתפשט החיות, כמו\"כ העולם שהוא גוף גדול ויש חיות אלקי המחי' אותו, וכמו שאוהב חיי נפשו כמו\"כ יהי' לו אהבה לאלקות. ובכל מאדך הוא שיוצא מהגבלת הכלי, דאהבה דבכל נפשך הוא אור בכלי, ואהבה דבכל מאדך הוא שיוצא מהגבלות הכלי ולכן אינו נפסק, דאהבה דבכל נפשך אפשר ליפסק שאינו יכול להיות כל היום בההתבוננות, וכשנפסק ההתבוננות נפסק גם האהבה, משא\"כ אהבה דבכל מאדך הוא שיוצא חוץ מהגבלות הכלי לכן אינו נפסק. והנה בע\"ת יכולים לבוא לבחי' זו, דהנה בעלי עסקים אינם יכולים להיות תמיד בהתבוננות וכשפונים מעסקם [ולומדים תורה] יכולים לבוא למדרי' בכל מאדך. וזהו מעלת תפלת מנחה<sup data-n=\"896\">27</sup> שכן אליהו לא נענה אלא בתפלת מנחה, וצ\"ל למה תפלת מנחה דוקא, והענין דהנה בתפלת שחרית הוא מיד שניעור משנתו ולא ראה את ההיפך, וכשמתפלל בהתקשרות לאלקות דתפלה הוא ל' התקשרות (בל\"א קלעפ) וכמו הטופל כלי חרס, אין זה חדוש כ\"כ, אבל בתפלת מנחה שהוא טרוד בעסקיו\n\n*)ההפרש בין אהבה דבכל נפשך לאהבה דבכל מאדך: בשולי המאמר נרשם בגוכי\"ק: לעבדו בכל לבבכם הוא ג\"כ מ\"ש בכל לבבך בשני יצריך, ובירור דיצה\"ר הוא בכל מאדך, וזהו בחי' מים חיים.",[["896","27","<b>וזהו מעלת תפלת מנחה</b>: בהבא לקמן ראה אוה\"ת וישלח רלה, א. רלז, סע\"ב ואילך. נ\"ך ס\"ע עא ואילך. עד ואילך. סה\"מ תרכ\"ז ע' נב ואילך. תרל\"ה ח\"א ע' ד ואילך. טו ואילך. עזר\"ת ע' פב ואילך. תרפ\"ח ע' כט ואילך."]]],[2002180293,"ומתפלל מנחה בהתקשרות יכולים לבוא לבחי' אהבה דכל מאדך. וזהו עמוד העבודה דרזא דקורבנא עולה עד רזא דא\"ס שהוא הארת עצמות א\"ס.\n<b>וזהו</b> הקדוש הא'<sup data-n=\"897\">28</sup> שהוא העטרה שנטל ונתן בראשו, והיינו שיהי' לו רצון ותשוקה לא\"ס שהוא קדוש ומובדל שאין ערוך דבי\"ה ה' צור עולמים ביו\"ד נברא עוה\"ב ובה' עוה\"ז, ומה תופס מקום ב' אותיות לגבי הדיבור שבאדם, ומכ\"ש לבחי' מח' ומכ\"ש לגבי עצם מהות האדם, וכללות עוה\"ז ועוה\"ב הם רק מב' אותיות שאינם רק משם והארה בעלמא שאינו נוגע לעצמיות, וזהו שיהי' רצון ותשוקה. וזהו בעטרה שעטרה לו אמו, שכנס\"י מעטר עטרה להקב\"ה, וזהו אהבה דבכל מאדך.",[["897","28","<b>וזהו הקדוש הא'</b>: בהבא לקמן ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380210\" data-slug=\"likkutei-torah\" data-id=\"4001380210\">לקו\"ת אמור לא, א</a> ואילך."]]],[2002180294,"<h3>על שלשה דברים (יום ב' דחה\"ש קודם התפילה)</h3>\n<b></b><b>יום ב' דחה\"ש בוקר קודם התפלה, ט\"ל לפ\"ק.</b>\n<b>על</b> ג' דברים<sup data-n=\"898\">1</sup> העולם עומד על תורה ועבודה וגמ\"ח, הנה נת\"ל דג' בחי' אלו הם ג' בחי' קדוש, עמוד העבודה הוא נגד קדוש הא' דרזא דקורבנא עולה עד רזא דא\"ס, ותפלה במקום קרבנות תקנו, דאהבה דבכל מאדך הוא שיוצא חוץ מהגבלות הכלי וע\"י הקרבנות דנה\"ב ממשיכים עטרה לבחי' מלך שהשלום שלו, וזהו קדוש הא' שיהי' רצון ותשוקה למדרי' שהוא קדוש ומובדל שלמעלה מע\"ס.\n<b>והנה</b> אי' בס\"י אם רץ לבך שוב לאחד שאם יש לו רצון ותשוקה לאלקות צ\"ל אח\"כ שוב, והוא הקדוש הב', והוא מעשה המצות. דהנה מצות שרשן למעלה מאד וזהו הברכה אשר קדשנו במצותיו וצונו, אשר הוא עונג ותענוג העליון מפני שהוא דבר נפלא, וצ\"ל מה שייך אשר לדבר מופלא. הנה כתי' הנמצא כזה איש אשר רוח אלקים בו ואי' במד' הה\"ד קמו בניה ויאשרוה בעלה ויהללה, וצ\"ל מה שייכים פסוקים אלו זה לזה. והענין דהנה פי' הנמצא כזה איש אשר רוח אלקים בו, הנמצא אדם שיהי' בו געטלעך קייט כ\"כ שיבין ענין כזה, ולכן מהללים ומשבחים אותו, וזהו קמו בניה ויאשרוה בעלה ויהללה, מפרש אשר ל' תענוג כמ\"ש באשרי כי אשרוני בנות, ולכן מהללים ומשבחים אותו. וזהו אשר שהוא תענוג שהוא דבר נפלא, קדשנו במצותיו וצונו שנמשך למטה, וזהו\"ע המצות להמשיך שיהי' לו דירה בתחתונים, דהנה קדוש הא' שממשיכים עטרה למלך שהשלום שלו, וזהו שממשיכים כתר אריך",[["898","1","<b>על ג' דברים</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב מהמאמר ד\"ה ”והנה איתא בס\"י אם רץ לבך\" הנדפס לעיל ע' תיא ואילך. מאמר זה הוא המשך להמאמר שלפנ\"ז ד\"ה צאינה וראינה."]]],[2002180295,"לנאצלים, אבל למטה אינו נמשך כלל, וקדוש הב' הוא שיומשך למטה, ועיקר הגילוי יהי' לע\"ל ועכשיו הוא להוסיף אורות באצי' וה\"ה כמונח בקופסא<sup data-n=\"899\">2</sup>. וזהו שפי' התרגום בקדושא דבי סדרא על קדוש הא' פי' קדיש בשמי מרומא עילאה בית שכינתא, ועל קדוש הב' פי' קדיש על ארעא עובד גבורתי', דהנה קדוש הא' הוא ביטול דבכל מאדך ועי\"ז ממשיכים עטרה למלך שהשלום שלו, אבל למטה אינו נמשך מזה וזהו קדיש בשמי מרומא שהוא רק שנמשך כתר דאריך בנאצלים, אבל למטה אינו נמשך מזה, וקדוש הב' שהוא מעשה המצות שהוא להמשיך למטה וזהו קדיש על ארעא עובד גבורתי'.\n<b>ועל</b> קדוש הג' פי' קדיש לעלם ולעלמי עלמיא שהוא לדורי דורות והוא נגד עמוד התורה. והענין הוא שלא יאמר האדם מהו עבודתי שעי\"ז ימשיך בחי' שאינו בנאצלים, וגם ע\"י המצות ימשיך למטה, ע\"ז הוא עמוד התורה שנותן כח על ההעלאה וההמשכה. דהנה עיקר התורה הוא הדיבור, וזהו וידבר ה' אל משה, ויאמר אל משה, דבר אל בנ\"י, שכל התורה הוא מלא בדיבור ואמירה, וזהו והיו הדברים האלה בד\"ת הכתוב מדבר, ושננתם לבניך ודברת בם שהעיקר דיבור, וכן בתושבע\"פ הנה אמרז\"ל אם ערוכה בכל שמורה, אם ערוכה ברמ\"ח אברי' שמורה, שהדיבור צ\"ל בכח, הרי העיקר הוא הדיבור, ויש בחי' עיון דתורה<sup data-n=\"900\">3</sup> ובזה הו\"ע פלפול, והעיקר הוא התקשרות המח' שיקשר מחשבתו בתורה ויהי' מקיף ומוקף<sup data-n=\"901\">4</sup>, והנה ע\"י העיון דתורה נותן כח על ההעלאה שיבוא לבחי' בכל מאדך שהוא התקשרות המח' שיקשר מחשבתו בתורה ויהי' מקיף ומוקף, דתחילה עדיין אינו יודע השכל וה\"ה מוקף ממנו ואח\"כ כשיודע אותו ה\"ה מקיף אותו. וע\"י דיבור דתורה ממשיך למטה, וזהו כל הקורא בתורה הקב\"ה קורא ושונה כנגדו שהוא ההמשכה שנמשך למטה. ובכלל הוא ההפרש בין תושב\"כ ותושבע\"פ, דתורה שבכתב הוא מ\"ש כל הקורא בתורה כו', דהנה כל התורה שמותיו של הקב\"ה וכמו שם האדם כשקוראין לו בשמו כמו אברהם ראובן הוא בא, כמו\"כ כל הקורא בתורה שהוא הדיבור הוא ממשיך למטה, ותושבע\"פ הוא העיון דהנה ערוכה בכל שמורה הוא בתושבע\"פ, דבאמת יש בתושב\"כ ובתושבע\"פ שני דברים אלו דיבור ועיון, רק שבתושב\"כ העיקר הוא הדיבור, ותושבע\"פ העיקר הוא העיון, דעיון שייך בתושבע\"פ דוקא, דבתושב\"כ אינו מושג, וזהו הכח שיש בתורה על ההעלאה והמשכה. וזהו לאמר שבמ\"ת דלכאו' מהו לאמר<sup data-n=\"902\">5</sup>, דמ\"ש וידבר אל משה לאמר הוא שיאמר לישראל, אבל במ\"ת דאנכי ולא יהי' לך מפי",[["899","2","<b>ועכשיו הוא להוסיף אורות באצי' וה\"ה כמונח בקופסא</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380715\" data-slug=\"likkutei-torah\" data-id=\"4001380715\">לקו\"ת דברים א, ב</a>. מאמרי אדה\"ז תקס\"ב ח\"ב ע' שפג ואילך. מאמרי אדהאמ\"צ ויקרא ח\"א ע' נה. סה\"מ תרכ\"ז ע' תסז. תרכ\"ט ס\"ע רכח-ט. ד\"ה פזר נתן תרמ\"ב. סה\"מ מלוקט ח\"א ע' ז."],["900","3","<b>עיקר התורה הוא הדיבור . . ויש בחי' עיון דתורה</b>: ראה גם מאמרי אדה\"ז ענינים ע' רכד-ה. מאמרי אדהאמ\"צ ויקרא (כרך ב) ע' תקצג. ובכ\"מ."],["901","4","<b>שיקשר מחשבתו בתורה ויהי' מקיף ומוקף</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ\"ה (ט, א</a> ואילך)."],["902","5","<b>וזהו לאמר שבמ\"ת דלכאו' מהו לאמר</b>: ראה בכ\"ז בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370301\" data-slug=\"torah-or\" data-id=\"3901370301\">תו\"א יתרו סז, ב</a>. סה\"מ תרכ\"ט ע' רכג. תרל\"ג ח\"א ע' רצז."]]],[2002180296,"הגבו' שמענו ובזה נכלל רמ\"ח מ\"ע ושס\"ה מל\"ת ומהו לאמר, אך לאמר הוא שיש כח זה בתורה לעולם, שתושב\"כ הוא כח על ההמשכה ותושבע\"פ הוא כח על ההעלאה. וזהו אם פגע בך מנוול זה משכהו לבית המדרש אפי' אם אבן הוא נמוח, בית המדרש הוא הדרש על הפסוק ועי\"ז הוא הבירור דנה\"ב, וזהו ביטול דבכל מאדך, אפי' אם אבן הוא נמוח שיהי' כמו לע\"ל והסירותי לב האבן מבשרכם ונתתי לכם לב בשר, וגם לב בשר יהי' כמ\"ש יבוא כל בשר להשתחוות לפני, וזהו קדוש הג'.\n<b>והנה</b> ג' בחי' קדוש אלו הם בג' פרשיות דק\"ש, פרשה א' הוא כנגד קדוש הא', וזהו בכל מאדך שיוצא חוץ מהגבלת הכלי ועי\"ז מעטר עטרה לבחי' מלך שהשלום שלו. ופ' שני' הוא כנגד קדוש הב' שהו\"ע המצות דכאן כתי' והי' אם שמו\"ע תשמעו ועי\"ז ממשיכים למטה, ולכן בפ' שני' יש כל ההשפעות, השפעות רוחניים והשפעות גשמיים. ופ' שלישי' הוא קדוש הג' שלא יאמר האדם מה עבודתי, ואפי' כשמברר הנה\"ב מה תופס מקום שעי\"ז ימשיך מדרי' גבוה כזו, זהו שאמר בפ' ג' אני הוי' אלקיכם אשר הוצאתי אתכם מארץ מצרים, דהנה במצרים היו משוקעים במ\"ט דהיפוך ובחמשים יום הי' מ\"ת, וירד ה' על הר סיני רואין את הנשמע ושומעין את הנראה שהי' גילוים גבוהים, ומ\"ת הי' ביום החמשים שהוא שער הנו\"ן דבינה, אני ה' אלקיכם עתה ג\"כ, וזהו אשר הוצאתי אתכם מארץ מצרים בכל יום ויום חייב אדם לראות א\"ע כאלו הוא יצא ממצרים, מצרים הם המצרים וגבולים שהוא בעל גבול ורצונות זרות, ומה שהם זרות הוא מפני שהוא בע\"ג, ויצ\"מ הוא שלא יהי' עוד המצרים וגבולים כו'.\n<b>וזהו</b> בשעה שהקדימו ישראל נעשה לנשמע ירדו מה\"ש וקשרו להם ב' כתרים, דהנה נעשה הוא כלי ונשמע הוא אור<sup data-n=\"903\">6</sup>, נעשה הוא מצות ונשמע הוא תורה, ובאמת הוא ענין א' דהנה כתי' כי נר מצוה ותורה אור<sup data-n=\"904\">7</sup> שמצוה הוא כמו נר שמחזיק השמן והפתילה והם מחזיקין את האור נמצא הנר מחזיק השמן והפתילה והאור כמו\"כ מצות הם כלים, ותורה הוא אור. וצ\"ל שניהם תורה ומצות, דתורה בלא מצות הוא אור בלי כלי ואור צריך דבר שיאחז בו. וזש\"ה כלים ריקים אל תמעיטי, אין עוד כלי ויעמוד השמן, שהשמן צריך כלי. וזהו שאנו מבקשים קדשנו במצותיך ותן חלקינו בתורתך, תחילה צ\"ל קדשנו במצותיך שהוא הכלי ואח\"כ ותן חלקינו בתורתיך שהוא האור, וזהו שע\"י תומ\"צ ממשיכים ב' כתרים כתר תורה וכתר מצות הוא כתר ז\"א וכתר מל'.\n<b>אך</b> צ\"ל דהנה אמרז\"ל בשעה שהקדימו ישראל נעשה לנשמע ירדו מה\"ש וקשרו להם שני כתרים, שמשמע דמה שקשרו להם ב' כתרים הוא מפני שהקדימו",[["903","6","<b>נעשה הוא כלי ונשמע הוא אור</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370435\" data-slug=\"torah-or\" data-id=\"3901370435\">תו\"א מג\"א צז, ב</a>."],["904","7","<b>דהנה כתי' כי נר מצוה ותורה אור</b>: בהבא לקמן ראה סה\"מ תרל\"א ע' קו-ז. וש\"נ. וראה גם לעיל ח\"א ע' קמד ואילך."]]],[2002180297,"נעשה לנשמע<sup data-n=\"905\">8</sup>, ואם לא היו מקדימים לא הי' נמשך כלל, וכאן אומר שע\"י נעשה ונשמע שהם תומ\"צ ממשיכים הב' כתרים.\n<b>והענין</b> דהנה מה שהקדימו נעשה לנשמע הוא ביטול גדול מאד שמא יאמר להם דברים שאין בכוחם לעשות זה, מ\"מ אמרו נעשה הוא ביטול לבעל הרצון שלמעלה מרצונות פרטים. והענין דהנה צ\"ל איך ע\"י המצות למטה כמו ע\"י תפילין ממשיכים מוחין לז\"א והלא תפילין כותבין בדיו גשמי על קלף גשמי ואיך ממשיכים עי\"ז, וכן צדקה שהוא להחיות רוח שפלים וע\"י שישראל עושה למטה צדקה גורם למעלה ג\"כ<sup data-n=\"906\">9</sup> להחיות רוח שפלים, דהנה לגבי א\"ס העולמות בכ\"מ שנדבר הם שפלים ודלים וע\"י המצות ממשיכים באצי', ואיך בכח האדם להמשיך זה. דהנה האבות המשיכו זה ע\"י המס\"נ אבל אנו שמניחים תפילין בלי מס\"נ וגם בלי כוונה רק כוונה הפשוטה לשעבד הלב והמוח, וכן בצדקה רק להחיות רוח שפלים, איך ממשיכים עי\"ז. אך הנה כך עלה ברצונו שע\"י הרצונות פרטים ימשיכו למטה, בשבת (שאחר ששת ימי החול, וע' לעיל במאמר של שבת הקדום<sup data-n=\"907\">10</sup>) נמשך מוחין דאבא וביו\"ט מוחין דאימא וע\"י תפילין מוחין לז\"א. והנה כדי שיהיו הרצונות פרטים, דהנה רצון אותיות צנור והוא הצמצום הראשון, וצריכים להמשיך מבעל הרצון שיומשכו הרצונות פרטים, וזהו ע\"י הביטול לבעל הרצון שלמעלה מהרצונות פרטים ועי\"ז יומשכו הרצונות פרטים. וזהו שאמרז\"ל וכי אדם זורע בשעת זריעה וקוצר בשעת קצירה תורה מה תהא עלי', אלא בזמן שישראל ערש\"מ מלאכתן נעשה ע\"י אחרים וכמו שנא' ועמדו זרים ורעו צאנכם, ובזמן שאין ישראל ערש\"מ מלאכתן נעשה ע\"י עצמן, וכמו שנא' ואספת דגנך. והקשה בתוס' והלא ואספת דגנך הוא בפ' שני' ושם נא' והי' אם שמוע תשמעו, ותירץ אין ערש\"מ כ\"כ, והיינו שערש\"מ אך אינו כ\"כ, וזהו שלא נא' שם בכל מאדכם<sup data-n=\"908\">11</sup> דכתי' בכל לבבכם ובכל נפשכם, ובכל מאדכם לא נא', ולכן נק' אין ערש\"מ. ממילא מובן במקום שנא' בכל מאדך נק' ערש\"מ שהוא הביטול לבעל הרצון שלמעלה מרצונות פרטים, ועי\"ז ממשיכים הרצונות פרטים. והגם שמה תופס מקום בלי גבול האדם לגבי א\"ס, אך כשהוא מבקש אינו מבקש אלא לפי כוחן, כשהוא נותן נותן לפי כחו וכמ\"ש הן אל ישגיב בכחו מי כמוהו מורה, וכשהוא מבקש מבקש לפי כחן שור או כשב או עז ואינו מבקש איל וצבי רק דבר המצוי. וזהו מפני שהקדימו נעשה לנשמע הו\"ע הביטול לבעל הרצון עי\"ז ממשיכים אח\"כ ע\"י המצות שיומשך למטה.",[["905","8","<b>שמשמע דמה שקשרו להם ב' כתרים הוא מפני שהקדימו נעשה לנשמע</b>: ראה בכ\"ז בארוכה סה\"מ תרכ\"ט ע' רב. [ובהנסמן שם בתחילת המאמר]."],["906","9","<b>צדקה . . להחיות רוח שפלים . . גורם למעלה ג\"כ</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370283\" data-slug=\"torah-or\" data-id=\"3901370283\">תו\"א בשלח סג, ב</a>. סה\"מ תרל\"ג ח\"ב ע' תסה. וש\"נ."],["907","10","<b>ועי' לעיל במאמר של שבת הקדום</b>: לעיל ד\"ה מי זאת הנשקפה."],["908","11","<b>ואספת דגנך הוא בפ' שני' . . שלא נא' שם בכל מאדכם</b>: ראה בכ\"ז או\"ת להה\"מ פ' עקב נג, סע\"ג ואילך. סה\"מ תרכ\"ט ע' קצז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121098\" data-slug=\"likkutei-sichot\" data-id=\"1300121098\">לקו\"ש חי\"ב ע' 98</a> ואילך. וש\"נ."]]],[2002180298,"<b>והנה</b> זה הי' במ\"ת, אך אח\"כ ויתנצלו בנ\"י את עדים מהר חורב הם הב' כתרים, ואי' במד' ועתיד הקב\"ה להחזירן לנו שנא' ופדויי ה' ישובון ובאו ציון ברנה ושמחת עולם על ראשם ששון ושמחה ישיגו ונסו יגון ואנחה, שמחת עולם שהשמחה שהי' מעולם זה עתיד להחזיר לנו, והקב\"ה בעצמו שלא ע\"י שליח, דבמ\"ת הי' ע\"י מה\"ש וכמארז\"ל ירדו מה\"ש כו', ויחזירם לנו בעצמו מפני שהוא מדרי' היותר גבוה וא\"א לימשך ע\"י שליח. והענין דהנה אמרז\"ל לע\"ל צדיקים יושבין ועטרותיהם בראשיהם, ענין עטרה הוא כמו כתר שהוא ממוצע בין מאציל לנאצלים כמו\"כ העטרה הוא ח\"י שהוא ממוצע בין אוא\"ס לנר\"ן, וזהו ועטרותיהם בראשיהם שהעטרה יאיר בנר\"ן.\n<b>וזהו</b> והי' הנשאר בציון והנותר בירושלים קדוש יאמר לו, ואמרז\"ל עתידים צדיקים שיאמרו לפניהם קדוש כדרך שאומרים לפני הקב\"ה ופי' רש\"י שמלאכים יאמרו לפניהם קדוש, דהנה מאחר שהקב\"ה בעצמו מחזיר להם העטרה שהוא מדרי' גבוה לכן יאמרו לפניהם קדוש. והענין דהנה לע\"ל מל' יתעלה במקום הכתר [ויהי' כתר דאו\"ח] על ל' הקבלה. והענין דהנה כתי' והי' ביום ההוא יצאו מים חיים מירושלים חצים אל הים הקדמוני, ים הקדמוני הוא ים החכ', והנה יש גידים כמו שהם מהתהום והם גידי הארץ (בפ\"ג<sup data-n=\"909\">12</sup> שאינם יוצאים לארץ) שהם קודם שנעשה המעין.\n<b>(הנה</b> כוונתו למ\"ש בד\"ה וככה שנת' שם ענין זה באריכות<sup data-n=\"910\">13</sup>. אך צ\"ל דלכאורה שם מדבר בהאין דחכ' שמהווה בינה, ונת' שם ענין זה הן בחכ' דאצי', הן בח\"ס, שכ\"כ שם שהאין דחכ' נק' אין וכמ\"ש והחכ' מאין תמצא, וכתר נק' יש אמיתי, ובינה נק' יש הנאצל, והאין דחכ' הוא הממוצע ביניהם, והנה האין דחכ' נחלק לב' בחי', אין א' התדבקותו אל הכתר, ב' התקרבותו אל הבינה, והוא כמו עד\"מ גידי הארץ הנמשכים מהתהום ונעשה מהם נהר, והנה התהום הוא משל ליש אמיתי, והנהר משל ליש הנאצל, והגידי הארץ שהם המעין הוא משל להאין. והנה הגידים נחלקי' לב', הגיד כמו שהוא נמשך מהתהום ועדיין הוא מכוסה בעפר הארץ, ונק' אין מפני שאינו תופס מקום, והגיד כמו שהוא בוקע עפר הארץ ונק' אין מפני שאינו מושג שממנו יהי' נהר (ואח\"כ כ' מפני שהוא מצומצם ואפ\"ל שהוא כוונה א') וכמו\"כ בחכ' סתימאה יש מעין סתים יעו\"ש. הרי שם נת' זה על האין דחכ' המהווה בינה, וזהו שבינה נק' נהר כידוע ומעין נק' חכ', והתהום הוא כתר, וכאן הכוונה על האין דכתר הממציא חכ', וזהו שא' קודם שנעשה המעין, וצ\"ע ולא זכיתי להבין ד\"ק. ונ\"ל שלכאן יותר מכוון מ\"ש בשערי אורה שער הפורים ד\"ה יביאו לבוש מל' פרק ך\"ד ך\"ה ך\"ו ך\"ז<sup data-n=\"911\">14</sup> יעו\"ש כנ\"ל לעיל).",[["909","12","<b>בפ\"ג</b>: בפעם ג', ר\"ל בפעם הג' שנאמר המאמר ע\"י כ\"ק אדמו\"ר מהר\"ש. [ועד\"ז לקמן בכ\"מ]."],["910","13","<b>למ\"ש בד\"ה וככה שנת' שם ענין זה באריכות</b>: המשך וככה תרל\"ז פקכ\"ה (ע' קצז)."],["911","14","<b>מ\"ש בשערי אורה שער הפורים ד\"ה יביאו לבוש מל' פרק ך\"ד . . ך\"ז</b>: דף סב, ב ואילך."]]],[2002180299,"<b>אך</b> זהו מלמעלה למטה, ולע\"ל כתי' והי' כו' מירושלים כו' אל ים הקדמוני הוא מלמטלמ\"ע שמל' יהי' כתר דאו\"ח. וזהו שלא כהפרדס שכ' מפני שהצדיקים יתעלו בצדיק וצדק, אלא מפני שמל' יתעלה במקום הכתר וממילא יאמר להם קדוש (ובפ\"ג שהרי העליונים מכתירים להקב\"ה בהעטרה, ומאחר שהצדיקים יתעלו ג\"כ למדרי' זו ממילא יאמרו להצדיקים, וזהו כדרך שאומרים להקב\"ה שהוא כדרך כו' וממילא יאמר להם ג\"כ).\n<b>וזהו</b> צאינה וראינה בנות ציון במלך שלמה בעטרה שעטרה לו אמו, צאינה שיהי' ההילוך, וראינה שיבואו לבחי' עטרה שעטרה לו אמו. והענין דהנה כתי' והתהלכתי בתוככם עתיד הקב\"ה לטייל עם צדיקים, ענין הטיול הוא דהנה כתי' והי' מדי חודש בחדשו ומדי שבת בשבתו יבוא כל בשר להשתחוות לפני, דהנה בששת ימי החול הנה בחו\"ל נמשך ההשפעה מו\"ק דעשי' ובא\"י עפ\"י רוב מו\"ק דיצי'<sup data-n=\"912\">15</sup> ולפעמים מו\"ק דבריאה, ובשבת הוא עליות העולמות דו\"ק דעשי' נתעלים בו\"ק דיצי', וו\"ק דיצי' בו\"ק דבריאה, וו\"ק דבריאה בו\"ק דאצי', ובחודש הוא עליות הדיבור ויש בחי' חדשו של חודש ושבתו של שבת הוא שיבוא כל בשר להשתחוות לפני וכמ\"ש כי השמים כו' עומדים לפני. וזהו והי' הנשאר בציון והנותר בירושלים, ציון הוא תורה כמ\"ש כי מציון תצא תורה, וירושלים הוא יראה שלם, ובכלל הוא ההפרש בין בעלי תורה לבעלי עסקים, בעלי תורה באים למדרי' זו ע\"י תורה, ובעלי עסקים שאינם פנוים ללמוד תורה באים למדרי' זו ע\"י שעושים מצוה כדבעי למהוי.\n<b>וזהו\"ע</b> ג' דברים תורה ועבודה וגמ\"ח, שע\"י העבודה מעטרין עטרה להקב\"ה [וע\"י תורה ומצות ממשיכים הב' כתרים]. וזהו ואשים דברי בפיך ובצל ידי כו', ואשים דברי בפיך הוא תורה, ובצל ידי כסיתיך הוא מצות, לנטוע [שמים] וליסוד ארץ הוא עבודת הקרבנות<sup data-n=\"913\">16</sup> שהוא סולם מוצב ארצה וראשו מגיע השמימה.\n<b>ועוי\"ל</b> (ובפ\"ג פי' הב' הוא למעלה קצת<sup data-n=\"914\">17</sup>) דלע\"ל יהי' במדרי' ואנשי קדש תהיון לי, דמלאכים אומרים קדוש הוא קדוש ו', וקדש הוא מדרי' שלמעלה ממנו שהוא קדש מלה בגרמי', וזהו קדוש הוי' דש' הוי' הוא קדש ו', וכתי' שאו ידיכם קדש וברכו שמשם נמשך לשם הוי'. ועוי\"ל דהנה כתי' בעטרה שעטרה לו אמו, שאמו מעטר עטרה, אבל העטרה אינה בחי' אמו רק שיש בכח אמו להמשיך העטרה והעטרה הוא למעלה מאמו, ולע\"ל יהי' א\"ח עט\"ב שאמו תהי' עטרה ממילא יאמר",[["912","15","<b>בששת ימי החול . . בחו\"ל . . מו\"ק דעשי' ובא\"י . . מו\"ק דיצי'</b>: ראה בכ\"ז בארוכה לעיל ח\"א ע' כב ואילך. וש\"נ. וע' לו ואילך."],["913","16","<b>וזהו ואשים דברי בפיך . . תורה . . מצות . . עבודת הקרבנות</b>: ראה בארוכה אוה\"ת ויצא ריג, ב ואילך. דברים ע' לו ואילך. שם (כרך ו) ע' ב'תקצז ואילך. נ\"ך (כרך ג) ע' א'קסז ואילך. ועוד."],["914","17","<b>(ובפ\"ג פי' הב' הוא למעלה קצת)</b>: ר\"ל שבאמירת המאמר בפעם הג' נאמר פי' הב' בחלק המאמר שלפנ\"ז."]]],[2002180300,"להם קדוש מאחר שהם העטרה שע\"ג הראש, וזהו עתידים צדיקים שיאמרו לפניהם קדוש כדרך שאומרים לפני הקב\"ה."],[2002180301,"<h3>הנני ממטיר (ש\"פ נשא)</h3>\n<b>ש\"פ נשא ט\"ל, לפ\"ק.</b>\n<b>הנני</b> ממטיר לכם<sup data-n=\"915\">1</sup> לחם מן השמים ויצא העם ולקטו דבר יום ביומו למען אנסנו הילך בתורתי אם לא, הנה נת\"ל דהמן הוא אתעדל\"ע<sup data-n=\"916\">2</sup> שמעורר האתעדל\"ת. והנה הוא נותן כח בההילוך מלמטלמ\"ע ומלמעלמ\"ט, דאתעדל\"ע שמעורר אתעדל\"ת הוא ע\"י המן וגם באתעדל\"ת אתעדל\"ע הוא ג\"כ ע\"י המן. והנה המן הי' נסיון אם ילך בתורתי כו' וצ\"ל שבחי' זו יש בתורה ג\"כ, והנה צ\"ל תחילה הנסיון דמן<sup data-n=\"917\">3</sup>, הנה כתי' איש אל יותר ממנו עד בקר, וזה הי' הנסיון דמן שאסור להכין מיום לחבירו, וצ\"ל למה אסור להכין מיום א' לחבירו שהרי שאר מאכלים מותר להכין.\n<b>והענין</b> דהנה מן שרשו מלמעלה מהזמן, וי\"ל זה על ב' אופנים, א' דזמן הוא מל' ואי' במד' מלמד שהי' סדר זמנים<sup data-n=\"918\">4</sup> קודם לכן אפ\"ל שהוא מדות, ויש מדרי' שלמעלה מהזמן דהנה אמרז\"ל מי יש לו פת בסלו ודואג למחר ה\"ז מקטני אמנה, ה\"ז קטנות, ואמרז\"ל מי שברא יומו ברא פרנסתו, בחי' מי שהוא ברא יומו הוא ברא פרנסתו, ולכן אסור להכין מיום לחבירו.\n<b>והענין</b> דהנה כתי' כי אלף שנים בעיניך<sup data-n=\"919\">5</sup> כיום אתמול מכאן שיומו של הקב\"ה אלף שנה, ואין הפי' שבמדות יש זמן אלף שנים, אלא כשמאיר הארת המדה במל' נעשה מזה במל' זמן אלף שנה. ולכן על אדה\"ר כתי' ביום אכלך ממנו כו' והי' לו אלף שנה רק שנתן ע' שנין לדוד, אבל הי' לו אלף שנה. וזהו שנמשך הארת מדת החסד במל' ונעשה ממנה במל' זמן אלף שנה ולא שבמדות יש זמן אלף שנה. וזהו",[["915","1","<b>הננו ממטיר לכם</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב מהמאמר ד\"ה ”אך להבין מ\"ש למען אנסנו\" הנדפס לעיל ע' שצו ואילך. מאמר זה הוא המשך לד\"ה מי זאת הנשקפה הנדפס לעיל."],["916","2","<b>הנה נת\"ל דהמן הוא אתעדל\"ע</b>: לעיל בד\"ה מי זאת הנשקפה ע' שצד-ה."],["917","3","<b>והנה צ\"ל תחילה הנסיון דמן</b>: בכ\"ז ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370292\" data-slug=\"torah-or\" data-id=\"3901370292\">תו\"א בשלח סה, ג</a>."],["918","4","<b>והענין דהנה מן שרשו מלמעלה מהזמן . . וי\"ל . . ב' אופנים . . סדר זמנים</b>: בהבא לקמן ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' לד ואילך. תקס\"ט ע' רפב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830293\" data-slug=\"or-hatorah-hb\" data-id=\"8158830293\">אוה\"ת בשלח ע' תרלג</a> ואילך. בלק ע' תתקעט-פ. ענינים ע' צו. סה\"מ תרכ\"ז ס\"ע לז-ח. תרכ\"ח ר\"ע קסט. המשך תרס\"ו ע' מא ואילך. ועוד."],["919","5","<b>והענין דהנה כתי' כי אלף שנים בעיניך</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380952\" data-slug=\"likkutei-torah\" data-id=\"4001380952\">לקו\"ת</a> <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381200\" data-slug=\"likkutei-torah\" data-id=\"4001381200\">דרושים לר\"ה נח, ב</a>. שה\"ש יז, ד. סה\"מ תרכ\"ט ע' שלג ואילך. וש\"נ."]]],[2002180302,"שאלף הראשון הי' חסד דורו של אנוש נזונין בחסדו של הקב\"ה, וזהו מפני הארת החסד במל', ובאלף השני האיר מדת הגבו' ולכן הי' גבו', דשנת תרנ\"ו לאלף השני הי' המבול ושנת תתקצ\"ו לאלף הב' הי' דור הפלגה, ובאלף הג' האיר מדת הת\"ת לכן בשנת תמ\"ח הי' מ\"ת (וצ\"ע והלא בשנת ש\"מ הי' גלות מצרים<sup data-n=\"920\">6</sup>). והגם שיום זה הוא ג\"כ זמן מ\"מ הוא סדר זמנים דמפני שהם מקור למקור לזמן לכן הם נק' יומין. ומי שברא יומו הוא כמ\"ש מי ברא אלה, אלה הוא ו\"ק<sup data-n=\"921\">7</sup>, ו' כלול מו' בגי' אלה, ומי שהוא בינה ברא אלה והוא למעלה מהזמן. דהנה אנו רואין שמדו' הם שייכי' לזולת דוקא דממה יודעין המדה הוא מהשפעה, וכשלא יש זולת למי להשפיע הרי בטל המדה דמאחר שכל המדה הוא ע\"ש ההשפעה, וכשאינו משפיע הרי המדה כמו שאינו, שזה שישנו ה\"ה כמו שאינו, אבל מוחין ה\"ה יכול לישב בפ\"ע<sup data-n=\"922\">8</sup> ולהשכיל השכלות, וראי' מרשב\"י שהי' זמן רב במערה ונתוסף לו ריבוי חכ', דקודם שהי' במערה הי' רפב\"י משיב לרשב\"י י\"ב פרוקא ואח\"כ הי' הוא משיב לרפב\"י ך\"ד פרוקא הרי שנתוסף לו ריבוי חכ' והי' עם ר\"א בנו שאינו שייך לתלמידיו, כמו\"כ למעלה הגם שאינו דומה מדות למעלה כמו מדות למטה, שלמטה מדת החסד רק גורם השפעה ולמעלה מדות גופא משפיע וכמ\"ש מכלכל חיים בחסד, מ\"מ הם שייכים לעולמות (וצ\"ע אדרבה יותר שייכים לעולמות) וכמ\"ש כי אמרתי עולם חסד יבנה, זכור רחמיך וחסדיך כי מעולם המה, רחמים וחסדים שייכים לעולם דוקא, אבל מוחין אינם שייכים לעולם שהם למעלה מהזמן, הגם דאמרז\"ל אלפים שנה קדמה תורה לעולם והם חו\"ב ונק' יום דכתי' ואהי' שעשועים יום יום, זהו רק שם המושאל, אבל באמת אינו שייך שם יום שהוא למעלה מהזמן.\n<b>ולכן</b> אסור להכין מן מיום לחבירו<sup data-n=\"923\">9</sup>, דשאר מאכלים שהם תחת הזמן מותר להכין אבל מן שהוא מלמעלה מהזמן ושם אינו שייך שינויים ולא יופסק לכן אסור להכין מיום א' לחבירו.\n(ע\"כ נרשם בגוכי\"ק, וחסר סיום)",[["920","6","<b>בשנת תמ\"ח הי' מ\"ת (וצ\"ע והלא בשנת ש\"מ הי' גלות מצרים)</b>: עי' סדר הדורות במקומו שירידת בנ\"י למצרים הי' בשנת ב'רל\"ח, ושעבוד וגלות מצרים התחיל בשנת ב'ש\"מ. ויצי\"מ ומ\"ת הי' בשנת ב'תמ\"ח. וראה בהנסמן לעיל ע' שצז."],["921","7","<b>כמ\"ש מי ברא אלה, אלה הוא ו\"ק</b>: ראה בכ\"ז בארוכה סה\"מ תרכ\"ז ע' שסז ואילך. תרל\"ה ח\"ב ע' שפז ואילך."],["922","8","<b>שמדו' הם שייכי' לזולת . . אבל מוחין . . בפ\"ע</b>: ראה בכ\"ז סה\"מ תרכ\"ז ע' פו. וע' רעז. תרכ\"ח ע' ד ואילך. תרכ\"ט ע' ט. וע' תו. וש\"נ. תר\"ל ס\"ע פ-פא. וע' רסז. תרל\"ג ח\"א ע' צ. וע' שטו. ח\"ב ס\"ע תקמ ואילך. תרל\"ד ע' נד ואילך."],["923","9","<b>לחבירו</b>: ע\"כ נמצא בגוכי\"ק (שם ממשיך עוד תיבה: ”ועוי\"ל\", וחסר ההמשך). וראה המשך הענין לעיל ס\"ע שצז ואילך."]]],[2002180303,"<h3>וידבר גו' בהעלותך (ש\"פ בהעלותך)</h3>\n<b></b><b>ש\"פ בהעלותך ט\"ל, לפ\"ק.</b>\n<b>וידבר</b> ה' אל משה דבר אל אהרן ואמרת אליו בהעלותך<sup data-n=\"924\">1</sup> את הנרות אל מול פני המנורה יאירו שבעת הנרות, וצ\"ל כפל ל' דבר ואמרת, והול\"ל דבר אל אהרן ותו לא, או אמור אל אהרן. ועוד צ\"ל דרש\"י פי' שהנר אמצעי הוא גוף המנורה והול\"ל יאירו ששת הנרות. ועוד צ\"ל דהנה רש\"י פי' למה נסמכה פ' המנורה לחנוכת [הנשיאים] אלא כיון שראה אהרן שכל הנשיאים הקריבו קרבנם והוא ושבטו לא הקריבו והי' מצטער מזה א\"ל הקב\"ה חייך שלך גדולה משלהם שאתה מדליק ומטיב את הנרות כ\"ה ברש\"י ובמדרש, ובמדרש מסיים שהם הקריבו קרבנות שאינם לעולם ואתה מדליק את הנרות שהוא לעולם, וצ\"ל והלא גם המנורה אינו לעולם דמשחרב בהמק\"ד ובטלו הקרבנות בטל גם המנורה ומהו לעולם. ורמב\"ן מביא פירש\"י ומדרש ומקשה זה, ומתרץ שהוא מרמז על נרות חנוכה<sup data-n=\"925\">2</sup> שהי' הנס ג\"כ ע\"י כהנים והוא זכר לנרות המקדש. אך הוא דוחק דמשמע שהנרות שהיו בבהמק\"ד הם לעולם, ורבינו ז\"ל תירץ תירוץ אחר<sup data-n=\"926\">3</sup>.\n<b>והנה</b> צ\"ל תחילה מנורה דזכרי' דכתי' ראיתי והנה מנורת זהב כו' ויאמר אלי מה אתה רואה ויאמר זה דבר ה' אל זרובבל<sup data-n=\"927\">4</sup>, וצ\"ל מה שייך זה אל זה דבר ה', שהרי קאמר שם ראיתי והנה מנורת זהב כולה וגולה על ראשה ושבעה נרותי' יוצאים ממנה ומצייר שם כל המנורה ומה שייך זה אל זה דבר ה' כו'. והענין הוא שיומשך זה בדבר ה', דכל הנביאים נתנבאו בכה וכמ\"ש כה אמר ה' ומשה נתנבא בזה כמ\"ש זה הדבר, וממשיכים זה לדבר ה'.\n<b>והענין</b> דהנה כתי' בצלמינו כדמותינו<sup data-n=\"928\">5</sup>, כדמותינו הוא כמו שרואין במראה שקורין בל\"א שפיגול הנה אנו רואין רק הדמות כי מהות הדבר אין שם כלל כ\"א כשעומד איזה דבר כנגד המראה נצטייר אותו דבר שם, ועי\"ז הוא רואה אותו, ה\"ז דמות הדבר ההוא, ולכן כתי' גבי נביאים במראה אליו אתודע בחלום אדבר בו, הגם",[["924","1","<b>וידבר ה' . . בהעלותך</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב מהמאמר הנדפס לעיל ע' תיז ואילך. וראה בהנסמן שם בתחילת המאמר."],["925","2","<b>ורמב\"ן מביא . . ומתרץ שהוא מרמז על נרות חנוכה</b>: הובא ונת' באוה\"ת בהעלותך ע' שכה. שנד. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201522\" data-slug=\"likkutei-sichot\" data-id=\"1300201522\">לקו\"ש ח\"כ ע' 509</a>. סה\"ש תשמ\"ט ח\"ב ע' 523. תש\"נ ח\"א ע' 205. תנש\"א ח\"א ע' 196 ואילך. ועוד."],["926","3","<b>אך הוא דוחק . . ורבינו ז\"ל תירץ תירוץ אחר</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תקסא. וראה גם מאמרי אדהאמ\"צ במדבר ח\"ג ר\"ע תתקז. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830022\" data-slug=\"or-hatorah-hb\" data-id=\"8158830022\">אוה\"ת בהעלותך</a> בהוספות (הוצאת תשנ\"ז) ע' 22. 24. וראה הביאור בזה לעיל ע' תלב-ג."],["927","4","<b>דכתי' ראיתי והנה מנורת זהב כו' ויאמר אלי מה אתה רואה ויאמר זה דבר ה' אל זרובבל</b>: ז\"ל הפסוק (זכרי' ד, ב-ו): ויאמר אלי מה אתה רואה ואומר ראיתי והנה מנורת זהב וגו', ואען ואומר גו' מה אלה אדוני וגו', ויאמר אלי לאמר זה דבר הוי' אל זרובבל."],["928","5","<b>והענין דהנה כתיב בצלמינו כדמותינו</b>: בהבא לקמן ראה בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370153\" data-slug=\"torah-or\" data-id=\"3901370153\">תו\"א מקץ לג, א</a>-ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380909\" data-slug=\"likkutei-torah\" data-id=\"4001380909\">לקו\"ת נצבים מז, ג</a>. דרושים לשמע\"צ צב, סע\"ב. שה\"ש כח, ב. סה\"מ תרל\"ב ח\"א ע' פא. וע' צט."]]],[2002180304,"שיש כאן גם כח המדבר מ\"מ הוא רק בחלום כמו מראה שרואין אותו דבר בכל פרטיו מ\"מ הוא רק דמות, אבל בצלמינו הוא מהות הדבר והוא אספקלרייא המאירה שרואין המהות ולכן נא' גבי משה במראה ולא בחידות (הגם שהוא ג\"כ מראה אך הוא אספה\"מ כנ\"ל) ותמונת ה' יביט שרואה המהות.\n<b>אך</b> צ\"ל דהנה המשל למטה אינו מכוון, דהנה ראיית העין הוא, שהעין הוא נקודה עגולה וכל צדדיו הם בהירים ואחורי הנקודה הוא עצם חשוך וכשרואין איזה דבר היינו שאותו דבר נצטייר בהעין<sup data-n=\"929\">6</sup> ועי\"ז הוא רואה וג\"ז צ\"ל ע\"י כמה לבושים, ה\"ז ג\"כ רק דמות, דאם נא' שהעין הוא רואה מהות הדבר ואספשא\"מ אינו רואה רק הדמות<sup data-n=\"930\">7</sup>, אך מאחר שהעין ג\"כ רואה רק הדמות מה ההפרש, דהנה מה שרואין במראה הוא מפני שהוא מצופה בכסף דק שאם לא הי' מצופה לא הי' רואה אותו כ\"א כשהי' עומד מעבר הזכוכית ה\"ז אספה\"מ, אבל כשעומד לפני הזכוכית לא יראה וכמו\"כ בהעין ג\"כ. והענין דהנה באספשא\"מ אינו רואה המהות כלל כ\"א הדמות, אבל באספה\"מ ה\"ה רואה המהות אלא שאינו יכול לראות כ\"א בהעין היינו כלי הבטה, ואין זה שייך לזה כלל שהרי אינו פועל שינוי באותו דבר, ובאמת אי' שנבואה הוא כמו ראיות העין<sup data-n=\"931\">8</sup>, לא ראיות השכל דזהו שמיעה, ואינו דומה שמיעה לראיה, דבראיה יש כוחות נעלים, וזהו שרואה המהות רק שהנבראים צריכים לקבל זה ע\"י כלי הבטה.\n<b>והנה</b> למעלה הוא יחו\"ת ויחו\"ע, יחו\"ע הוא איך שכולא קמי' כלא חשיב והוא ביטול אמיתי ביטול במציאות, ויחו\"ת הוא ביטול היש לאין הרי הוא יש אלא שהוא בטל לאין, וכמו שמים הרי יש כח האלקי השופע חיות בשמים וה\"ה בטל לבחי' זו מ\"מ הוא יש, וכמו שיש שמים גשמים כמו\"כ יש שמים רוחנים, דשמים הוא אש ומים שהם מדות. וע\"ז נא' לך ה' הגדולה והגבורה כו' שהוא ביטול אמיתי, ואח\"כ כתי' לך ה' הממלכה וצ\"ל מהו לך פ\"ב, וגם מהו הממלכה והול\"ל לך ה' המלוכה<sup data-n=\"932\">9</sup>. והענין דהנה מדת המל' אינו כמו כל המדות שכל המדות הם השפעה בקירוב, ומדת המל' הוא השפעה בריחוק<sup data-n=\"933\">10</sup>, ויש השפעה בקירוב ג\"כ, ואיך אפשר להיות שניהם התנשאות וגם ביטול, וזהו שאמר שההתנשאות הוא רק לגבי נבראים אבל לגבי א\"ס הוא בטל וכמו גדול שאמרו גדול ה' ומהולל מאד בעיר אלקינו, אימתי הוא גדול כשהוא בעיר אלקינו, מלך בלא מטרוניתא לאו איהו מלך ולאו איהו גדול איקרי, הרי שהוא גדול לגבי למטה אבל לגבי למעלה הוא בטל כמו\"כ מדת",[["929","6","<b>דהנה ראיית העין . . שאותו דבר נצטייר בהעין</b>: ראה המשך וככה תרל\"ז ע' פז. וע' קטז ואילך. סה\"מ תר\"ם ח\"א ע' שמג. וש\"נ."],["930","7","<b>רק הדמות</b>: אוצ\"ל: רק הדמות ניחא."],["931","8","<b>ובאמת אי' שנבואה הוא כמו ראיות העין</b>: ראה המשך וככה תרל\"ז שם ע' פד ואילך."],["932","9","<b>מהו הממלכה והול\"ל . . המלוכה</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600717\" data-slug=\"or-hatorah-hb\" data-id=\"8316600717\">אוה\"ת נ\"ך (כרך א) ע' תשיז</a>."],["933","10","<b>מדת המל' אינו כמו כל המדות . . בקירוב . . בריחוק</b>: ראה סה\"מ תר\"ל ע' קעו ואילך. קפב ואילך."]]],[2002180305,"המל'. ומ\"ש הממלכה הוא כמ\"ש ואתם תהיו לי ממלכת כהנים וגוי קדוש שהכהנים ע\"י שמברכים את ישראל הם ממליכים אותם והכהנים אינם מלכים רק ממליכים מלכים, דהנה ב\"ו כשהוא ממליך מלך הרי המלך הוא מלך אבל הממליך אינו מלך, אבל למעלה הממליך מלכים ולו המלוכה, וזהו לך ה' הממלכה שהממלכה בטל לאלקות, ויחו\"ת הוא שיש מציאות היש אלא שהוא בטל להאין.\n<b>וזהו</b> זה דבר ה' אל זרובבל שיאיר בחי' זה בדבר ה' וכמו לע\"ל הנה אלקינו זה וכמ\"ש ונגלה כבוד ה' וראו כל בשר יחדיו כי פי ה' דיבר דפי ה' כמו שהוא למעלה יאיר למטה, וזהו זה דבר ה' שיאיר בחי' זה בדבר ה'. וזהו שאמרז\"ל נביאים כתובים עתידים להיבטל וה' חומשי תורה אינם עתידים להיבטל, דנביאים וכתובים הם בחי' כה ולכן בטלים פי' ע\"ד שרגא בטיהרא<sup data-n=\"934\">11</sup> מאי אהני אבל ה' חומשי תורה הוא בחי' זה אינם עתידים להיבטל, וזהו זה דבר ה' אל זרובבל<sup data-n=\"935\">12</sup> שהוא ב' תיבות אל זרוע בבל, דכוונת הזריעה הוא בשביל הצמיחה, וזהו זרוע בבל שנזרעו בבבל, ולכן נק' הנשיא זרובבל ע\"ש המאורע, והצמיחה הוא שיאיר בחי' זה בדבר ה'.\n<b>והנה</b> בחי' זו ממשיכים כהנים כמ\"ש ואתה כהן לעולם על דברתי מלכי צדק והול\"ל על דברת, והענין שהוא דברת יו\"ד שממשיכים יו\"ד שהוא חכ' אבא מקננא באצי' ששם ביטול אמיתי, בדבר ה' שהוא בחי' ים, כלת משה, שיש במל'.\n<b>וזהו</b> בהעלותך את הנרות אל מול פני המנורה יאירו שבעת הנרות, מנורה הוא כללות נש\"י והשבעה נרות הם ז' פרטים בעבודה<sup data-n=\"936\">13</sup>, יש שעבודתם באהבה שהוא מצד החסד, ויש מצד הגבורה והוא יראה, ויש מארי תורה והוא מדת הת\"ת שמ\"ת הי' בחודש השלישי באלף השלישי וזהו שארז\"ל והת\"ת זו מ\"ת, ויש שעבודתם בנצח שהוא הנצחון שיהי' סור מרע ועשה טוב, דהנה אהוי\"ר באים מצד ההתבוננות וא\"א להיות כל היום בהתבוננות ונשאר הסכם חזק<sup data-n=\"937\">14</sup> אצלו על סו\"מ וע\"ט, וזה ברוב נש\"י, ויש שעבודתם בהוד שמי שהוא בעל שכל קטן וא\"י להעמיק בהתבוננות ה\"ה מודה שהוא כן, ויש שעבודתם בהתקשרות והוא מדרי' גבוה עבודת הצדיקים וכמ\"ש הקשורים ליעקב<sup data-n=\"938\">15</sup> וכתי' יעקב חבל נחלתו כמו חבל<sup data-n=\"939\">16</sup> כשקושרין ראש א' למעלה וראש הב' למטה כשמנענעים הקצה התחתון מתנענע הקצה העליון ג\"כ, כך הנשמה כתי' כי",[["934","11","<b>בטלים פי' ע\"ד שרגא בטיהרא</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370409\" data-slug=\"torah-or\" data-id=\"3901370409\">תו\"א מג\"א צ, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370414\" data-slug=\"torah-or\" data-id=\"3901370414\">צב, א</a> ואילך. ועוד."],["935","12","<b>וזהו זה דבר ה' אל זרובבל</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380428\" data-slug=\"likkutei-torah\" data-id=\"4001380428\">לקו\"ת בהעלותך כט, ג</a>."],["936","13","<b>וזהו בהעלותך את הנרות . . ז' פרטים בעבודה</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380428\" data-slug=\"likkutei-torah\" data-id=\"4001380428\">לקו\"ת בהעלותך שם כט, ג</a>. [ובהנסמן בהמ\"מ לשם]."],["937","14","<b>בנצח שהוא הנצחון . . הסכם חזק</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380165\" data-slug=\"likkutei-torah\" data-id=\"4001380165\">לקו\"ת תזריע כא, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380686\" data-slug=\"likkutei-torah\" data-id=\"4001380686\">מסעי צ, ג</a> ואילך. ובכ\"מ."],["938","15","<b>בהתקשרות . . מדרי' גבוה עבודת הצדיקים וכמ\"ש הקשורים ליעקב</b>: ראה בארוכה שערי תשובה לאדהאמ\"צ ח\"א נז, א ואילך."],["939","16","<b>וכתי' יעקב חבל נחלתו כמו חבל</b>: ראה אגה\"ת רפ\"ה (צה, סע\"א). פ\"ו (צו, א). ובכ\"מ."]]],[2002180306,"חלק ה' עמו יעקב חבל נחלתו, ויש שעבודתם בהתנשאות כמו ויגבה לבו בדרכי ה', ואהרן מדליק הנרות שיהי' מקרב איש ולב עמוק בכליון ורשפי אש בל\"א מיט א ברען.\n<b>והענין</b> דהנה יש אהבה דאהרן ואהבה דאברהם<sup data-n=\"940\">17</sup>, אהבה דאברהם היא אהבת עולם ואהבה דאהרן היא אה\"ר, וצ\"ל האיך אהבה דאהרן למעלה מאהבה דאברהם, והלא כתי' אחד הי' אברהם ותורה היא נצחיות ואיך שייך שיהי' אהרן למעלה ממנו במדריגה, וגם אמרז\"ל יכול יהא חותמין בכולן ת\"ל והי' ברכה בך חותמין<sup data-n=\"941\">18</sup> ואין חותמין בכולן מגן אברהם [והכל הולך אחר החיתום] והוא גמר הענין, ואהרן הי' אחר אברהם איך שייך שיהי' למעלה ממנו.\n<b>והענין</b> דהנה אה\"ע הוא מ\"ש ואהבת את ה' אלקיך, דהנה שרש אהבה אבה ל' רצון, והנה רצון הוא פנימיות המדות, ויכול להפוך המדה היפוך טבעה, דהנה כשבא לאדם איזה דבר שצריך להתענג ממנה מ\"מ כשברצונו שלא להתענג מזה אינו מתענג, וכן להיפך כשבא לו דבר שצריך לצער מזה וכשברצונו שלא לצער מזה אינו מצער אדרבה מקבל עונג, וכמו ר\"י החסיד שהי' מתענה בכ\"י וגם בשבת הגם שמצוה לענגו מ\"מ זה הי' העונג שלו, וכן ת\"ח שרי להתענות בשבת מפני שנפשו עגומה עליו זהו העונג שלו מה שמתענה, הרי שהעיקר הוא הרצון. וזהו שמצד הרצון אפשר לבוא לאהבה. והוא ע\"י ההתבוננות בפסוק ראשון דק\"ש שמע כו' אחד, ח' הוא ז' רקיעים וארץ, וד' הוא ד' רוחות העולם כולם בטלים לאלקות, דכמו שיש ו\"ק למטה כמו\"כ יש למעלה ג\"כ דכתי' צפון וימין אתה בראתם, מזרח הוא קדמה מזרחה, מערב נק' אחור (וכ\"ה באמ\"ב פה\"ש פ\"ג<sup data-n=\"942\">19</sup>) וזהו שהמקום ומקור המקום בטל לאלקות (ע' באמ\"ב פה\"ש פ\"א). ונוכל להבין זה מזמן (צ\"ע מה ראי' מזמן יותר ממקום<sup data-n=\"943\">20</sup>) דהנה גבול לגבי בלתי בע\"ג אינו בערך דמה שאדם יכול לספור אפי' נו\"ן אלפים יובלות, דהנה שית אלפי שני הוא שבוע, ויש שנה, שמיטה, יובל, נו\"ן אלפי', והנה א' לגבי מספר גדול ה\"ז בערך אבל גבול לגבי בלתי בע\"ג אין לו ערך כלל, וכמו\"כ מקום לגבי למעלה ממקום ג\"כ אין ערוך כלל.\n<b>וכשיתבונן</b> בזה יהי' לו אהבה ותשוקה לאלקות וכמ\"ש מי לי בשמים ועמך לא חפצתי בארץ, שמים הוא תענוגים רוחניים וארץ תענוגים גשמיים<sup data-n=\"944\">21</sup> (צ\"ל למה לא פי' כמו בכ\"ד ארץ געה\"ת), תענוגים רוחניים הוא תענוג שבג\"ע דכל",[["940","17","<b>והענין דהנה יש אהבה דאהרן ואהבה דאברהם</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380428\" data-slug=\"likkutei-torah\" data-id=\"4001380428\">לקו\"ת בהעלותך שם כט, סע\"ג</a> ואילך."],["941","18","<b>אמרז\"ל . . ת\"ל והי' ברכה בך חותמין</b>: ראה בארוכה ע\"ז לעיל ח\"א ע' א ואילך. וע' קעה ואילך."],["942","19","<b>(וכ\"ה באמ\"ב פה\"ש פ\"ג)</b>: ראה אמ\"ב פתח השער פ\"ג (א, ד): ומוכח זה מלשון הפסוקים שבכל מקום כו' נק' המערב אחור. וראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' קמב."],["943","20","<b>ונוכל להבין זה מזמן (צ\"ע מה ראי' מזמן יותר ממקום)</b>: קאי עמ\"ש לעיל בהמאמר ס\"ע תכג: ויותר אנו רואים זה בזמן [כדלקמן בפנים]."],["944","21","<b>וארץ תענוגים גשמים (צ\"ל למה לא פי' כמו בכ\"ד ארץ געה\"ת)</b>: כ\"ה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380430\" data-slug=\"likkutei-torah\" data-id=\"4001380430\">לקו\"ת בהעלותך שם ל, א</a>: ועמך לא חפצתי בארץ שהם תענוגים גשמיים. וכ\"ה גם בהמאמר לעיל ע' תכד. ועד\"ז הובא בכ\"מ ראה לעיל ע' תס. לקמן ד\"ה כי יש אדם שעמלו בחכ' (הנחת כ\"ק אדמו\"ר מהורש\"ב). וכן משמע ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370166\" data-slug=\"torah-or\" data-id=\"3901370166\">תו\"א מקץ לו, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370214\" data-slug=\"torah-or\" data-id=\"3901370214\">ויחי מז, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380381\" data-slug=\"likkutei-torah\" data-id=\"4001380381\">לקו\"ת במדבר יח, סע\"ב</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310048\" data-slug=\"tanya\" data-id=\"3401310048\">תניא פמ\"ג (סב, א</a>): שלא תתלבש בשום דבר הנאה ותענוג גשמי או רוחני כו' בלתי לה' לבדו מקור החיים של כל התענוגים כו' וכמ\"ש מי לי בשמים ועמך לא חפצתי בארץ.\nאך בכ\"מ הובא עוד פי' ארץ קאי על ג\"ע התחתון, ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת ראה כה, א</a>: ועמך לא חפצתי בארץ כו' שמים וארץ ג\"ע עליון ותחתון. דרמ\"צ קלח, סע\"א. סה\"מ תרכ\"ז ע' קמח. תרכ\"ט ע' עב. קכט. רו. ערה. תרל\"ג ח\"א ע' רמו. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370037\" data-slug=\"torah-or\" data-id=\"3901370037\">תו\"א נח ט, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540527\" data-slug=\"torat-chaim\" data-id=\"2300540527\">לקו\"ת חוקת נו, ב</a>. תו\"ח שמות (הוצאת תשס\"ג) ח\"א עז, א. מאמרי אדהאמ\"צ קונטרסים ע' תקצג. [וראה לקמן ד\"ה ובראשי חדשיכם — הנחת כ\"ק אדמו\"ר מהורש\"ב].\nאך בכ\"מ הובא עוד פי' ארץ קאי על ג\"ע התחתון, ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת ראה כה, א</a>: ועמך לא חפצתי בארץ כו' שמים וארץ ג\"ע עליון ותחתון. דרמ\"צ קלח, סע\"א. סה\"מ תרכ\"ז ע' קמח. תרכ\"ט ע' עב. קכט. רו. ערה. תרל\"ג ח\"א ע' רמו. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370037\" data-slug=\"torah-or\" data-id=\"3901370037\">תו\"א נח ט, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540527\" data-slug=\"torat-chaim\" data-id=\"2300540527\">לקו\"ת חוקת נו, ב</a>. תו\"ח שמות (הוצאת תשס\"ג) ח\"א עז, א. מאמרי אדהאמ\"צ קונטרסים ע' תקצג. [וראה לקמן ד\"ה ובראשי חדשיכם — הנחת כ\"ק אדמו\"ר מהורש\"ב]."]]],[2002180307,"השגה הוא הגבלה, כ\"א א\"ס בלתי בע\"ג, וזהו אה\"ע אהבה הבאה מהתבוננות העולם, וזהו\"ע אברהם<sup data-n=\"945\">22</sup> דכתי' בו הלוך ונסוע הנגבה ואי' בזהר חסד שירותא דעלמא עילאה עמיקא וטמירא עד א\"ס. דהנה כתי' כי אמרתי עולם חסד יבנה, עפ\"י פשוט הפי' דבנין העולם הוא ע\"י החסד, ועוי\"ל<sup data-n=\"946\">23</sup> כשצריכים לבנות העולם צריכים לבנות מדת החסד, וזהו יבנה אותיות בינה, דחסד נמשך מבינה, דחסד הוא סדר זמנים, ובינה היא למעלה מסדר זמנים<sup data-n=\"947\">24</sup> וע\"ז אמרז\"ל מי שברא יומא ברא פרנסתו<sup data-n=\"948\">25</sup>. וזהו תשובה קדמה לעולם דתשובה הוא תשוב ה\"א ליו\"ד והוא בינה לכן קדמה לעולם, ובינה ממנו נמשך מדת החסד שהוא יומא דאזיל עם כולא יומין, וזהו שההמשכה היא ע\"י מדת החסד, וכמו\"כ ההעלאה הוא ג\"כ ע\"י מדת החסד וזהו\"ע אהבה דאברהם ההעלאה ממקום וזמן לא\"ס שלמעלה ממקום וזמן.\n<b>ואהבה</b> דאהרן הוא שיומשך מא\"ס שלמעלה ממקום וזמן במקום<sup data-n=\"949\">26</sup> וזמן. ואיך אפ\"ל שלמעלה ממקום יהי' במקום וזמן, אך הנה כבר הי' כן דהנה ארון הי' אמתים וחצי ארכו ואמה וחצי קומתו ואמרז\"ל מקום ארון אינו מן המדה שהי' עשר אמות מכאן ועשר אמות מכאן והוא מפני שהאיר מא\"ס שלמעלה ממקום וזמן במקום וזמן, וכן הראה הקב\"ה לאדה\"ר דור דור ודורשיו דור דור ומנהיגיו הרי הראה לו ששת אלפי' שנין במעט זמן והוא שהאיר מאוא\"ס שלמעלה ממקום וזמן במקום וזמן, וכן תורה<sup data-n=\"950\">27</sup>.",[["945","22","<b>וזהו אה\"ע . . וזהו\"ע אברהם</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380430\" data-slug=\"likkutei-torah\" data-id=\"4001380430\">לקו\"ת בהעלותך שם ל, א</a>."],["946","23","<b>עולם חסד יבנה עפ\"י פשוט הפי' . . ועוי\"ל</b>: ראה יהל אור להצ\"צ ע' שיד. סה\"מ תרכ\"ז ע' קמ. תרכ\"ט ע' עג. תרל\"ד ע' נד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381028\" data-slug=\"likkutei-torah\" data-id=\"4001381028\">לקו\"ת האזינו עו, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381176\" data-slug=\"likkutei-torah\" data-id=\"4001381176\">שה\"ש יא, ד</a>. ועוד."],["947","24","<b>סדר זמנים . . למעלה מסדר זמנים</b>: ראה בארוכה לעיל ע' שצו-ז. וש\"נ."],["948","25","<b>וע\"ז אמרז\"ל מי שברא יומא ברא פרנסתו</b>: ע\"פ מכילתא בשלח עה\"פ דבר יום ביומו (טז, ד). תנחומא שם פיסקא כ. ועוד.."],["949","26","<b>ארון הי' אמתים וחצי ארכו . . מקום ארון אינו מן המדה . . שלמעלה ממקום . . במקום</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830257\" data-slug=\"or-hatorah-hb\" data-id=\"8158830257\">אוה\"ת נשא ע' רנז</a>-ח. סה\"מ תרמ\"ו-נו\"ן ע' עדר. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111326\" data-slug=\"likkutei-sichot\" data-id=\"1300111326\">לקו\"ש חי\"א ע' 319</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151186\" data-slug=\"likkutei-sichot\" data-id=\"1300151186\">חט\"ו ע' 186</a>. ועוד."],["950","27","<b>וכן תורה</b>: ע\"כ נמצא בגוכי\"ק. וראה המשך הענין לעיל בהמאמר ס\"ע תכה ואילך."]]],[2002180308,"<h3>ובראשי חדשיכם (ש\"פ קרח)</h3>\n<b>ש\"פ קרח ט\"ל לפ\"ק.</b>\n<b>ובראשי</b> חדשיכם<sup data-n=\"951\">1</sup> תקריבו עולה לה' כו' ושעיר עזים אחד לחטאת לה', ואמרו בגמ' מה נשתנה שעיר זה שנא' בו חטאת לה', אלא אמר הקב\"ה שעיר זה תהא עלי כפרה על שמעטתי את הירח. וצ\"ל מה שייך חטא ועון למעלה שצריכים לחטאת. הענין דהנה יש ב' מיני קרבנות עולות וחטאות, עולות ע\"פ רוב הם מכבשים כמ\"ש עולה תמיד את הכבש גו', וכן בשבת שני כבשים, וחטאות ע\"פ רוב הם משעיר עזים כמ\"ש שעיר עזים לחטאת לה', לבד חטאת יוהכ\"פ פר, וחטאת כהן המשיח פר, ויחיד לפעמים הי' כבשה.\n<b>והענין</b> דהנה כתי' את קרבני לחמי<sup data-n=\"952\">2</sup> לאשי, שהקרבן הוא לחם לאשי שהם מלאכים וכמו שרפים עומדים שנק' שרפים ע\"ש שנתוקדו ברשפי אש<sup data-n=\"953\">3</sup> נק' שרפים או אישים שהם מדרי' א', והקרבן הוא לחם לאשי. וצ\"ל מה שייך לחם למעלה, דמשה כשהי' בהר לחם לא אכל מים לא שתה ואמרז\"ל אזלת לקרתא עבדית כנמוסי' וא\"כ מלאכים כ\"ש שאינו שייך בהם אכילה. וכן מ\"ש במדר' רעייתי פרנסתי ישראל מפרנסי' לאביהם שבשמים מה שייך זה למעלה.\n<b>והענין</b> דהנה צ\"ל תחילה ענין צמחים<sup data-n=\"954\">4</sup> שרשם למעלה, דהנה אמרז\"ל בשעה שא' הקב\"ה לאילנות למינהו נשאו דשאים ק\"ו בעצמם<sup data-n=\"955\">5</sup> מה אלו שאין דרכם לצאת בערבובי' א\"ל הכתוב למינהו אנו שדרכנו לצאת בערבובי' עאכו\"כ. וצ\"ל מה שייך שצומח ישא ק\"ו והלא אין לו רק נפש הצומחת, ובע\"ח נוסף ע\"ז נפש החיונית ומדבר נפש המדברת, אבל הצומח אין לו נפש המדברת ואיך שייך שישא ק\"ו, ולזה צריכים שכל ג\"כ. והענין דהנה אמרז\"ל אין לך עשב למטה שאין לו מזל למעלה המכה בו ואומר לו גדל, שפועל בו צמיחה מקטנות לגדלות. וזהו מצמיח חציר לבהמה ועשב לעבודת האדם, חציר הוא עשב שנגדל בכ\"י ונפסד מיד, ועשב הוא מתקיים, כמו\"כ מלאכים כללות המלאכים נק' דשא כמ\"ש תדשא הארץ דשא ובזה יש פרטים חציר ועשב, וזהו יוצר משרתים ואשר משרתיו, יוצר משרתיו הם מלאכים שנק' חציר שהם נבראים בכ\"י ונכללים בביטול לאלקות, ואשר משרתיו הם מלאכים שנק' עשב שהם מתקיימים.",[["951","1","<b>ובראשי חדשיכם</b>: הנחת אדמו\"ר מהורש\"ב מהמאמר שנדפס לעיל ע' תלו ואילך. [וראה בהנסמן שם בתחילת המאמר]. וראה לקמן ד\"ה ושעיר עזים שהוא המשך למאמר זה."],["952","2","<b>והענין דהנה כתי' את קרבני לחמי</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380624\" data-slug=\"likkutei-torah\" data-id=\"4001380624\">לקו\"ת פנחס עו, א</a>. סידור עם דא\"ח לו, א. אוה\"ת פנחס ע' א'עב ואילך. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121018\" data-slug=\"likkutei-sichot\" data-id=\"1300121018\">לקו\"ש חי\"ב ע' 18</a> [ובהמ\"מ שם]."],["953","3","<b>שנק' שרפים ע\"ש שנתוקדו ברשפי אש</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380631\" data-slug=\"likkutei-torah\" data-id=\"4001380631\">לקו\"ת פנחס שם עז, ד</a>. סה\"מ תרכ\"ז ע' קלה. תרכ\"ט ע' סט. ועוד."],["954","4","<b>והענין דהנה צ\"ל תחלה ענין צמחים</b>: בהבא לקמן ראה אוה\"ת בראשית לג, סע\"ב ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370129\" data-slug=\"torah-or\" data-id=\"3901370129\">תו\"א וישב כז, סע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380230\" data-slug=\"likkutei-torah\" data-id=\"4001380230\">לקו\"ת אמור לו, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380637\" data-slug=\"likkutei-torah\" data-id=\"4001380637\">פנחס עט, סע\"ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381030\" data-slug=\"likkutei-torah\" data-id=\"4001381030\">האזינו עו, ד</a>. ועוד."],["955","5","<b>דהנה אמרז\"ל . . נשאו דשאים ק\"ו בעצמם</b>: ראה בכ\"ז סה\"מ תרכ\"ט ע' קנח. תרל\"ב ח\"א ע' רעג."]]],[2002180309,"<b>וזהו</b> ועשב לעבודת האדם, דהנה אמרז\"ל מט\"ט קושר כתרים לקונו מתפלותיהם של ישראל, וצ\"ל והלא התפלה הוא מגושם ואיך שייך שיהי' כתר לקונו. ואי' בזהר דגפיף לון ומנשק לון היינו שמלאכים מזככים אותם<sup data-n=\"956\">6</sup> דדיבור שלהם הוא בערך מח' שלנו<sup data-n=\"957\">7</sup> ומח' שלהם הוא בדקות יותר, וגבוה מעל גבוה עד מט\"ט קושר מזה כתר לקונו, שיהי' יהי רצון שיומשך רצון חדש לרפאות החולים ולברך השנים וכמו ויזרע יצחק בארץ ההיא וימצא מאה שערים ויברכהו הוי', דמצד שם אלקים הוא שיהי' הצמיחה לפ\"ע הזריעה, אבל שיהי' שלא לפ\"ע כלל זהו מצד שם הוי', והוא ע\"י התפלה, וזהו לעבודת האדם. ומצמיח חציר לבהמה הוא בהמה רבא דאכיל אלף טורין. וזהו מקור הצומח למעלה ששופע חיות בהצומח למטה ופועל בו שיהי' צמיחה מקטנות לגדלות, דגוף הצומח הוא מסוכ\"ע, דאפי' בריבוי מדרי' השתל' א\"א שיהי' גוף הגשמי כ\"א החיות ההגדלה מקטנות לגדלות. וזהו נשאו דשאים ק\"ו בעצמן דקאי על מלאכים שרשי הצומח ובהם שייך דיבור ושכל. וכשם שצומח יש לו שרש למעלה כמו\"כ בע\"ח ומדבר, דהנה אמרז\"ל ג' שותפים באדם<sup data-n=\"958\">8</sup> או\"א והקב\"ה נותן בו נשמה והוא חלק אלוקה ממעל<sup data-n=\"959\">9</sup> חלק הוי' עמו, והוא ג\"כ פועל רק הצמיחה מקטנות לגדלות. אבל גוף הדשא הוא מא\"ס הסוכ\"ע<sup data-n=\"960\">10</sup>. ושרש כל הנבראים הם מד' חיות המרכבה<sup data-n=\"961\">11</sup> פני שור הוא מקור כל הבהמות כו', והאדם הוא מפני אדם שבמרכבה או מאדם שעל הכסא, וזהו ע\"י שמקריבי' בהמה ע\"ג מזבח ונכללת בשרשה שהוא מעולם התהו שקדם לעולם התיקון, דהאדם הוא רק מג' קוין ושרש הבהמה למעלה יותר לכן מכפרת כו'.\n<b>והנה</b> ההקרבה הוא ע\"י כהן איש החסד<sup data-n=\"962\">12</sup> ימין מקרבת שמקרב את הניצוץ לאלקות, וסדר ההקרבה אי' בזהר ארי' דאכיל קורבנין<sup data-n=\"963\">13</sup> ונתעלה בקו השמאל, וזה בעשי' ומעורר מרכבה דיצי' ואח\"כ מרכבה דבריאה, וכשם שיש חיוון תתאין כמו\"כ יש חיוון עילאין<sup data-n=\"964\">14</sup> דאבות הן המרכבה, והכסא הוא בינה, ואדם שעל הכסא מפרשי'",[["956","6","<b>אמרז\"ל מט\"ט קושר כתרים . . שמלאכים מזככים אותם</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">תו\"א מקץ מב, ב</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940108\" data-slug=\"or-hatorah-hb\" data-id=\"8159940108\">אוה\"ת תזריע (כרך ב) ס\"ע תקכד</a>-ה. סה\"מ תרל\"ה ח\"א ע' רז ואילך. ועוד."],["957","7","<b>דדיבור שלהם הוא בערך מח' שלנו</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380305\" data-slug=\"likkutei-torah\" data-id=\"4001380305\">לקו\"ת</a> הוספות לס' ויקרא נג, רע\"ב. סידור עם דא\"ח רעו, א. ובכ\"מ."],["958","8","<b>וכשם שצומח . . כמו\"כ בע\"ח ומדבר . . ג' שותפים באדם</b>: בהבא לקמן ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381243\" data-slug=\"likkutei-torah\" data-id=\"4001381243\">לקו\"ת שה\"ש כח, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381251\" data-slug=\"likkutei-torah\" data-id=\"4001381251\">ל, ג</a> ואילך. אוה\"ת משפטים (כרך ח) ע' ג'יח ואילך."],["959","9","<b>נשמה . . חלק אלוקה ממעל</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>. ועוד."],["960","10","<b>גוף הדשא הוא מא\"ס הסוכ\"ע</b>: ראה אוה\"ת דרושים לשמע\"צ ע' א'תשעט ואילך. ובכ\"מ."],["961","11","<b>ושרש כל הנבראים הם מד' חיות המרכבה</b>: ראה תניא אגה\"ק סכ\"ח (קמז, ב). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380422\" data-slug=\"likkutei-torah\" data-id=\"4001380422\">לקו\"ת נשא כח, ג</a>. אוה\"ת משפטים שם."],["962","12","<b>והנה ההקרבה הוא ע\"י כהן איש החסד</b>: בהבא לקמן ראה גם ביאוה\"ז להצ\"צ ח\"א ע' רמב ואילך."],["963","13","<b>וסדר ההקרבה . . ארי' דאכיל קורבנין</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380355\" data-slug=\"likkutei-torah\" data-id=\"4001380355\">לקו\"ת במדבר יא, ד</a>. ועוד."],["964","14","<b>וכשם שיש חיוון תתאין . . חיוון עילאין</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380171\" data-slug=\"likkutei-torah\" data-id=\"4001380171\">לקו\"ת תזריע כב, ד</a>. ביאוה\"ז לאדהאמ\"צ מב, ב. סידור עם דא\"ח סד, א."]]],[2002180310,"פרצוף אבא<sup data-n=\"965\">15</sup>, וזהו\"ע העלאת הקרבנות. והנה למעלה יש ג\"כ כהן והוא מיכאל כהנא רבא דאית חסד ואית חסד אית חסד דאיקרי חסד עולם חסד זוטא ואית חסד דאיקרי רב חסד<sup data-n=\"967\">16</sup> והוא אהרן כה\"ר, וזהו אית מלך לעילא<sup data-n=\"966\">17</sup> וכהן משמש תחותא ברזא דקדה\"ק, ואית מלך לתתא וכהן משמש תחותא ברזא דאור קדמאה, דרזא דקורבנא עולה עד רזא דא\"ס.\n<b>ועיקר</b> הקרבן הי' חלב ודם<sup data-n=\"968\">18</sup> ואי' בזהר חוור וסומק שהם חו\"ג והיינו בטול המדות לא\"ס דלאו מכא\"מ איהו כלל, וכמ\"ש לך הוי' הגדולה כו' שמדת הגדולה כו' טפל ובטל לך, ואח\"כ כי כל בשמים וארץ שיומשך ממקיף הכללי וכמ\"ש כל תשא עון, ופי' המגיד דכל הוא מקיף הכללי<sup data-n=\"969\">19</sup>. וזהו כי כל כו' שיומשך מקיף הכללי, וזהו\"ע העלאת הקרבנות, ועי\"ז נמשך אח\"כ שיהי' ריח נחוח להוי' ריח הוא העלאה דרזא דקורבנא עולה עד רזא דא\"ס, וניחוח הוא המשכה שיומשך שם הוי' יו\"ד צמצום ה' התפשטות, וכדי שיומשך למטה צ\"ל ו' המשכה מיו\"ד וה' אחרונה התפשטות.\n<b>וזהו</b> את קרבני לחמי לאשי, דהנה לחם הוא מחבר הנשמה עם הגוף<sup data-n=\"970\">20</sup>, דבלא לחם יחלש, וברבות הזמן אפשר שח\"ו יפרד הנשמה מהגוף, והלחם הוא מחבר הנשמה עם הגוף, וכמו\"כ למעלה כמה גופים תקינת לון חסד דרועא ימינא כו' וההוא נביעו איהו כנשמתא לגופא דאיהו חיים לגופא, ונק' אורות וכלים, והקרבן פועל שיהי' יחוד או\"כ, וכן מ\"ש ישראל מפרנסין לאביהם שבשמים, שמים הוא אש ומים מדות העליונות, ואביהם שבשמים הוא מוחין דז\"א, וכדי שיומשך ממוחין לז\"א זהו ישראל מפרנסין.\n<b>והנה</b> כמשנת\"ל ענין הקרבן למעלה, כמו\"כ יש קרבן בעבודה ג\"כ, והענין דהנה ההקרבה הוא להקריב את נה\"ב דשרשו ג\"כ מפני שור רק מפני אדם שבפני שור, הגם שנת\"ל דבהמה שרשה למעלה יותר מאדם שנשפלה למטה יותר, וזהו כלל כל שנשפל למטה יותר שרשו למעלה יותר<sup data-n=\"971\">21</sup>, וכמו אבן שבראש החומה נופל למרחוק",[["965","15","<b>ואדם שעל הכסא מפרשי' פרצוף אבא</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370354\" data-slug=\"torah-or\" data-id=\"3901370354\">תו\"א תרומה עט, ג</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316640321\" data-slug=\"or-hatorah-hb\" data-id=\"8316640321\">אוה\"ת שה\"ש (כרך א) ע' שכא</a> בשם הפרדס (ראה פרדס שער ערכי הכינויים פ\"א ערך אדם). ובכ\"מ."],["967","16","<b>דאית חסד ואית חסד . חסד עולם . . רב חסד</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370366\" data-slug=\"torah-or\" data-id=\"3901370366\">תו\"א תצוה פב, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380509\" data-slug=\"likkutei-torah\" data-id=\"4001380509\">לקו\"ת שלח מט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380537\" data-slug=\"likkutei-torah\" data-id=\"4001380537\">קרח נה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381252\" data-slug=\"likkutei-torah\" data-id=\"4001381252\">שה\"ש ל, ד</a>. ובכ\"מ."],["966","17","<b><a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550044\" data-slug=\"torat-chaim\" data-id=\"2300550044\">והנה למעלה יש ג</a>\"כ כהן . . מיכאל כהנא רבא . . אית מלך לעילא</b>: ראה בכ\"ז בארוכה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550045\" data-slug=\"torat-chaim\" data-id=\"2300550045\">תו\"ח יתרו</a> (הוצאת תשס\"ג) ח\"ב רסט, א ואילך. רעג, ג ואילך. וש\"נ."],["968","18","<b>ועיקר הקרבן הי' חלב ודם</b>: בהבא לקמן עד סוף המאמר ראה בארוכה סה\"מ תרכ\"ט ע' קכב ואילך. תר\"ל ע' שנא ואילך. תרס\"ד ע' רחצ ואילך. תרצ\"ז ע' 209 ואילך. ועוד."],["969","19","<b>וכמ\"ש כל תשא עון ופי' המגיד דכל הוא מקיף הכללי</b>: הובא (בשם הה\"מ) בסה\"מ תרכ\"ט ע' קכו. וש\"נ. וראה גם לקו\"ת דרושים לש\"ש סז, ד. סה\"מ תרכ\"ז ע' קעג. תרכ\"ט ע' לד. תרל\"ג ח\"ב ע' תקעא. תקעה."],["970","20","<b>וזהו את קרבני לחמי . . לחם הוא מחבר הנשמה עם הגוף</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380624\" data-slug=\"likkutei-torah\" data-id=\"4001380624\">לקו\"ת פנחס עו, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380859\" data-slug=\"likkutei-torah\" data-id=\"4001380859\">תצא לה, ג</a>. דרושים לשמע\"צ צב, ד."],["971","21","<b>וזהו כלל כל שנשפל למטה יותר שרשו למעלה יותר</b>: ראה בארוכה אוה\"ת וארא ע' קסב ואילך. וע' ריד. סה\"מ תרכ\"ט ע' צט. וש\"נ."]]],[2002180311,"וכל מה שנפל למרחוק יודעין שבהחומה הי' הוא בראש החומה. אך באמת הנה הבהמה שנמשכת אחרי תאוות הרי לא יש לה שכל, אבל אדם שיש לו שכל ומ\"מ נמשך אחר תאוות זרות הוא גרוע יותר א\"כ נפל למטה יותר, א\"כ ההעלאה הוא ג\"כ במדרי' היותר גבוה.\n<b>וכמו</b> שבקרבן העיקר הוא חלב ודם, וכמו\"כ בעבודה<sup data-n=\"972\">22</sup> הנה כתי' כמו חלב ודשן תשבע נפשי, דחלב הוא בא מתענוג [והוא] שיהי' לו תענוג באלקות וכמ\"ש מי לי בשמים ועמך לא חפצתי<sup data-n=\"973\">23</sup> בארץ, שמים הוא תענוגים רוחנים וארץ תענוגים<sup data-n=\"974\">24</sup>, לא חפצתי מפני שהוא עמך טפל ובטל לך וכמ\"ש כי עמך מקור חיים אפי' מקור חיים מקור התענוגי' הוא טפל ובטל לך כ\"ז לא חפצתי, דהנה יש רצון וחפץ<sup data-n=\"975\">25</sup>, רצון הוא חיצוניות, וכמו כופין אותו עד שיאמר רוצה אני שהוא רצון מעושה, וחפץ הוא פנימיות הרצון, וזהו לא חפצתי שפנימיות הרצון אינו בדברים אלו כ\"א בא\"ס עצומ\"ה. ודם הוא אהבה ברשפי אש לאלקות.\n<b>ועי\"ז</b> ממשיכים ריח נחוח להוי' ריח הוא העלאה, ונחוח הוא המשכה שיומשך שם הוי' בכאו\"א מישראל. הגם שנת\"ל דנשמה היא חלק הוי', אך הנה כתי' ויקרא הוי' הוי' שיש ב' שמות הוי'<sup data-n=\"976\">26</sup>, א' הוי' דממכ\"ע וכמאמר מה הנשמה ממלא את הגוף אף הקב\"ה ממלא את כל העולם, וכמו בנשמה הנה יש חילוק בין ראש ורגל כמו\"כ באלקות המחייה את העולמות יש בזה חילוקי מדריגות, ב' שם הוי' דלמעלה מסדר השתל' הוי' דסוכ\"ע. וזהו הוי' אלקינו הוי' אחד, הוי' אחד הוא הוי' דממכ\"ע ח' הוא ז' רקיעים וארץ, וד' הם ד' רוחות העולם, וא' הוא הארת סוכ\"ע בממכ\"ע, וזהו הוי' אחד הוא הוי' דממכ\"ע דההתבוננות הוא מהעולם. והוי' אלקינו הוא הוי' דסוכ\"ע דשוה ומשוה קטן וגדול<sup data-n=\"977\">27</sup> דבמדרי' זו לא יש חילוקים. וזהו אל תהי ברכת הדיוט קלה בעיניך, דמצד מדריגה זו שוה קטן וגדול. וזהו לבי ובשרי ירננו<sup data-n=\"978\">28</sup> לאל חי, שמצד בחי' אל חי אפי' ליבי ובשרי הגשמי ירננו. וזהו\"ע נחוח להוי', שיומשך שם הוי' דסוכ\"ע למטה. וזהו הוי' אלקינ\"ו דזה לא נמצא בשום שם כ\"א בשם אלקים<sup data-n=\"979\">29</sup>, דמצד צמצום דשם אלקים אפשר שגם שם הוי' דסוכ\"ע יאיר למטה. והנה הכח לזה",[["972","22","<b>וכמו שבקרבן העיקר הוא חלב ודם וכמו\"כ בעבודה</b>: בהבא לקמן ראה מאמרי אדה\"ז הקצרים ע' צב ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370137\" data-slug=\"torah-or\" data-id=\"3901370137\">תו\"א וישב כט, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381178\" data-slug=\"likkutei-torah\" data-id=\"4001381178\">לקו\"ת שה\"ש יב, ב</a>. ועוד."],["973","23","<b>וכמ\"ש מי לי בשמים ועמך לא חפצתי</b>: ראה גם דרמ\"צ קלח, א. [ובהנסמן בהע' שלאח\"ז]."],["974","24","<b>וארץ תענוגים</b>: כ\"ה בגוכי\"ק, וראה לעיל הנחת כ\"ק אדמו\"ר מהורש\"ב מד\"ה בהעלותך. וש\"נ."],["975","25","<b>דהנה יש רצון וחפץ</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381244\" data-slug=\"likkutei-torah\" data-id=\"4001381244\">לקו\"ת שה\"ש כח, רע\"ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381264\" data-slug=\"likkutei-torah\" data-id=\"4001381264\">לג, רע\"ד</a>."],["976","26","<b>כתי' ויקרא הוי' הוי' שיש ב' שמות הוי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380955\" data-slug=\"likkutei-torah\" data-id=\"4001380955\">לקו\"ת שה\"ש שם כט, סע\"א</a>. ובדרושים לר\"ה נט, סע\"א ואילך."],["977","27","<b>וזהו אל תהי ברכת הדיוט . . שוה קטן וגדול</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380779\" data-slug=\"likkutei-torah\" data-id=\"4001380779\">לקו\"ת שה\"ש שם כח, ד</a>. עקב טז, ב."],["978","28","<b>וזהו לבי ובשרי ירננו . . אפי' לבי ובשרי הגשמי</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380342\" data-slug=\"likkutei-torah\" data-id=\"4001380342\">לקו\"ת במדבר ח, ג</a> ואילך."],["979","29","<b>אלקינ\"ו דזה לא נמצא בשום שם כ\"א בשם אלקים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380932\" data-slug=\"likkutei-torah\" data-id=\"4001380932\">לקו\"ת נצבים נג, סע\"ב</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380611\" data-slug=\"likkutei-torah\" data-id=\"4001380611\">לקו\"ת בלק עג, ב</a>. אוה\"ת וארא ע' ריג. דברים (כרך ו) ע' ב'רסג."]]],[2002180312,"הי' במ\"ת וכמ\"ש עולת תמיד העשוי' בהר סיני דאמרז\"ל על כל דבור ודיבור פרחה נשמתן והחזירן בטל תחי', הנה מה שעל כל דבור פרחה נשמתן הוא העלאה והדיבור דאנכי הוא המשכה.\n<b>וזהו</b> שהעולה היא מכבשים<sup data-n=\"980\">30</sup> דהנה אי' במדרש דפרים אילים וכבשים הם נגד ג' אבות, פרים נגד אברהם וכמ\"ש ואל הבקר רץ אברהם, אילים נגד יצחק אילו של יצחק, כבשים נגד יעקב כמ\"ש ואת הכשבים הפריד יעקב, ולכן כבש קולו רחמים שהוא מדתו של יעקב, הגם שנת\"ל דהכח ע\"ז הי' במ\"ת, מ\"מ צריכים ג\"כ מדתו של יעקב דהנה כתי' נותן התורה שבכל יום יש מ\"ת<sup data-n=\"981\">31</sup>, וקודם מ\"ת כתי' ואשא אתכם על כנפי נשרים שהוא בחי' רחמים<sup data-n=\"982\">32</sup>, ולכן העולה הוא מכבשים. ועוי\"ל מפני דכבש יש לו ביטול יותר מכל הבהמות, דבשור יש שור נגח<sup data-n=\"983\">33</sup> אבל כבש הוא בטל יותר. ועוי\"ל דבכבש מרומז תומ\"צ דמעורו עושין לבושין וכמ\"ש בגז כבשים יתחמם, והם לבושים דמעשה המצות, ושערו הוא בחי' תורה וכמ\"ש קוצותיו תלתלים הם תילי תילים של הלכות. ועוי\"ל והוא העיקר דהנה אמרז\"ל איזהו גבור הכובש את יצרו שנא' טוב ארך אפים מגיבור, והנה קרבן בגימ' ארך אפים<sup data-n=\"984\">34</sup>, דע\"י קרבן שכובש את יצרו ממשיכים מבחי' א\"א, וזהו שהעולה היא מכבשים דכובש את יצרו<sup data-n=\"985\">35</sup>.",[["980","30","<b>וזהו שהעולה היא מכבשים</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380634\" data-slug=\"likkutei-torah\" data-id=\"4001380634\">לקו\"ת פנחס עח, ג</a>-<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380637\" data-slug=\"likkutei-torah\" data-id=\"4001380637\">ד. עט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380240\" data-slug=\"likkutei-torah\" data-id=\"4001380240\">אוה\"ת פנחס ס\"ע א</a>'קיג ואילך. וראה גם לקו\"ת אמור לח, סע\"ג ואילך. מאמרי אדה\"ז פרשיות ח\"ב ע' תקעט. סה\"מ תרכ\"ט ע' נז."],["981","31","<b>נותן התורה שבכל יום יש מ\"ת</b>: ראה לעיל ד\"ה מי זאת הנשקפה. וש\"נ."],["982","32","<b>וקודם מ\"ת כתי' ואשא . . כנפי נשרים . . בחי' רחמים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380348\" data-slug=\"likkutei-torah\" data-id=\"4001380348\">לקו\"ת במדבר י, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381035\" data-slug=\"likkutei-torah\" data-id=\"4001381035\">האזינו עח, א</a> ואילך. מאמרי אדהאמ\"צ ויקרא ח\"א ע' כב. סה\"מ תרכ\"ז ע' תעה. תרל\"ג ח\"א ע' רטז."],["983","33","<b>דבשור יש שור נגח</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380234\" data-slug=\"likkutei-torah\" data-id=\"4001380234\">לקו\"ת אמור לז, א</a>-ב."],["984","34","<b>קרבן בגימ' ארך אפים</b>: ראה גם סה\"מ תרל\"ב ח\"א ע' קסא."],["985","35","<b>מכבשים דכובש את יצרו</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380635\" data-slug=\"likkutei-torah\" data-id=\"4001380635\">לקו\"ת פנחס שם עח, ד</a>."]]],[2002180313,"<h3>שעיר עזים (ש\"פ חוקת)</h3>\n<b>ש\"פ חוקת ט\"ל לפ\"ק.</b>\n<b>ושעיר</b> עזים<sup data-n=\"986\">1</sup> אחד לחטאת לה', ואמרו בגמ' מה נשתנה שעיר זה שנא' בו חטאת לה' דבכל חטאת נא' חטאת סתם וכאן נא' חטאת לה', אלא אמר הקב\"ה שעיר זה יהא עלי כפרה על שמעטתי את הירח, וצ\"ל מה שייך חטא ועון למעלה שצריכים ע\"ז כפרה.",[["986","1","<b>ושעיר עזים</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב מהמאמר ד\"ה ”ומעתה צ\"ל מה שהחטאת\" הנדפס לעיל ע' תמו ואילך. [וראה בהנסמן שם בתחילת המאמר]. מאמר זה הוא בהמשך להמאמר שלפנ\"ז ד\"ה ובראשי חדשיכם."]]],[2002180314,"<b>והענין</b> דהנה בחטאת יש ג' פירושים<sup data-n=\"987\">2</sup>, א' חטאת הוא יצה\"ר<sup data-n=\"988\">3</sup> כמ\"ש לפתח חטאת רובץ ואמרז\"ל ז' שמות נקראו לו, ויש דעה שדוד קראו חטאת כמ\"ש וחטאתי נגדי תמיד. ב' חטאת הוא ל' חסרון כמ\"ש והייתי אני ובני שלמה חטאים ופירש\"י כלומר חסרים, וכמו קולע אל השערה ולא יחטיא, כשיש חסרון אפי' כחוט השערה ה\"ז חטאת, אך כשהוא קולע אל השערה ולא יחטיא. ג' חטאת נקיון וכמ\"ש תחטאני באזוב ואטהר וכתי' וחטא את הבית ותרגם וידכי ית ביתא. וצ\"ל איך יש ב' הפי' חסרון ונקיון. והענין שע\"י קרבן חטאת אפשר שמחסרון יהי' חטאת נקיון. והנה מ\"ש שעיר זה יהא עלי כפרה צ\"ל שבו יש כל הג' פי', וצ\"ל איך שייך חסרון למעלה כלום חסר.\n<b>והענין</b> דהנה כתי' ויעש אלקים את שני המאורות הגדולים את המאור הגדול לממשלת היום ואת המאור הקטן לממשלת הלילה, והנה בפסוק זה יש סתירה מרישא לסיפא דתחילה אומר שני המאורות הגדולים ואח\"כ אומר את המאור הגדול והמאור הקטן. והנה אי' בזהר שני מאורות הגדולים הם הוי' ואלקים, דהנה מצינו דהוי' נק' גדול כמ\"ש גדול הוי' ומהולל מאד וכן כמה פסוקים, ונק' אור כמ\"ש הוי' אורי וישעי, כי אתה נרי הוי', גם כי אשב בחשך הוי' אור לי, וש' אלקים נק' גדול דכתי' גדול הוי' ומהולל מאד בעיר אלקינו אימתי הוא גדול כשהוא בעיר אלקינו ובזהר אי' מלכא בלא מטרוניתא לאו גדול איקרי, ומאחר דש' אלקים פועל שהוי' יקרא גדול כ\"ש שהוא נק' גדול, ועוד קרב לגבי דהינא ואידהין.\n<b>ועל</b> ל' החסידות, ענין עיר אלקינו כמו עד\"מ מקיבוץ הרבה אבנים נעשה בית ומקיבוץ בתים הרבה נעשה עיר, אבנים הם אותיות וכמ\"ש ב' אבנים בונות ב' בתים ג' בונות ג' בתים כו' והוא כללות עולם הדיבור, וכמו שיהי' לע\"ל ונגלה כבוד הוי' וראו כל בשר יחדיו כי פי הוי' דיבר, דפי הוי' כמו שהוא למעלה יאיר ויתגלה למטה בעולם הדיבור וזהו מ\"ש זה דבר ה' אל זרובבל, שזה יאיר בדבר ה'<sup data-n=\"989\">4</sup>, והוא שפנימיות המל' יאיר ע\"י חיצוניות המל' ע\"י התלבשות האותיות. וזהו ההפרש בין נבואת משה לשאר הנביאים, דהנה נבואת משה הי' ע\"י אספקלרייא המאירה והוא בחי' זה, ולכן אמר זה הדבר אשר צוה ה', וכל הנביאים נתנבאו בכה<sup data-n=\"990\">5</sup> כדמותינו שהוא רק דמות שרואין במראה, שעצם הדבר אין שם כלל כ\"א דמות הדבר, וכמשית\"ל אי\"ה כמו שהלבנה מקבלת אור השמש. וזהו שני המאורות הוא כשש' הוי' מאיר בשם אלקים. אבל בזמן חורבן הבית הנה כתי' מי כמוכה באלים ה' מי כמוכה באלמים כו' מרקדים בהיכלו והוא שותק כביכול כאלם לא יפתח פיו, נאלמתי דומי'",[["987","2","<b>והענין דהנה בחטאת יש ג' פירושים</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010064\" data-slug=\"or-hatorah-hb\" data-id=\"8159010064\">אוה\"ת פנחס ע' א'קסח</a> ואילך. וע' א'קפט ואילך. וראה גם אוה\"ת חוקת ע' תשסב."],["988","3","<b>חטאת הוא יצה\"ר</b>: ראה לעיל בהמאמר ע' תמו (בפי' הא'): חטאת ל' חטא."],["989","4","<b>וזהו מ\"ש זה דבר ה' אל זרובבל שזה יאיר בדבר ה'</b>: ראה לעיל ס\"ע תיז-ח."],["990","5","<b>ההפרש בין נבואת משה לשאר הנביאים . . זה . . בכה</b>: ראה בכ\"ז לעיל ע' תיח. וש\"נ."]]],[2002180315,"החשיתי, כרחל לפני גוזזי' נאלמה, קודב\"ה בגלותא סליק לעילא ולעילא, והוא גלות השכינה בכלל ואז מאור הגדול ומאור הקטן, שם הוי' הוא גדול דסליק כו', אבל שם אלקינו נק' קטן.\n<b>וביאור</b> הענין דהנה כל נברא יש לו צירוף<sup data-n=\"991\">6</sup> המחי' אותו, כמו לזה נאה לקרות שור ולזה נאה לקרות חמור, והנה בע\"מ נברה\"ע והיכן הם צירופים אלה בע\"מ, ובסש\"ב יש בזה אריכות וקאמר שיש חילופים<sup data-n=\"992\">7</sup>, הם א\"ב כמו א\"ת ב\"ש או אלב\"ם, ובכלל יש רל\"א שערים המתגלגלים פנים ואחור, והנה א\"ת ב\"ש האל\"ף נתחלף בתי\"ו הנה התי\"ו הוא אות בפ\"ע רק כשמחליף מקום האל\"ף יש בו כח האל\"ף, וה\"ז כמו הלבנה דאחר הקטרוג כתי' המאור הקטן לכי ומעטי א\"ע ונעשה במיעוט היותר אחרון שנעשה עצם חשוך רק שמקבלת אור השמש, והול\"ל שתאיר כמו השמש ובאמת אינו בערך כלל אלא הוא מפני שמחליף האור ע\"י יחוד שמשא וסיהרא (ע' בסידור בשער השבת<sup data-n=\"993\">8</sup> בפי' לרוץ ארח) נתייחד אור השמש עם עצם הלבנה שהיא עצם חשוך ולכן אינה מאירה כ\"כ כמו השמש, כמו\"כ כאן ע\"י חילופים וחילופי דחלופים ותמורות ותמורות דתמורות, עד שבמיעוט אחר מיעוט אפשר שיהי' חטאת חסרון, [ועוד] לפתח חטאת רובץ.\n<b>והנה</b> בעבודה הוא<sup data-n=\"994\">9</sup>, דהנה כתי' וזרעתי את בנ\"י זרע אדם וזרע בהמה שיש ב' מדריגות בנשמה<sup data-n=\"995\">10</sup>, א' הם הנק' זרע אדם היינו שיש להם התקשרות לאלקות והוא בחי' דעת המחבר חו\"ב ראי' ושמיעה, דהנה כשא' שומע איזה דבר בכל פרטי פרטיו, מ\"מ כשרואה אח\"כ הדבר ההוא נעשה הקנין בנפש באו\"א, כמו\"כ בחי' הדעת שיהי' כאילו רואה, וכמו במ\"ת רואין את הנשמע שבשמיעה הי' ראי'. ב' הם הנק' זרע בהמה שאין להם דעת, וא\"כ השמיעה מרחוק הוא היסח הדעת, ואפ\"ל חטאת חסרון בשוגג, שחטאת הוא על שוגג, דאם הוא מקושר ע\"ד האבות הן המרכבה אינו שייך שיהי' חטא ועון, אבל בהיסח הדעת אפשר שיהי' חטא ועון שהוא חטאת חסרון. והעצה לזה שיהי' חטאת נקיון וכמ\"ש לב נשבר ונדכה אלקים לא תבזה, נדכה הוא מפעולה שהוא מצד ההתבוננות איך שחטאתי נגדי תמיד עי\"ז יהי' לב נשבר, וזה אפי' אלקים לא תבזה, דבכל הקרבנות כתי' ריח נחוח להוי' אבל לשם אלקים מה\"ד והצמצום אינו שייך קרבן, אבל בחי' זו הוא קרבן לש' אלקים ג\"כ.",[["991","6","<b>וביאור הענין דהנה כל נברא יש לו צירוף</b>: בהבא לקמן ראה אוה\"ת פנחס שם ע' א'קעג ואילך."],["992","7","<b>ובסש\"ב יש בזה אריכות וקאמר שיש חילופים</b>: שעהיוה\"א פי\"ב (פט, ב). וראה גם סה\"מ תרכ\"ז ע' שסה."],["993","8","<b>(ע' בסידור בשער השבת בפי' לרוץ אורח)</b>: סידור עם דא\"ח קפב, ד ואילך. ובארוכה פיה\"מ לאדהאמ\"צ כט, סע\"ב ואילך."],["994","9","<b>והנה בעבודה הוא</b>: בהבא לקמן ראה אוה\"ת פנחס שם ע' א'קעד ואילך."],["995","10","<b>וזרעתי את בנ\"י זרע אדם וזרע בהמה . . ב' מדריגות בנשמה</b>: ראה בכ\"ז בארוכה תו\"א משפטים עד, ג ואילך. וראה גם סה\"מ תרל\"ב ח\"א ע' ט. וש\"נ."]]],[2002180316,"<b>וזהו</b> שא' הביאו עלי כפרה על שמיעטתי את הירח דיש מעלה בחטאת על עולה, דהנה בעולה יש מעלה מה שכולה כליל, אבל במתן דמים יש מעלה בחטאת, דהנה בעולה הם שתים שהן ארבע<sup data-n=\"996\">11</sup> בקרן מזרחית צפונית ודרומית מערבית, מזרח י', צפון ה' עילאה, ודרומית הוא ו' ומערב ה' אחרונה, ובחטאת הי' על ארבע קרנות שהם ד' אותיות שם הוי', ואי' בזהר ובא לו לקרן בקדמיתא שהוא קוש\"י<sup data-n=\"997\">12</sup> שלמעלה מד' אותיות הוי' ובא כו' הוא שממשיכים מלמעלה מש' הוי' וכמ\"ש ותתפלל חנה על הוי', וכמו לפני הוי' תטהרו שהוא למעלה מש' הוי', תטהרו בגי' כתר, שהוא קוש\"י שמשם יומשך בש' הוי' שיהי' שני המאורות הגדולים וכמ\"ש שמש ומגן ה' אלקים, כמו ששם אלקים הוא מגן ונרתק לש' הוי' ולא שמסתיר ש' הוי' אלא שהוא כדי שיוכל לקבל שם הוי'.\n<b>ולכן</b> הי' החטאת משעיר עזים, ועולה הוא דוקא כבשים ונת\"ל הטעם ע\"ז<sup data-n=\"998\">13</sup>. והענין דהנה אמרז\"ל מ\"ט עיזי מסגי ברישא<sup data-n=\"999\">14</sup> והדר אימרי כבריתו של עולם ברישא חשוכא והדר נהורא ופירש\"י סתם עיזים שחורות, דהנה אימרי הוא עבודת הצדיקים וכמ\"ש וירא אלקים את האור כי טוב אלו מעשיהם של צדיקים, וכתי' את ה' האמרת היום אתם עשיתוני חטיבה א' בעולם ה' אלקינו ה' אחד אין כיוצא בו<sup data-n=\"1000\">15</sup>, אף אני אעשה אתכם חטיבה א' בעולם מי כעמך כישראל גוי אחד בארץ וזהו ה' האמרת ה' האמירך, וכתי' והי' במחשך מעשיהם אלו מעשיהם של הרשעים, אך יתרון האור מתוך החשך דוקא זכאין מרי' דתיובתא דמשכין לקוב\"ה בחילא יתיר כמו מרקחת עושין מדבר מר דוקא. וזהו דכתי' קח שני גדיי עיזים טובים הם שני שעירי יוהכ\"פ, טובים אי' במדרש טוב זה יצ\"ט טוב מאד זה יצה\"ר, והוא יצה\"ר אחר הבירור דיתרון אור כו', ואת עורות גדיי עיזים נתן על ידיו ועל חלקת צואריו וירח ריח בגדיו, אין לך ריח רע יותר משטף גדיי עיזים אלא נכנס עמו ריח ג\"כ, ואיך שייך בגדיי עיזים ריח ג\"ע אלא שהוא כשמהפכין ומבררים אותם ואז יתרון האור כו', וזהו ריח בגדיו ריח בוגדיו, ריח בגדיו הם לבושים דמעשה המצות וריח בוגדיו הם בע\"ת דיתרון האור מתוך החשך דוקא.\n<b>וזהו</b> הביאו עלי כפרה על שמעטתי את הירח, דמצד מיעוט נעשה אח\"כ במיעוט אחר מיעוט חטאת חסרון, וע\"י קרבן חטאת ממשיכים מבחי' שלמעלה מש' הוי' בשם הוי' שיהי' שני המאורות הגדולים.",[["996","11","<b>בעולה הם שתים שהן ארבע</b>: ראה גם אוה\"ת ויצא קפט, ב. ויקרא (כרך ב) ע' תכט ואילך. דרושים לר\"ה ע' א'שכד. סה\"מ תרכ\"ט שם ע' קכ."],["997","12","<b>ובא לו לקרן בקדמיתא שהוא קוש\"י</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830219\" data-slug=\"or-hatorah-hb\" data-id=\"8158830219\">אוה\"ת בלק ע' תתקה</a>."],["998","13","<b>ועולה הוא דוקא כבשים ונת\"ל הטעם ע\"ז</b>: לעיל סד\"ה ובראשי חדשיכם."],["999","14","<b>והענין דהנה אמרז\"ל מ\"ט עיזי מסגי ברישא</b>: בהבא לקמן ראה גם סה\"מ תרכ\"ט שם ס\"ע קיח ואילך. וס\"ע קכ ואילך."],["1000","15","<b>וכתי' את ה' האמרת . . אתם עשיתוני חטיבה א' . . ה' אחד אין כיוצא בו</b>: ראה בכ\"ז בארוכה לעיל ד\"ה את ה' האמרת [ובהנסמן שם]."]]],[2002180317,"<h3>לא הביט (ש\"פ קרח)</h3>\n<b>ש\"פ בלק ט\"ל לפ\"ק.</b>\n<b>לא</b> הביט און ביעקב<sup data-n=\"1001\">1</sup> ולא ראה עמל בישראל ה' אלקיו עמו ותרועת מלך בו, כמו שיש יעקב וישראל למטה דאחר שקראו ישראל קראו יעקב ג\"כ, כמו\"כ בעבודה למעלה יש ג\"כ יעקב וישראל שהם מדריגות שונות בעבודת ה'<sup data-n=\"1002\">2</sup>. והנה יעקב נק' עבד כמ\"ש שמע יעקב עבדי וכתי' אל תירא עבדי יעקב, וישראל נק' בן כמ\"ש בני בכורי ישראל. ובעבודה הוא תורה ותפלה, דהנה כתי' לעבדו בכל לבבכם איזה עבודה שבלב זו תפלה הרי תפלה הוא עבודת עבד, ותורה הוא ישראל כמ\"ש בכל התורה צו את בנ\"י דבר אל בנ\"י ולא נא' אל בני יעקב, ולכן כתי' ותורה שם בישראל.\n<b>והענין</b> דהנה כתי' גבי יחזקאל ראיתי מגלה עפה<sup data-n=\"1003\">3</sup> כתובה פנים ואחור, והוא תורה ותפלה, תפלה הוא אחור ותורה פנים, וצ\"ל מה שייך תורה לפנים. והענין דהנה כתי' חכמת אדם תאיר פניו ואי' במדרש אדם זה הקב\"ה וכמ\"ש ואשמע קול אדם מדבר וכתי' ועל דמות הכסא דמות כמראה אדם עליו מלמעלה, וצ\"ל מה שייך אדם למעלה והלא אין לו דמות הגוף ולא גוף, וכן מ\"ש נעשה אדם בצלמינו כדמותינו שאדם שלמטה הוא בצלם ודמות אדם שלמעלה, ומה שייך אדם למעלה והלא אין לו לא דמות הגוף ולא גוף. והענין דהנה כתי' לא מחשבותי מחשבותיכם<sup data-n=\"1004\">4</sup>, וצ\"ל למה אומר רק על מח' והלא הדיבור ג\"כ אינו שוה למעלה כמו למטה, דלמעלה נעשה העולם מהדיבור, ולמטה מהדיבור אינו נעשה כלום. והענין דהנה אמרז\"ל ז' דברים קדמו לעולם תורה תשובה ג\"ע כו' ומחשבתן של ישראל קדמו לכל דבר. והענין דהנה ברה\"ע הוא מהדיבור וכמ\"ש בדבר ה' שמים נעשו וברוח פיו כל צבאיו, בע\"מ נברה\"ע והלא במאמר אחד יכול להבראות, וז' דברים אלו קדמו למעלת העולם שהם ממח', ומח' של ישראל קדמו לכל דבר שהם במדריגה במח'<sup data-n=\"1005\">5</sup>* וכמו ישראל עלו במח' שהוא עלי' במח', דבמח' גופא יש כמה מדריגות, וכמו עד\"מ מי שיש לו בן יחיד הוא חביב אצלו ותמיד חקוק צורתו במוחו ולבו",[["1001","1","<b>לא הביט און ביעקב</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב מהמאמר הנדפס לעיל ע' תנג ואילך. [וראה בהנסמן שם בתחילת המאמר]. וראה לקמן ד\"ה כי יש אדם שעמלו בחכ' שהוא המשך למאמר זה."],["1002","2","<b>יעקב וישראל שהם מדריגות שונות בעבודת ה'</b>: בהבא לקמן ראה ד\"ה זה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380600\" data-slug=\"likkutei-torah\" data-id=\"4001380600\">לקו\"ת בלק ע, ג</a> ואילך."],["1003","3","<b>והענין דהנה כתי' . . ראיתי מגלה עפה</b>: בהבא לקמן ראה בארוכה הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370543\" data-slug=\"torah-or\" data-id=\"3901370543\">תו\"א מג\"א קכב, א</a> ואילך. סה\"מ תרל\"ה ח\"א ע' קמו ואילך. תרס\"ג ח\"ב ע' שלד ואילך. המשך תרס\"ו ע' רכח ואילך. תרע\"ח ע' קצו ואילך."],["1004","4","<b>והענין דהנה כתי' לא מחשבותי מחשבותיכם</b>: ראה בכ\"ז המשך תרס\"ו שם ע' רכט ואילך."],["1005","5","<b>שהם במדריגה במח'</b>: אוצ\"ל: במדריגה היותר עליונה במח'. כדלעיל ע' תנד."]]],[2002180318,"כמו\"כ למעלה<sup data-n=\"1006\">6</sup>, רק שאינו דומה למעלה כמו למטה, דלמטה כשיש לו בן אז הוא חקוק צורתו בלבו, ולמעלה קודם שהי' עלו במח' וכשעלה במח' נברא תיכף. וזהו כי לא מחשבותי מחשבותיכם דוקא, דבדיבור הנה כתי' באשר דבר מלך שלטון כשמדבר לא' ה\"ה עושה, אבל ממח' לא יעשה כלום. הגם שלמטה הדיבור הוא רק גורם העשי' אבל אינו עושה כלום, ולמעלה הדיבור גופא הוא העושה. ולכאו' י\"ל שדבור הוא כמו שאר המדות כמו חסד שלמטה הוא גורם השפעה שמי שהוא חסדן ה\"ה משפיע טוב לזולתו ומי שאינו חסדן אינו משפיע אבל לא שהחסד גופא נשפע, ולמעלה הנה כתי' מכלכל חיים בחסד כלי בתוך כלי עד שנשפע מדת החסד למטה להחיות, וכמו\"כ דיבור שהוא מדת המל'. אבל באמת אינו דומה כלל דדיבורו של הקב\"ה חשיב מעשה וכמו ויאמר אלקי' יהי אור, נעשה אור וכן רקיע כו', ודיבור רוחני ומעשה גשמי, וכמו אינו דומה ראי' לשמיעה דראי' תופס דבר גשמי דוקא מפני שהוא רוחני יותר, ושמיעה תופס דבר רוחני קול, הרי דיבור הוא רוחני ומעשה הוא גשמי, וא\"כ מדיבור נשתנה ממהות למהות, אבל חסד נמשך כלי בתוך כלי להחיות שהוא רוחני, אלא שלכך אומר כי לא מחשבותי כו' ולא דיבור, דלאחר עשי' אינו ניכר אם מדיבור נעשה או שהדיבור הי' רק הגורם העשי', אבל ממח' אפי' יחשב כל היום וכל הלילה לא יעשה מזה כלום, ולמעלה כשעלה במח' מיד נעשה.\n<b>והנה</b> מה שעלה במח'<sup data-n=\"1007\">7</sup> זהו אדם שלמעלה, דאוא\"ס אינו בערך ג' קוין<sup data-n=\"1008\">8</sup> שהם חב\"ד חג\"ת נה\"י, או חסד גבורה תפארת, דלגבי' כתי' כולם בחכ' עשית שאפי' החכ' נחשבת לעשי' גשמיות, אלא שנמשך הארת אוא\"ס שיהי' עלו במח'. וזהו חכמת אדם תאיר פניו וקאי על תורה שנק' ג\"כ אדם וכמ\"ש זאת התורה אדם אלא שהוא במדריגה גבוה יותר, דהנה ענין התקון הוא שיהי' התכללות, ובחב\"ד כלול חג\"ת נה\"י, וכמו שגידי המוח מתפשטין בכל הגוף אפי' ברגל ג\"כ מפני שבמוח יש ציור אדם וכמו\"כ בחכ' יש כללות חב\"ד חג\"ת נה\"י, וזהו חכמת אדם תאיר פניו של אדם שנא' ועל דמות הכסא דמות כמראה אדם, דהנה אנו רואין שחכ' פועל הארת הפנים וכמו ר\"א מצא תוס' חדתא צהבו פניו<sup data-n=\"1009\">9</sup> מפני העונג שיש בחכ', דהשכל נמשך מהמשכיל [עונג מקור התענוגים] שהוא בחי' עדן עין לא ראתה לכן פועל הארת פנים. וזהו אמרה מטרונא אחת לר\"י בר אלעאי פניך דומין למלוה ברבית או למגדלי חזרים, א\"ל הא והא אסורים לי אלא חכמת אדם תאיר פניו. וזהו שאמרז\"ל שמא תאמר זהו עדן זהו גן כשהוא אומר יוצא מעדן להשקות את הגן, עדן לחוד וגן לחוד, אלא שהנהר משקה את הגן, גן הם ג\"ן סדרים דאורייתא ועדן הוא כמ\"ש עין לא ראתה אלקים זולתך, ונמשך הארת העדן בתוך הגן לכן הוא פועל הארת",[["1006","6","<b>וכמו עד\"מ מי שיש לו בן יחיד . . ותמיד חקוק צורתו . . כמו\"כ למעלה</b>: ראה או\"ת להה\"מ (הוצאת קה\"ת) ב, ג. וראה גם כש\"ט סי' רמא (לא, ב). הובא ונת' באוה\"ת משפטים ע' א'רסז. א'רעח. אוה\"ת מג\"א ע' קצח. המשך תרס\"ו שם ע' רלא. המשך תער\"ב ח\"ב ס\"ע תתקב. סה\"מ מלוקט ח\"א ע' רעו. ח\"ב ע' ה. וש\"נ. ח\"ה ע' רפו. ח\"ו ע' קיט. ועוד."],["1007","7","<b>והנה מה שעלה במח'</b>: בהבא לקמן ראה המשך תרס\"ו שם ע' רלב ואילך."],["1008","8","<b>אדם שלמעלה . . ג' קוין</b>: ראה בכ\"ז בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370317\" data-slug=\"torah-or\" data-id=\"3901370317\">תו\"א יתרו עא, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370323\" data-slug=\"torah-or\" data-id=\"3901370323\">עב, ד</a>. סה\"מ תרל\"ב ח\"א ע' יב. ס\"ע טו ואילך. ועוד."],["1009","9","<b>וכמו ר\"א מצא תוס' חדתא צהבו פניו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380697\" data-slug=\"likkutei-torah\" data-id=\"4001380697\">לקו\"ת מסעי צג, רע\"ב</a>. לעיל ע' שעה. וראה סה\"מ מלוקט ח\"ב ע' עז. ובכ\"מ."]]],[2002180319,"הפנים, וזהו חכמת אדם תאיר פניו שמחכ' התורה נמשך הארת פנים באדם שעל הכסא.\n<b>והנה</b> כתי' יאר ה' פניו אליך ואי' במדרש<sup data-n=\"1010\">10</sup> מאור תורה, והוא ג\"כ בחי' חכמת אדם, ועוד דרש יש שם שיביט בך בפנים מאירות, והוא ג\"כ ענין חכמת אדם. והענין דהנה ארז\"ל כל השונה הלכות בכ\"י מובטח לו שהוא בן עוה\"ב שנא' הליכות עולם לו א\"ת הליכות אלא הלכות, דתורה הוא ההילוך מלמעלמ\"ט. והענין דהנה כתי' כאשר יאמר משל הקדמוני, דתורה הוא משל לא\"ס קדמונו של עולם<sup data-n=\"1011\">11</sup>, דהנה משל מסתיר על הנמשל ומ\"מ מזה מובן הנמשל, וכמו שהע\"ה א'<sup data-n=\"1012\">12</sup> ג' אלפים משלים, והמשלים הם דברי' זרים כמו על חכ' התורה א' משל ראה חיים עם אשה אשר אהבת ועל חכ' משל אחר שהם דברי' זרים מ\"מ מובן מזה הנמשל. וענין הג' אלפים משלים שא', דהנה כתי' וה' נתן חכ' לשלמה שנתן לו חכ' תתאה במתנה שהוא מקור בי\"ע<sup data-n=\"1013\">13</sup>, לכן אמר ג' אלפים משלים, בכל עולם ג' מדריגות<sup data-n=\"1014\">14</sup> שכל מדריגה הוא משל למדריגה שלמעלה ממנה, כמו חשן ואפוד שלמטה שהיו מאבנים הוא משל לחשן ואפוד שבעשי' הרוחניות<sup data-n=\"1015\">15</sup>, וגבוה מעל גבוה שומר, והוא רק מח\"ת, ויש מדריגה זו גם באצי', ולפני אצי' תורה הוא משל לא\"ס קדמונו ש\"ע שהוא לפני אצי' העליון ומשם נמשך למטה. וזהו יאר ה' פניו אליך שהארת פנים שיש בתורה יומשך אליך למטה ג\"כ. וזהו בית יעקב לכו ונלכה באור ה', דהנה כתי' ועל דמות הכסא דמות כמראה אדם עליו מלמעלה הוא מראה דמות כבוד הוי' [ומבחי' חכ' אדם נמשך באור הוי' וע\"י בית יעקב היינו נשמות בגופים שלומדים תורה ממשיכים שיומשך למטה ג\"כ]. וזהו דכתי' לבושי' כתלג חיוור שקאי על תורה, דכמו שלג שהוא מים שנגלד<sup data-n=\"1016\">16</sup> ונעשה שלג, ואח\"כ בהפשרת שלגים נעשה מזה מים, כמו\"כ תורה הוא חכ' בראש בחי' חכ' אדם, וחכ' בסוף שנמשך למטה ג\"כ.\n<b>וזהו</b> כמים הפנים אל הפנים<sup data-n=\"1017\">17</sup>, שמהפנים של חכ' אדם נמשך באדם שעל הכסא, כן לב האדם אל האדם שנמשך בהאדם שלמטה ג\"כ. וזהו דגבי שבת כתי' ויברך אלקים את יום השביעי ברכו במאור פניו של אדם אינו דומה מאור פניו של אדם",[["1010","10","<b>והנה כתי' יאר ה' פניו אליך ואי' במדרש</b>: בהבא לקמן ראה המשך תרס\"ו שם ע' רלז. ואילך."],["1011","11","<b>משל הקדמוני דתורה הוא משל לא\"ס קדמונו של עולם</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370439\" data-slug=\"torah-or\" data-id=\"3901370439\">תו\"א מג\"א צח, ב</a>. אוה\"ת וארא ע' קנב. סה\"מ תרכ\"ט ע' צו. וש\"נ."],["1012","12","<b>שהע\"ה א'</b>: שלמה המלך ע\"ה אמר."],["1013","13","<b>וענין הג' אלפים משלים . . מקור בי\"ע</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">תו\"א מקץ מב, ב</a>. מג\"א שם צח, ב. סה\"מ תרכ\"ט ע' צה. וש\"נ. סה\"מ מלוקט ח\"ג ע' לז. סה\"ש תשמ\"ט ח\"א ע' 151 הע' 31. ובכ\"מ."],["1014","14","<b>בכל עולם ג' מדריגות</b>: אוצ\"ל: בכל עולם אלף מדריגות. ראה לעיל בהמאמר ע' תנו: שבכל עולם יש אלף מדריגות."],["1015","15","<b>חשן ואפוד . . משל לחשן ואפוד . . הרוחניות</b>: ראה בארוכה אוה\"ת תצוה ע' א'תרמה-ו. א'תרסה ואילך. א'תרעט. סה\"מ תרל\"ג ח\"א ע' קסה-ו. [ובהנסמן שם בתחילת המאמר]."],["1016","16","<b>דכמו שלג שהוא מים שנגלד</b>: ראה גם סה\"מ תרכ\"ז ע' תכז. וש\"נ."],["1017","17","<b>וזהו כמים הפנים אל הפנים</b>: ראה לעיל ח\"א ד\"ה כמים הפנים. — בהבא לקמן ראה המשך תרס\"ו שם ע' רלח."]]],[2002180320,"בשבת למאור פניו של אדם בחול, וצ\"ל מהו\"ע המאור פניו של אדם בשבת. והענין דהנה שבת לאו זמן תפילין<sup data-n=\"1018\">18</sup>, דע\"י תפילין ממשיכים מוחין לז\"א קדש והי' כי יביאך חו\"ב, שמע והא\"ש דעת הנחלק לחו\"ג. והנה תפילין הם על גבי הראש בבחי' מקיף, ובשבת נמשכים מקיפים דחול בפנימיות דאז מאיר מוחין דאבא, ולכן אינו דומה כו' מפני שהמוחין נמשכים בפנימיות פועל הארת פנים. והנה כמו שע\"י תורה ממשיכים מדרי' זו<sup data-n=\"1019\">19</sup> כמו\"כ ע\"י מצות דהנה עטרת תפארת שיבה בדרך צדקה תמצא, תפארת שיבה הוא הזקן, הדרת פנים זה זקן, וזהו ר\"י לא הי' לו הדרת פנים שלא הי' לו זקן, ולמעלה הו\"ע יגד\"ת י\"ג מדה\"ר, וע\"י יג\"מ שהתורה נדרשת ממשיכים היגת\"ד<sup data-n=\"1020\">20</sup>, בדרך צדקה תמצא שע\"י צדקה ממשיכים מדריגה זו, דצדקה הוא להחיות רוח שפלים שהוא חי בזה, ועי\"ז ממשיכים למעלה מאור פני מלך חיים. והעיקר הוא עבודה בשמחה וכמ\"ש תחת אשר לא עבדת את ה' אלקיך בשמחה ובטוב לבב מרב כל, כל הוא העמוד המחבר<sup data-n=\"1021\">21</sup> געה\"ע וגעה\"ת וכמ\"ש כי כל בשמים וארץ שמים געה\"ע וארץ געה\"ת וכל הוא מחבר אותם, וזהו יפה שעה כו' מכל חיי עוה\"ב, כל שהוא חיי עוה\"ב, דגן עדן הוא רק העדן שנמשך לגן אבל ע\"י מצות נמשך עדן בעצם, ולכן הוא מרב כל מריבוי מדרי' שיש בכל, דיש כמה ג\"ע הגם דבספרים אי' געה\"ע אבל באמת יש כמה מדרי', וא\"כ יש כמה בחי' כל ועבודה בשמחה ובטוב לבב הוא מרוב כל.",[["1018","18","<b>דהנה שבת לאו זמן תפילין</b>: ראה אוה\"ת דברים (כרך ו) ע' ב'תתפט. ובהנסמן שם."],["1019","19","<b>והנה כמו שע\"י תורה ממשיכים מדרי' זו</b>: בהבא לקמן ראה המשך תרס\"ו שם ע' שלט."],["1020","20","<b>שהתורה נדרשת ממשיכים היגת\"ד</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380431\" data-slug=\"likkutei-torah\" data-id=\"4001380431\">לקו\"ת בהעלותך ל, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380779\" data-slug=\"likkutei-torah\" data-id=\"4001380779\">עקב טז, ב</a>. ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380850\" data-slug=\"likkutei-torah\" data-id=\"4001380850\">ראה לג, ד</a>. וראה או\"ת להה\"מ ס\"פ בהעלותך (מו, ב). סה\"מ תרכ\"ט ע' רל. וש\"נ."],["1021","21","<b>תחת אשר לא עבדת . . מרב כל . . העמוד המחבר</b>: ראה בכ\"ז לעיל ח\"א ד\"ה החודש הזה לכם. וש\"נ."]]],[2002180321,"<h3>כי יש אדם עמלו בחכמה (ש\"פ פינחס)</h3>\n<b>ש\"פ פינחס ט\"ל לפ\"ק.</b>\n<b>כי</b> יש אדם שעמלו בחכ'<sup data-n=\"1022\">1</sup> ובדעת ובכשרון ולאדם אשר לא עמל בו יתננו חלקו גם זה הבל ורעה רבה. ואי' במדרש אדם זה הקב\"ה כמ\"ש ועל דמות כו' כמראה אדם, שעמלו בחכ' כו' כמ\"ש ה' בחכ' יסד ארץ כונן שמים בתבונה בדעתו תהומות נבקעו, ולאדם אשר כו' זה דור אנוש ודור המבול, גם זה כו' כמ\"ש וירא ה' כי רבה רעת האדם. וצ\"ל מה שייך עמל למעלה והלא לא בעמל וביגיעה ברא הקב\"ה את עולמו, בע\"מ ברא הקב\"ה את העולם.",[["1022","1","<b>כי יש אדם שעמלו בחכ'</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב מהמאמר ד\"ה ”ואחור הוא בחי' תפילה\" הנדפס לעיל ע' תס ואילך. מאמר זה הוא המשך להמאמר שלפנ\"ז ד\"ה לא הביט און ביעקב."]]],[2002180322,"<b>וצ\"ל</b> תחלה ענין המגילה הכתובה פנים ואחור ונת\"ל דפנים הוא<sup data-n=\"1023\">2</sup> [תורה] וכמ\"ש חכמת אדם תאיר פניו וכמ\"ש כמים הפנים אל הפנים שנמשך מבחי' חכמת אדם לאדם שעל הכסא, כן לב כו' שנתארך ונמשך עד למטה מטה<sup data-n=\"1024\">3</sup>. ותפלה הוא אחור<sup data-n=\"1025\">4</sup> כמ\"ש אחרי ה' אלקיכם תלכו וכמ\"ש זכרתי לך חסד נעוריך כו' לכתך אחרי במדבר, דכשהלכו לא לקחו צידה לדרך והלכו בארץ ציה ושממה שאינו שייך שם לא זריעה ולא צמיחה, בלא לחם ומזון, וזה מפני שהיו בטלים לאלקות, כמו ענין התפלה ואהבת שיהי' לו אהבה ורצון ותשוקה לאלקות והוא כשיתבונן בפסוק ראשון שמע כו' יחו\"ע ויחו\"ת, ועי\"ז יהי' לו אהבה לאלקות, מי לי בשמים ועמך לא חפצתי בארץ, שמים תענוגים רוחניים וארץ תענוגים גשמיים<sup data-n=\"1027\">5</sup>, הכל עמך שהוא טפל<sup data-n=\"1026\">6</sup> ולא עצם, ומה ירצה אם העצם או הטפל, וזהו\"ע שהתפלה נק' אחור.\n<b>ועוי\"ל</b> שלכן התפלה נק' אחור<sup data-n=\"1028\">7</sup> לבד מה שהוא נמשך לאלקות, הנה ההתבוננות שגורם הביטול הוא רק בבחי' אחרי, דהנה כלליות ההתבוננות הוא מל' מל' כ\"ע שכל עולמים הם רק מבחי' מל' אשר מלך שמו נק' עליהם, כמו השם שהוא אחורים וחיצוניות, דמל' הוא מלוכה, וכתי' ומושיב מלכים לכסא וכתי' וישב ה' למלך לעולם כמו ישיבה היא באחוריים כמו\"כ מדת המל' הוא רק אחוריים וחיצוניות. ולכן בתפלה אומרים לשון שם ישתבח שמך לעד מלכינו, ומעריצים כו' את שם האל, יהללו את שם ה' כי הוא צוה ונבראו, יהללו את שם ה' כי נשגב שמו לבדו. וכשהי' צ\"ל בחי' מל' הנה כתי' כבוד מל' יאמרו וגבורתך ידברו, אתה גבור לעולם אד', כשצ\"ל בחי' אנת אשתמודע אדון על כולא מקור בי\"ע הוא ע\"י גבורות וצמצומים, וכשיתבונן איך שכל עולמים הם רק מבחי' מל' יהי' בטל לאלקות מי לי בשמים ועמך לא חפצתי בארץ, כלה שארי ולבבי, צמאה נפשי, והוא רצון חזק, דמי שהוא צמא למים הוא רצון חזק יותר ממי שהוא רעב ללחם, דכשהוא רעב ללחם אפשר שירצה עוד דבר אחר, אבל כשהוא צמא למים אינו רוצה לשום דבר, וכמו\"כ ע\"י התבוננות התפלה יהי' לו צמאון לאלקות. ולכן נק' התפלה אחור ותורה הוא פנים וכמו כמים הפנים כו'.\n<b>והנה</b> לתורה צריכים תפלה ג\"כ, דהנה תו' נק' מים כמ\"ש הוי כל צמא לכו למים, וכתי' כמים קרים על נפש עיפה, דכשהוא צמא למים אז נהנה מהמים ולכן",[["1023","2","<b>ונת\"ל דפנים הוא </b> [תורה]<b></b>: לעיל בד\"ה לא הביט און ביעקב."],["1024","3","<b>וכמ\"ש כמים הפנים אל הפנים . . שנתארך ונמשך עד למטה מטה</b>: ראה תניא פמ\"ו. וראה גם מאמרי אדה\"ז תקס\"ד ע' צד ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8315950477\" data-slug=\"or-hatorah-hb\" data-id=\"8315950477\">אוה\"ת בשלח ע' תעז</a> ואילך. ועוד."],["1025","4","<b>ותפלה הוא אחור</b>: בהבא לקמן ראה המשך תרס\"ו ס\"ע רמא-ב."],["1027","5","<b>וארץ תענוגים גשמיים</b>: ראה לעיל הנחת כ\"ק אדמו\"ר מהורש\"ב מד\"ה בהעלותך. וש\"נ."],["1026","6","<b>מי לי בשמים ועמך לא חפצתי . . עמך שהוא טפל</b>: ראה גם לעיל ע' תמב. וש\"נ. ובהנסמן בהע' שלאח\"ז."],["1028","7","<b>ועוי\"ל שלכן התפלה נק' אחור</b>: בהבא לקמן ראה המשך תרס\"ו שם ע' רצז."]]],[2002180323,"השותה מים לצמאו מברך, אבל השותה לאונסו כמו חנקתו אומצא<sup data-n=\"1029\">8</sup> אינו מברך לא בתחילה ולא בסוף, וזהו הוי כל צמא כו' דוקא צמא, ולכן כשיש תחילה תפלה שהוא שיהי' לו צמאון לאלקות אז שייך תורה שהוא מים. וזהו והיו הדברים האלה כו' ואמרז\"ל בד\"ת הכתוב מדבר ומה שייך תורה לואהבת, אלא כשיש תחילה הב' מיני אהבות ע\"י התבוננות דיחו\"ע ויחו\"ת וכמ\"ש כי עמך מקור חיים אפי' מקור החיים מקור התענוגים טפל ובטל לך ויהי' לו רצון לאוא\"ס, ואח\"כ והיו הדברים האלה בד\"ת הכתוב מדבר דבתורה יש בחי' זו דאורייתא וקוב\"ה כולא חד, אורייתא היכלא עילאה דקוב\"ה.\n<b>ועוי\"ל</b> לכן התפלה נק' אחור, דהנה אמרז\"ל הני י\"ח ברכות כנגד מי כנגד ח\"י חוליות שבשדרה<sup data-n=\"1030\">9</sup>, והעיקר הוא החוט [השדרה] שהוא נמשך ממוח שמושבו הוא לצד האחור, דמושב מוחין חו\"ב הוא לצד הפנים, ומוח הדעת הוא לצד האחור, ולכן התפלה נק' אחור. והענין דהנה חכ' הוא ראי' כמו חכמים נק' עיני העדה, איזהו חכם הרואה את הנולד, וכמ\"ש וירא ראשית לו שהוא לצד הפנים. וענין הראי' הוא, דהנה משה ביקש אעברה נא ואראה את הארץ וכי לאכול מפריה הוא צריך, אלא ארץ הוא כנס\"י ורצה להמשיך בחי' ראי'<sup data-n=\"1031\">10</sup> בכנס\"י ולא פעל זה, דלא כ\"א יוכל לבוא למדרי' זו, כ\"א ראי' מרחוק וכמ\"ש כי מנגד תראה את הארץ, ועי\"ז פעל בחי' ראי' רק ביחידי סגולה<sup data-n=\"1032\">11</sup> כמו חכמים נק' עיני העדה, וכמו איזהו חכם הרואה הרי זה ראיית אלקות. ודעת הוא בכל ישראל וכמ\"ש וידעת היום והשבות אל לבבך שהוא הכרה והרגשה באלקות כאילו רואה הגם שאינו רואה ממש אך הוא כאילו רואה. דהנה יש ב' מדריגות דעת ואמונה<sup data-n=\"1033\">12</sup>, אמונה הוא במקיף והוא מקיף הרחוק כ\"כ עד שאפשר שיעשה היפך רצה\"ע וכמארז\"ל גנבא אפום מחתרתא<sup data-n=\"1034\">13</sup> רחמנא קריא שמאמין שביכולתו לעזור לו ומ\"מ הוא עושה היפך הרצון, ולא עוד אלא שמבקש שיעזור לו לעשות היפך הרצה\"ע, נמצא שהוא מקיף הרחוק, אבל דעת הוא בפנימיות שהוא הכרה והרגשה באלקות, וזהו\"ע התפלה לכן נק' התפלה אחור. וענין התפלה הוא ברוך אתה הוי', הוי' יו\"ד צמצום ה' התפשטות<sup data-n=\"1035\">14</sup> ו' המשכה ה' אחרונה התפשטות, והוא סדר השתל'. והנה סדר השתל' לגבי אוא\"ס שלמעלה מסדר השתל' הוא הארה",[["1029","8","<b>כמו חנקתו אומצא</b>: ראה ברכות מה, א. שו\"ע או\"ח סי' רד סעי' ז. שו\"ע אדה\"ז שם סעי' יז."],["1030","9","<b>ועוי\"ל לכן התפלה נק' אחור . . ח\"י חוליות שבשדרה</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380601\" data-slug=\"likkutei-torah\" data-id=\"4001380601\">לקו\"ת בלק ע, ד</a> ואילך."],["1031","10","<b>משה ביקש אעברה נא ואראה . . להמשיך בחי' ראי'</b>: ראה בכ\"ז בארוכה לקו\"ת ואתחנן ב, סע\"ג ואילך. ג, ג ואילך. סה\"מ תרל\"ג ח\"ב ע' תכג [ובהנסמן שם בתחילת המאמר]. ובהנסמן בהערה שלאח\"ז."],["1032","11","<b>פעל בחי' ראי' רק ביחידי סגולה</b>: ראה סה\"מ תרכ\"ז ע' רצב. שפט. תרכ\"ט ע' רלא. וש\"נ. תרל\"ב ח\"א ע' קסח. שיט. ח\"ב ע' שע. תרל\"ג ח\"ב ע' תכח. ועוד."],["1033","12","<b>יש ב' מדריגות דעת ואמונה</b>: בהבא לקמן ראה בארוכה לקו\"ת ואתחנן ד, א ואילך. ו, א ואילך."],["1034","13","<b>אמונה הוא במקיף . . גנבא אפום מחתרתא</b>: ראה בכ\"ז בארוכה סה\"מ תר\"ל ע' קיא. תרל\"ב ח\"א ע' צ-צא. [ובדרושים שנסמנו שם בתחילת המאמר]."],["1035","14","<b>הוי' יו\"ד צמצום ה' התפשטות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380601\" data-slug=\"likkutei-torah\" data-id=\"4001380601\">לקו\"ת בלק שם ע, ד</a>. לעיל ד\"ה אנכי אנכי. וש\"נ."]]],[2002180324,"מצומצמת, אתה הוא אוא\"ס שלמעלה מסדר השתל', וזהו ברוך כו' שיתברך ויומשך מאוא\"ס שלמעלה מסדר השתל' לההארה המצומצמת, ותוס' של הקב\"ה מרובה על העיקר. והכלי לזה הוא ח\"י ברכאן דצלותא לרפאות החולים ולברך השנים, ואפשר שיתרפא החולה יותר מזה שהי' קודם.\n<b>וזהו\"ע</b> יעקב שנא' יעקב עבדי<sup data-n=\"1036\">15</sup>, וכתי' לעבדו בכל לבבכם איזה עבודה שבלב זו תפלה, וזהו יעקב יו\"ד עקב שיומשך עד עקביים, ובעבודה הו\"ע רעו\"ד, וזהו יו\"ד נקודה חדא אזעירת גרמא, אוכמתא דלית בי' חוורתא, והוא מורה על ביטול. וישראל הוא כמ\"ש בני בכורי ישראל, והוא בחי' מה שמו מה שם בנו, שמה שמו הוא מ\"ה דחכ' יומשך בבחי' בנו.\n<b>וזהו</b> לא הביט און ביעקב<sup data-n=\"1037\">16</sup>, דהנה און הוא איש און מחשבותיו והוא ערמומית תחבולות ומרמות, והוא היפך מיעקב שהוא מח' טובה, ואיש און הוא מח' רעה הרהורין בישין, ולכן בשעת התפלה שמאיר חב\"ד אז המח\"ז בחוזק יותר. וזהו לא הביט און ביעקב, דביעקב לא שייך און דהנה כתי' גבי' וירא כי לא יכול לו דיעקב הוא י' עקב שנמשך עד עקביים שמעמיד גם הרגלים. והנה לישראל צריכים יעקב ג\"כ דלאחר שקראו ישראל קראו יעקב, דכל הקורא לאברהם אברם עובר בעשה ולא יעקב, ופריך בגמ' מ\"ש, ומתרץ הדר אהדרי' קרא, וצ\"ל למה אהדרי', והוא מפני כי שלישראל שהוא תורה צריכים יעקב ג\"כ שהוא תפלה, וכמו חוט השדרה שמעמיד הרגלים, ולכן כשיש איזה קלקול ברגלים מרפאים החוט השדרה, וכמו\"כ הוא יעקב י' עקב שמעמיד הרגלים וכמ\"ש ימותו ולא בחכ'.\n<b>ולא</b> ראה עמל בישראל<sup data-n=\"1038\">17</sup>, הנה כתי' כי יש אדם שעמלו בחכ' ובדעת ובכשרון, אדם זה הקב\"ה ונת\"ל שזהו מ\"ש ישראל עלו במח'<sup data-n=\"1039\">18</sup>, שעלו בחכ' כו'. הנה כתי' אדם לעמל יולד ואמרז\"ל א\"י אם עמל מלאכה אם לעמל פה, כשהוא אומר אכף עלי פיהו הוי עמל פה, ועדיין איני יודע אם לעמל תורה או לעמל שיחה כשהוא אומר לא ימוש ספר התורה הזאת מפיך הוי עמל תורה. וצ\"ל והלא כתי' מה יתרון לאדם בכל עמלו שיעמול תחת השמש ואי' בזהר שאני עמלא דאורייתא דלעילא משמשא, ובגמ' אי' ג\"כ תחת השמש אבל קודם השמש יש עמל, וצ\"ל והלא בפ' שני' דק\"ש כתי' ואספת דגנך וזהו תחת השמש. והענין דהנה כתי' שמש ומגן ה' אלקים, שם ה' נמשל לשמש<sup data-n=\"1040\">19</sup> כמו שמש אורו וזיוו מאיר למטה, ובגוף כדור השמש הוא בטל לגמרי,",[["1036","15","<b>וזהו\"ע יעקב שנא' יעקב עבדי</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380605\" data-slug=\"likkutei-torah\" data-id=\"4001380605\">לקו\"ת בלק שם עא, ד</a>."],["1037","16","<b>וזהו לא הביט און ביעקב</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380601\" data-slug=\"likkutei-torah\" data-id=\"4001380601\">לקו\"ת בלק שם ע, סע\"ד</a>."],["1038","17","<b>ולא ראה עמל בישראל</b>: בהבא לקמן עד סוף המאמר ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600610\" data-slug=\"or-hatorah-hb\" data-id=\"8316600610\">אוה\"ת נ\"ך (כרך א) ע' תרי</a>-<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450631\" data-slug=\"or-hatorah-hb\" data-id=\"8316450631\">יא. כרך ב' ע' א'קא</a>. כרך ג ע' א'שעח. ובארוכה בסה\"מ תרל\"ב ח\"ב ע' שפג ואילך. וש\"נ. תרס\"ט ע' רי ואילך."],["1039","18","<b>ונת\"ל שזהו מ\"ש ישראל עלו במח'</b>: לעיל ד\"ה לא הביט און ביעקב."],["1040","19","<b>שמש ומגן ה' אלקים שם ה' נמשל לשמש</b>: ראה שעהיוה\"א פ\"ד ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370017\" data-slug=\"torah-or\" data-id=\"3901370017\">תו\"א בראשית ד, סע\"ד</a> ואילך. יהל אור להצ\"צ ס\"ע ש ואילך."]]],[2002180325,"כמו\"כ שם הוי' ל' מהווה והוא הוי' מקור כל ההויות, וכתי' אני הוי' הוא שמי שהוא רק שם לבד, ושם אלקים הוא כמו מגן שמכסה ומסתיר על אור השמש, כמו\"כ שם אלקים מכסה ומסתיר על אור הוי', ומ\"מ אין זה הסתר גמור דזה גורם ביטול היש. אך יש מ\"ח צירופים אחרונים דשם אלקים שהם מעלימים ומסתירים לגמרי על אור ה' וקדושתו והו\"ע אדמת בני חם.\n<b>וזהו</b> שכ' אל תראוני שאני שחרחורת<sup data-n=\"1041\">20</sup> ששזפתני השמש והוא בחי' שמש ומגן ה' אלקים, והוא ע\"י התבוננות בתי' אחד, דז' רקיעים וארץ וד' רוחות העולם בטלים לאלקות, והו\"ע שלהוביתא דרחימותא. אך יש בלעו\"ז ג\"כ והוא חמימות התאוה בעניני עוה\"ז. נמצא שיש תחת השמש ב' עמלים, א' עמל דביטול היש שהוא משם אלקים, ב' עמל ממ\"ח צירופים אחרונים דשם אלקים. וזהו ואספת דגנך שיאסוף כל הדברים גשמיים<sup data-n=\"1042\">21</sup> להעלותם בקדושה. ושאני עמלא דאורייתא דלעילא משמשא וע\"ז נאמר לא ראה עמל בישראל. דהנה אמרז\"ל ר\"י אומר הנהג בו מדת ד\"א, אר\"ש אפשר אדם זורע בשעת זריעה וקוצר בשעת קצירה תורה מה תהא עלי', אלא בזמן שישראל עושין רצוש\"מ מלאכתם נעשה ע\"י אחרים. והענין דהנה אמרז\"ל עשה תורתך קבע ומלאכתך עראי<sup data-n=\"1043\">22</sup>, ואין הפי' שיהי' קביעות בזמן אלא שעיקר המכוון יהי' בשביל תומ\"צ הגם שהוא זמן קטן, וכמו מי שעוסק במו\"מ הרי המכוון הוא הריווח והוא זמן קטן והעסק הוא קביעות, מ\"מ העיקר הוא הריווח. כמו\"כ כאן הגם שכל הזמן יהי' במו\"מ מ\"מ עיקר המכוון יהי' בכדי שיוכל לקיים מצות, וכמו עושה צדקות בכל עת זה הזן ומפרנס בניו וב\"ב, ויוכל ללמוד תורה פרק א' שחרית ופרק א' ערבית. אבל כשיעסוק בתורה ע\"ד תורתו אומנתו אז ועמדו זרים ורעו צאנכם, וכמאמר אם אתה מעמל בתורה התורה מעמלת לך במ\"א שלא יצטרך להעמל דביטול היש ג\"כ. וזהו ולא ראה עמל בישראל, ישראל הוא תורה ומצד בחי' זו לא ראה עמל כלל אפי' עמל דביטול היש ג\"כ. וזהו יש אדם שעמלו בחכ' הוא חכמת התורה חכמת אדם הפנימי.\n<b>ה'</b> אלקיו עמו ותרועת מלך בו, עמו הוא מקיף וכמו גלו לבבל שכינה עמהם, ובו הוא פנימיות, והו\"ע תומ\"צ, דלבושים דמעשה המצות הם מקיפים, ותורה הוא פנימיות. וזהו לא הביט און ביעקב דביעקב י' עקב לא שייך און, ולא ראה עמל בישראל, ישראל הוא תורה ושם אינו שייך עמל אפי' עמל דביטול היש ג\"כ אינו שייך שם, ה' אלקיו עמו הוא מקיפים דמצות, ותרועת מלך בו הוא בחי'* תורה\n\n*)בחי' תורה שנמשך בפנימיות: בשולי הגליון נרשם בגוכי\"ק: עמל תורה הוא פנימיות.",[["1041","20","<b>וזהו שכ' אל תראוני שאני שחרחורת</b>: בהבא לקמן ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381152\" data-slug=\"likkutei-torah\" data-id=\"4001381152\">לקו\"ת שה\"ש ה, ד</a>."],["1042","21","<b>וזהו ואספת דגנך שיאסוף כל הדברים גשמיים</b>: ראה גם סה\"מ תרכ\"ו ע' קסט. וע' קעא. ובכ\"מ."],["1043","22","<b>אמרז\"ל עשה תורתך קבע ומלאכתך עראי</b>: ראה בכ\"ז סה\"מ תרכ\"ו שם ע' קסח. קעא. תרכ\"ט ע' כז. תא. תר\"ל ע' רמד. רנב. תרל\"ב ח\"ב ע' שפה. שפח. תרל\"ג ח\"א ע' קלז. ועוד."]]],[2002180326,"שנמשך בפנימיות. ולאדם שלא עמל בו יתננו חלקו גם זה הבל ורעה רבה, הו\"ע ז' מצות שנצטוו בני נח וגם זה לא קיימו."],[2002180327,"<h3>היתר נדרים פורחין באויר (ש\"פ דברים)</h3>\n<b>ש\"פ דברים ט\"ל לפ\"ק.</b>\n<b>היתר</b> נדרים פורחין באויר<sup data-n=\"1044\">1</sup>, וצ\"ל ענין פורחין באויר, הנה נת\"ל דנדרים סיג לפרישות שהוא פורש א\"ע מאותו דבר וא\"כ ה\"ז דחי' אלא שהדחי' אינו בלא שה\"ה היתר אלא שמפני שהמוצא פי ה' שבמאכל גבוה במעלה יותר מהמוצא פי ה' שבאדם לכן אינו בכחו להעלות אותו, מ\"מ ה\"ז דחי' ואין נ\"מ אם הדחי' היא מעלה או חסרון, והדחי' מפני דפרישות הוא מילי דחסידותא והוא ביטול אמיתי ומבלבל לו המאכל שהוא ביטול היש. וכמו ע\"ד דוגמא ר\"ז כד סליק לא\"י צם מאה תעניתא כדי לשכוח תלמוד בבלי, הגם דתלמוד הוא בבריאה והוא מדריגה גבוה, אך הנה אמרז\"ל במחשכים השיבני זו תלמוד בבלי והוא בחי' ובורא חשך פי' שהוא העלם לגבי נבראים, והנה כל רבי מא\"י ששם תוס' יו\"ד חכ' לכן מבלבל לזה תלמוד בבלי. כמו\"כ כאן חסיד שהוא ביטול אמיתי מבלבל לו ביטול היש, דהנה במאכל יש ב' דברים כשאוכלין אותו למלאות תאוות לבו ה\"ה מגשם ומוריד אותו וכמו ע\"ה אסור לאכול בשר פי' ע\"ה שלהם שהיו בורים והוא מפני שהמאכל מגשם אותו, וכמו\"כ כאן ג\"כ וכמ\"ש בטן רשעים, אבל צדיק אוכל לשובע היינו שמברך תחילה וסוף והאכילה היא כדי שיוכל ללמוד ולהתפלל עי\"ז מברר אותו, דשרש המאכל הוא מתהו שקדם לתיקון שע\"י שמברר אותו נתוסף בחכ' דתיקון, וכמאמר עד דלא אכילנא בשרא דתורא לא צלינא דעתאי, וכמאמר חמרא וריחא פקחין שנתוסף לו חכ' עי\"ז, וכ\"ז במדרי' צדיק שהוא פועל בהמאכל ביטול היש, אבל חסיד שהוא ביטול אמיתי מבלבל לו המאכל.\n<b>והנה</b> זה מובן שאם הי' ביכולתו להעלות המאכל הי' יותר טוב, וזהו החכם שמתיר הנדר שמהפך את המאכל שיהי' כולו אור. וביאור הענין הנה צ\"ל",[["1044","1","<b>היתר נדרים פורחין באויר</b>: לעיל במאמרי כ\"ק אדמו\"ר מהר\"ש נדפס בתחילה ד\"ה ”וידבר משה אל ראשי המטות\" מש\"פ מטו\"מ, ואח\"ז המשכו ד\"ה ”אמנם הנה כל ענין הנדרים\" מש\"פ דברים. אולם כאן בהנחות כ\"ק אדמו\"ר מהורש\"ב נמצא רק המשך הב' מש\"פ דברים (ומאמר הראשון ד\"ה וידבר משה אל ראשי המטות, לא נרשם)."]]],[2002180328,"שרש ענין ב' אכילות דשבת וחול<sup data-n=\"1047\">2</sup>, צדיק אוכל לשובע נפשו ובטן רשעים תחסר, צדיק אוכל כו' הוא אכילה דשבת<sup data-n=\"1048\">3</sup> שאפי' אוכל למלאות תאוות לבו מ\"מ אינו מגשם, ובטן רשעים תחסר הוא אכילה דשבת* כשאוכל למלאות תאוות לבו ה\"ה מוריד את המאכל, וכמאמר מלי כריסא זינא בישא, וכתי' וישמן ישורון ויבעט שמנת עבית כשית ל' כיסוי והוא ערלת הלב שמכסה ומסתיר, וזה שא' בגמ' מלי כריסא כו' קאי על תאוות היתר. אך מהיתר בא לאיסור היום אומר לו כך ומחר כך כו', וכמו בן סורר ומורה נדון ע\"ש סופו, דאימתי הוא סורר ומורה משיאכל תרטימר בשר וישתה חצי לוג יין האיטלקי, ובאמת אינו חייב ע\"ז וכמ\"ש אמרה תורה ימות זכאי ואל ימות חייב, ה\"ה זכאי אלא מפני שסופו לבוא לכך, וכן הבא במחתרת נדון ע\"ש סופו, דבתחילה מסית אותו בדבר קטן ואח\"כ אפשר שיעשה דבר גדול, ובודאי יעשה, וכן דרכו של היצה\"ר היום אומר כו', וזהו בטן רשעים תחסר שפועל חסרון.\n<b>וביאור</b> הענין דהנה ששת יומין דחול הם מששה מדות דשרשן מבינה וכמ\"ש אם הבנים שמחה, ועל בינה אי' בינה מינה דינין מתערין בסופין. והענין דהנה בפ' שני' דק\"ש אומרים וחרה אף, וצ\"ל מה שייך זה לק\"ש אחר המס\"נ דלמס\"נ באחד או ובכל נפשך ופ' ראשונה ושני'. והענין כשמתבונן באלקות ויש לו התקשרות לאלקות אז וחרה אף על ההיפך, עמי לא התבונן, וכמו מזיעתן של החיות שהן זעין מחיל כסא נהר דינור יוצא על ראש רשעים יחול, רשעים הם דכר ונוק' דקלי', וכ\"ז מצד ההתבוננות. וזהו לעולם ירגיז אדם יצ\"ט על יצה\"ר, יצה\"ר הוא ציור הרע, דעצם כח המתאווה אינו רע דאפשר שיהי' לו אהבה לאלקות, וכבר התבאר זה כמה פעמים<sup data-n=\"1049\">4</sup>, אלא שהאדם עושה בו ציור רע, וצריך להרגיז יצ\"ט על יצה\"ר, ומהו ההרגזה ארז\"ל יזכיר לו יום המיתה, וצ\"ל מה יוצא מזה. והענין דיצה\"ר ג\"כ רוצה שלא ישמע לו וכמ\"ש בזהר משל בזונה עם בן המלך שמכריחה אותו וכוונתה שלא ישמע לה, וזהו שארז\"ל טוב זה יצ\"ט טוב מאד הוא יצה\"ר לאחר הבירור, אלא שמוכרח להסיתו בכל הדרכי' שאל\"כ אינו מקיים רצון המלך, ואם שומעין לו לא טוב לו מזה, וזהו יזכיר לו הדין שאחר המיתה, היינו שני חיי האדם שגם לו יהי' לא טוב וזהו ההרגזה, וזהו מצד ההתבוננות, וזהו בינה מינה דינין מתערין בסופא שהוא מצד ההתבוננות. וכ\"ז בבינה ששם שייך נדרים, אבל שבת מאיר מוחין דאבא לכן האכילה אינו מגשם כלל שהוא מצוה ובמצוה אינו שייך חסרון, וכ\"ש כשאוכל כדי שיוכל ללמוד ולהתפלל אינו מגשם אותו, וזהו\"ע שהחכם מתיר את הנדר שהוא בחי' חכ' ומצד בחי' חכ' אפשר להעלות המאכל.",[["1047","2","<b><a class=\"ft-cite\" href=\"#/read/torah-or/3901370291\" data-slug=\"torah-or\" data-id=\"3901370291\">צ\"ל שרש ענין ב</a>' אכילות דשבת וחול</b>: ראה גם תו\"א חיי\"ש טו, ג ואילך. בשלח סה, ב-ג. סידור עם דא\"ח רב, ג ואילך. ובכ\"מ."],["1048","3","<b>ובטן רשעים תחסר הוא אכילה דשבת</b>: נראה דצ\"ל: אכילה דחול."],["1049","4","<b>דעצם כח המתאווה אינו רע . . וכבר התבאר זה כמה פעמים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380945\" data-slug=\"likkutei-torah\" data-id=\"4001380945\">לקו\"ת חוקת נו, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380964\" data-slug=\"likkutei-torah\" data-id=\"4001380964\">דרושים לר\"ה סא, ב</a>. סה\"מ תרכ\"ט ע' קא. קכח. רסג. רסז. תרל\"ב ח\"א ע' קטו. תרל\"ג ח\"א ע' ט וע' קפ. וש\"נ."]]]]});
